    INSERT INTO public.boards (name, code) VALUES ('CUET', 'cuet')
  INSERT INTO public.curriculum_classes (board_id, label, level)
  INSERT INTO public.curriculum_subjects (curriculum_class_id, name)
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Accounting for Partnership', 'Partnership deed', 'medium', 'When a partnership deed does not exist or is silent, the Partnership Act, 1932 states that interest shall be charged/provided on _______.', '["Drawings", "Capital", "Partner’s loan", "Both (a) and (b)"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q1'),
  ('Accountancy', 'Accounting for Partnership', 'Partner''s loan', 'easy', 'If the partnership deed is silent, interest on a partner’s loan is payable at _______ per annum.', '["4%", "8%", "6%", "10%"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q2'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'Which of the following is NOT an essential feature of a partnership firm?', '["Two persons", "Lawful Business", "Written agreement between all partners", "Mutual Agency"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q3'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'easy', 'As per the Partnership Act, partnership comes into existence through ________ and not by status.', '["Business", "Law", "Contract", "Consideration"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q4'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'easy', 'The partnership agreement can be made in which of the following forms:', '["Oral", "Written", "Either", "or (b) (d) Only (b)"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q5'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on drawings', 'medium', 'When a partner withdraws a fixed amount at the end of each quarter during the year, the interest on drawings is calculated for an average period of:', '["6 months", "4.5 months", "7.5 months", "9 months"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q6'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', '______ partner invests capital and shares profits and losses without participating in the day-to-day management of the business?', '["Limited partner", "Active partner", "Secret partner", "Sleeping partner"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q7'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'medium', 'Under the fixed capital method, interest on capital is recorded in the credit of ______.', '["Capital account", "Current account", "Profit and Loss account", "Profit and Loss Appropriation account"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q8'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'Identify the statements that correctly describe the features of a partnership firm.', '["Two or more persons carry on a common business under an agreement.", "Partners share profits and losses of the business.", "Business is carried by all or any of them acting for all as an agent.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q9'),
  ('Accountancy', 'Accounting for Partnership', 'Types of partners', 'medium', 'Which of the following correctly describes an Ostensible Partner''', '["Does not contribute any capital but receives a share of profit for lending his name to the firm.", "Contributes very little capital but receives equal profit.", "Does not contribute any capital and, without having any real interest in the business, lends his name to the firm.", "Contributes the maximum capital to the business."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q10'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on drawings', 'hard', 'A and B are partners in a firm sharing profits in the ratio of 4:1. The profit for the year ended on 31st March 2026 was distributed among A and B without having adjusted the interest on drawings charged from them @10% per annum. The drawings of A and B are ₹30,000 and ₹20,000 respectively. While passing the adjustment entry, the capital account of A will be ______ by _____.', '["Credited, ₹1,500", "Credited, ₹500", "Debited, ₹500", "Debited, ₹1,500"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q11'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'In a partnership firm, any act done by a partner in the ordinary course of business is:', '["Obligatory and binding on all the partners of the firm", "Binding on all partners except the partner who performs the act", "Binding only on the partner who performs the act", "Not binding on any of the partners"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q12'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'Articles of partnership are commonly referred to as:', '["Partnership prospectus", "Partnership deed", "Principles of partnership", "None of the above PRACTICE CORNER =====PAGE 9===== Accounting for Partnership 5"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q13'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'Which of the following items is NOT recorded on the debit side of a partner’s current account?', '["Drawings out of Profit", "Interest charged on drawings", "Salary payable to the partner", "None of the above"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q14'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'Aadh is a partner in a firm maintaining a fixed capital system. During the financial year 2025–26, he withdrew ₹1,70,000 for personal use. Which of the following will be the correct journal entry for this withdrawal?', '["Drawings A/c Dr. ₹1,70,000 To Aadh’s Capital A/c ₹1,70,000", "Drawings A/c Dr. ₹1,70,000 To Aadh’s Current A/c ₹1,70,000", "Aadh’s Capital A/c Dr. ₹1,70,000 To Drawings A/c ₹1,70,000", "Aadh’s Current A/c Dr. ₹1,70,000 To Drawings A/c ₹1,70,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q15'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'Which of the following items is NOT entered in a partner’s Current Account?', '["Interest on capital", "Partner’s commission", "Interest on drawings", "Additional capital brought by a partner"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q16'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on drawings', 'hard', 'X, Y and Z are partners sharing profits in the ratio of 2:2:1. The profit for the year 2025-26 of ₹60,000 was divided equally without providing for the following: A. 10% of the net profit was to be transferred to the General Reserve. B. Interest on capital of ₹10,000, ₹12,000 and ₹18,000, respectively. C. Interest on drawings of ₹3,000, ₹2,000, ₹1,000, respectively. Which of the following is the correct entry for the capital adjustment of X, Y and Z?', '["General Reserve A/c Dr 6,000 Z’s Capital A/c Dr 1,000 To X’s Capital A/c 5,000 To Y’s Capital A/c 2,000", "Y’s Capital A/c Dr 5,000 Z’s Capital A/c Dr 2,000 To X’s Capital A/c 7,000", "X’s Capital A/c Dr 5,000 Y’s Capital A/c Dr 2,000 To Z’s Capital A/c 7,000", "X’s Capital A/c Dr 5,000 Y’s Capital A/c Dr 2,000 To Z’s Capital A/c 1,000 To General Reserve A/c 6,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q17'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'Which of the following items is NOT adjusted through the Profit and Loss Appropriation Account?', '["Interest on partner’s drawings", "Interest on partner’s loan", "Partner’s salary", "Partner’s Commission"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q18'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'easy', 'Identify the odd one out.', '["Rent to a partner", "Interest on capital", "Depreciation", "Interest on partner’s loan"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q20'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'A, B, and C are architects, who entered into a partnership agreement and decided to share profits in the ratio of 2:2:1. B guaranteed that the fees earned by him will not be less than ₹80,000 in any year. C is guaranteed that his minimum share in profit will not be less than ₹25,000 in any year and the deficiency, if any, will be borne by A. The profit for the year ended on 31st March 2026 amounted to ₹1,10,000 (fees earned by B during the year was ₹60,000). The deficiency borne by A will be:', '["₹3,000", "Nil", "₹7,000", "₹5,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q21'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'A and B are partners in a firm sharing profits in the ratio of 1:1. The fixed capitals of A and B are ₹3,00,000 and ₹4,00,000 respectively. They are entitled to receive interest on capital @10% per annum. The profit for the year ended on 31st March 2026 was ₹56,000, which was distributed equally among A and B without providing for the interest on capital. The past adjustment entry for adjusting the capitals will be:', '["A’s Capital A/c Dr 4,000 To B’s Capital A/c 4,000", "B’s Capital A/c Dr 4,000 To A’s Capital A/c 4,000 =====PAGE 10===== CUET UG Accountancy 6", "A’s Current A/c Dr 2,000 To B’s Current A/c 2,000", "A’s Current A/c Dr 4,000 To B’s Current A/c 4,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q22'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'medium', 'The capital account of the partnership firm of P and Q are maintained under Fixed Capital Method. Which of the following will NOT affect the capital balance of the partners? (i) Additional capital introduced by them (ii) Interest on Capital (iii) Permanent withdrawal of Capital (iv) Share in Profits', '["Only (i) and (iii)", "Only (ii)", "Only (ii) and (iv)", "Only (iv)"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q23'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'easy', 'The interest on capital is allowed on:', '["Opening Capital", "Effective Capital", "Closing Capital", "Additional Capital"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q24'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on drawings', 'hard', 'Anil, a partner, withdrew same amount at the beginning of every month in the year 2025-26, and his interest on drawings @6% per annum amounted to ₹1,950. Determine his monthly drawings.', '["₹72,000", "₹6,000", "₹5,000", "₹60,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q25'),
  ('Accountancy', 'Accounting for Partnership', 'Profit sharing', 'hard', 'When the profits are guaranteed by the partners in their profit-sharing ratio, which of the following is NOT true?', '["Amount guaranteed to a partner is transferred to Profit and Loss Appropriation A/c.", "The remaining profit is distributed among the remaining partners in their profit-sharing ratio.", "Guaranteed amount is calculated according to his share.", "All of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q26'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'A partner who invests capital in the business but does not participate in managing the business is called:', '["Nominal Partner", "Partner by Estoppel", "Sleeping Partner", "Minor Partner"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q27'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'X and Y are partners in a firm, sharing profits in the ratio of 3:2. Their capitals as on 1st April 2025 are: ₹3,00,000 and ₹3,00,000 respectively. They are entitled to receive interest on capital @10% per annum. The profit for the year ended on 31st March 2026 of ₹40,000 was distributed equally without providing for the interest on capital. What will be the correct entry for the past adjustment?', '["X’s Capital A/c Dr 6,000 To Y’s Capital A/c 6,000", "X’s Capital A/c Dr 4,000 To Y’s Capital A/c 4,000", "Y’s Capital A/c Dr 4,000 To X’s Capital A/c 4,000", "No adjustment entry is required."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q28'),
  ('Accountancy', 'Accounting for Partnership', 'Partner''s loan', 'hard', 'A and B are partners in a firm. A has advanced a loan of ₹1,20,000 to the firm on 1st December 2025, and the books are closed on 31st March every year. There is no partnership deed. A claims interest on the loan @10% per annum. The interest on A’s loan will be:', '["₹4,000", "₹7,200", "₹12,000", "₹2,400"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q29'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'X and Y are partners sharing profit in the ratio of 1:2. Z was the manager who received the salary of ₹6,000 per month in addition to a commission of 10% on net profit after charging his salary and commission. Total remuneration to Z amounted to ₹1,02,000. Profit for the year before charging salary and commission was:', '["₹6,00,000", "₹6,60,000", "₹6,72,000", "₹4,02,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q30'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'X and Y are partners in a firm sharing profits and losses equally. As on 1st April 2025, their capitals were ₹2,40,000 and ₹2,70,000 respectively. On 1st October 2025, they decided that the total capital of the firm should be ₹5,00,000, which will be contributed equally by them. According to the deed, they are entitled to receive interest on capital @5% per annum. What will be the interest on capital of X and Y for the year ending on 31st March 2026.', '["X - ₹12,000 and Y - ₹13,500", "X - ₹12,500 and Y - ₹12,500", "X - ₹12,250 and Y - ₹13,000", "X - ₹13,000 and Y - ₹12,250"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q31');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'P and Q are partners in a firm and their fixed capitals are ₹30,000 and ₹50,000 as on 31st March 2026. During the year 2025-26 the firm earned a profit of ₹80,000. The partners are entitled to receive interest @10% per annum on their capital. They share profits equally. The entry for providing interest on capital will be:', '["Interest on Capital A/c Dr 16000 To P’s Capital A/c 7000 To Q’s Capital A/c 9000", "Interest on Capital A/c Dr 16000 To P’s Current A/c 7000 To Q’s Current A/c 9000 =====PAGE 11===== Accounting for Partnership 7", "Interest on Capital A/c Dr 8000 To P’s Current A/c 3000 To Q’s Current A/c 5000", "Interest on Capital A/c Dr 8000 To P’s Capital A/c 3000 To Q’s Capital A/c 5000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q32'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'X and Y are partners in the ratio of 3: 2. Their capitals are ₹1,00,000 and ₹50,000, respectively. Interest on capital is allowed @ 8% p.a. The firm earned a profit of ₹8,000 for the year ended 31st March 2023. As per the partnership agreement, interest on capital is treated as a charge on profits. Interest on Capital of X will be:', '["₹8000", "₹5333", "₹6000", "₹5000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q33'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'A, B and C are partners sharing profits in the ratio of 2:2:1, and their fixed capitals are of ₹3,00,000, ₹2,00,000 and ₹1,00,000, respectively. After closing the accounts for the year ending 31st March 2026, it was discovered that interest on capital was provided @ 12% p.a. instead of 10% p.a. In the adjustment entry:', '["Cr. A ₹ 1,200 ; Dr. B ₹ 800 and Dr. C ₹ 400", "Dr. A ₹ 1,200 ; Cr. B ₹ 800 and Cr. C ₹ 400", "Cr. A ₹ 800 ; Cr. B ₹ 400 and Dr. C ₹ 1,200", "Dr. A ₹ 800 ; Dr. B ₹ 400 and Cr. C ₹ 1,200"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q34'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'medium', 'If the firm’s asset are not sufficient to pay off the firm’s debts, the personal assets of the partners is used to pay off the firm’s debts. Which feature of partnership is being highlighted?', '["Mutual Agency", "Agreement", "Separate Entity", "Unlimited Liability"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q35'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'X, Y and Z are partners in a firm sharing profits in the ratio of 5:4:1. Z is guaranteed that his share of profit will not be less than ₹80,000. Any deficiency will be borne by X and Y in the ratio of 3:2. Firm’s profit was ₹5,60,000. How much deficiency will be borne by Y:', '["₹2,14,400", "₹14,400", "₹2,09,600", "₹9,600"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q36'),
  ('Accountancy', 'Accounting for Partnership', 'Interest on capital', 'hard', 'P and Q are partners sharing profits in the ratio of 2:1 and they have fixed capitals of ₹90,000 and ₹60,000 respectively. After closing the accounts for the year ending 31st March, 2026 it was discovered that interest on capitals was provided @ 6% instead of 8% p.a. In the adjusting entry:', '["P will be credited by ₹1,800 and Q will be credited by ₹1,200", "P will be debited by ₹200 and Q will be credited by ₹200.", "P will be credited by ₹200 and Q will be debited by ₹200.", "P will be debited by ₹1,800 and Q will be debited by ₹1,200 ."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q37'),
  ('Accountancy', 'Accounting for Partnership', 'Partnership deed', 'medium', 'Which of the following is NOT included in the partnership deed?', '["Profit sharing ratio of the partners.", "Rules regarding the operation of the bank account of the firm.", "Name and address of the manager of the firm", "Capital contribution by each partner."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q38'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'X, Y and Z are partners in the ratio of 6:4:1. In the firm, X has guaranteed Z for his minimum profit of ₹15,000. The firm’s profit was ₹99,000. In the firm’s profit, X’s share will be:', '["₹30,000", "₹15,000", "₹48,000", "₹45,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q39'),
  ('Accountancy', 'Accounting for Partnership', 'Accounting for Partnership', 'hard', 'Abhay, an equal partner in a firm, was guaranteed that his share in profits would not be less than ₹30,000 p.a. Deficiency, if any, was to be borne by other partners, Binay and Samay, in the ratio of 3:2. For the year ended 31st March, 2026, the firm incurred a loss of ₹90,000. What amount of loss will be transferred to Binay’s Capital A/c?', '["₹30,000", "₹66,000", "₹45,000", "₹60,000 Assertion – Reason – Based Questions Given below are two statements, one labelled as Assertion (A) and the other labelled as Reason (R). Read the statements and choose the correct option. (a) Both A and R are true, and R is the correct explanation of A. (b) Both A and R are true, but R is not the correct explanation of A. (c) A is true, but R is false. (d) A is false, but R is true."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Partnership · Q40'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'X, Y and Z were partners sharing profits in the ratio 2 : 3 : 4 with effect from 1st April, 2025 they agreed to share profits in the ratio 3 : 4 : 5. The sacrificing partner is ______ and his sacrificed share is ______.', '["X, 1 36", "Y, 1 36", "Z, 1 36", "Y, 1 6"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q1'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'The ratio in which a partner surrenders his share in favour of another partner(s) is known as:', '["New profit-sharing ratio", "Old profit-sharing ratio", "Sacrificing Ratio", "Gaining Ratio"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q2'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'A, B and C are partners with a profit-sharing ratio of 2 : 2 : 1. They agreed to share future profits in the ratio of 7 : 5 : 3. The Goodwill appeared in that Balance Sheet at ₹15,000. What amount will be debited to the capital accounts of the partners for writing off the goodwill?', '["₹6000, ₹6000, and ₹3000 respectively", "₹7000, ₹5000, and ₹3000 respectively", "₹1000 to A’s Capital A/c", "₹1000 to B’s Capital A/c"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q3'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'P , Q, and R are partners sharing profits in the ratio of 2 : 3 : 4. They decided to share future profits in the ratio of 3 : 4 : 5. The gained and sacrificed share by each partner will be:', '["P has gained 1 36 , and R has sacrificed 1 36", "P has gained 1 6 , and R has sacrificed 1 6", "P has sacrificed 1 36 , and Q has gained 1 36", "P has sacrificed 1 3 , and Q has gained 1 3"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q4'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'X and Y are partners sharing profits in the ratio of 3 : 2 before they changed the profit-sharing ratio to equal. The Balance Sheet as on the date of change in profit-sharing ratio showed a debit balance in Profit & Loss Account of ₹50,000. The balance of ₹50,000:', '["Will be shown in the balance sheet of the reconstituted firm.", "Will be credited to the capital accounts of X and Y in the ratio of 3 : 2", "Will be credited to the capital accounts of X and Y in the ratio of 1 : 1", "Will be debited to the capital accounts of X and Y in the ratio of 3 : 2"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q5'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'P and Q are partners in a firm sharing profits in the ratio of 3 : 1 on 1-4-2025; they decided to share profits equally in future. The goodwill of the firm was valued on the basis of 2 years’ purchase of the last three years’ average profits. The profits of the last three years were: ₹92,000, ₹1,20,000, and ₹86,000 (including abnormal loss of ₹20,000). The capital A/c of ______ will be debited by _____ for adjusting goodwill.', '["P , ₹2,12,000", "Q, ₹2,12,000", "P , ₹53,000", "Q, ₹53,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q6'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'On the date of change in the profit-sharing ratio among the partners, their Balance Sheet had: Investment Fluctuation Fund: ₹50,000 Investment: ₹1,20,000 On reconstitution, the market value of the investment was ₹1,00,000. What amount will be debited to the Revaluation A/c?', '["₹20,000", "₹30,000", "₹70,000", "Nil"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q7'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'In case of a change in the profit-sharing ratio, the gaining partner must compensate the sacrificing partners by paying the proportional amount of:', '["Capital", "Goodwill", "Accumulated Profits and Reserves", "Gain on Revaluation"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q8'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'A, B and C are equal partners in a firm. On 1st April 2025, they decided that they would share the future profits in the ratio of 3 : 2 : 1. Which partner is neither gaining nor sacrificing?', '["A", "B", "C", "None of them PRACTICE CORNER =====PAGE 32===== CUET UG Accountancy 28"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q9'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'The goodwill of a firm is ₹54,000. It was valued at 4 years’ purchase of super profits. The capital employed by the firm is ₹2,00,000, and the normal rate of return is 10%. The average profit of the firm is:', '["₹47,000", "₹33,500", "₹30,000", "₹24,500"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q10'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'easy', 'The ratio in which a partner receives an increase in his share of profits is known as:', '["New Ratio", "Sacrificing Ratio", "Old Ratio", "Gaining Ratio"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q11'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'E, F and G are partners sharing profits in 3:4:2 ratio. Their fixed capitals are ₹70,000, ₹40,000 and ₹80,000 respectively. It is now decided that the total capital of the firm should be ₹3,60,000 and should be in the profit-sharing ratio of the partner. Calculate the amount of capital to be introduced or withdrawn by E, F, and G.', '["E will introduce ₹50,000, F will introduce ₹1,20,000", "E will introduce ₹50,000, F will withdraw ₹1,20,000", "E will withdraw ₹50,000, F will introduce ₹1,20,000", "E will withdraw ₹50,000, F will withdraw ₹1,20,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q12'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'A and B are partners sharing profits equally. From 1st April 2025, they decided to share profits in the ratio of 3:2. The goodwill appeared in the balance sheet at ₹30,000 on the given date. Which of the given statements is correct in this case?', '["Goodwill will be written off in the old ratio.", "Goodwill will be written off in the new ratio.", "The capital account of the sacrificing partner will be credited by his share of goodwill.", "Both (a) and (c)"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q13'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'Assets are revalued, and liabilities are reassessed at the time of a change in profit-sharing ratio so that:', '["They could be shown at present values", "The gaining partner is not to put to an advantage & the sacrificing partner is not to put to a disadvantage & vice versa", "Both of the above", "None of these"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q16'),
  ('Accountancy', 'Reconstitution of Partnership', 'Revaluation', 'hard', 'Revaluation account is prepared in case of:', '["Increase or decrease in the value of assets", "Increase or decrease in the value of liabilities", "Change in the value of assets or liabilities", "Distribution of accumulated profits and reserves"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q17'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'Capital employed in a business is ₹15,00,000. The average profit of the last few years is ₹5,00,000, and the normal rate of profit is 20%. The value of goodwill as per the capitalisation of average profit method will be:', '["₹20,00,000", "₹15,00,000", "₹30,00,000", "₹10,00,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q18'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'In case of change in profit sharing, the accumulated profit and losses are generally:', '["Shared by all partners in new ratio", "Shared by all partners in old ratio", "Adjusted between gaining and sacrificing partner", "Transferred to Revaluation A/c"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q19'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'On the date of the change in the profit-sharing ratio among the partners, their Balance Sheet had: Investment Fluctuation Fund: ₹50,000 Investment: ₹1,20,000 The market value of the investment on the date of reconstitution was ₹1,50,000 =====PAGE 33===== Reconstitution of Partnership 29 Which of the following is the correct journal entry for the above?', '["Investment A/c 30,000 To Revaluation A/c 30,000", "Investment Fluctuation Fund A/c 50,000 To Investment A/c 30,000 To All Partners’ Capital A/c 20,000 (in old ratio)", "Investment Fluctuation Fund A/c 50,000 To All Partners’ Capital A/c 50,000 (in old ratio)", "Both (a) and (c)"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q20'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'X, Y and Z are partners sharing profits in the ratio of 8:5:3. With effect from 1st April 2025, they decide to share future profits in the ratio of 5:6:5. Who will gain and how much?', '["Y, 2 16 and Z, 1 16", "Y, 1 16 and Z, 2 16", "X, 1 16 and Z, 2 16", "Only Z, 1 16"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q21'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'A, B and C are partners in a firm sharing profits in the ratio of 2 : 2 : 1. Which of the following incidents will result in the reconstitution of the firm?', '["They decide to share profits equally.", "They admit D as a partner in the firm.", "C decides to retire from the firm.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q22'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'X, Y and Z are partners sharing profits in the ratio of 8 : 5 : 3. With effect from 1st April 2025, they decide to share future profits in the ratio of 5 : 6 : 5. Who will sacrifice and how much?', '["Only X by 3 16", "Y and Z by 1 16 and 2 16 , respectively", "X and Z by 1 16 and 2 16 , respectively", "Only Z by 1 16"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q23');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'Profits of the last three years were ₹12,000, ₹26,000 and ₹4,000. The value of goodwill at 2.5 years’ purchase of average profit will be:', '["₹14,000", "₹35,000", "₹19,000", "₹38,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q24'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'medium', 'Which of the following situations requires the valuation of goodwill?', '["Change in profit-sharing ratio", "Admission of a new partner", "Retirement or Death of an existing partner", "All of these"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q25'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'On the date of change in the profit-sharing ratio among the partners, their Balance Sheet had: Investment Fluctuation Fund: ₹20,000 Investment: ₹1,20,000 On reconstitution, the market value of the investment was ₹90,000. What amount will be debited to the Revaluation A/c?', '["₹90,000", "₹30,000", "₹10,000", "₹20,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q26'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'A, B and C are partners sharing profits in the ratio of 5 : 3 : 2. They decided to share the future profits in the ratio of 2 : 2 : 1. The gained share and sacrificed share of partners are:', '["A gained 1 10 and B sacrificed 1 10", "A gained 1 10 and C sacrificed 1 10", "A sacrificed 1 10 and B gained 1 10", "A sacrificed 1 10 and C gained 1 10"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q27'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'A and B are partners sharing profits in the ratio of 3:2. They decided to share future profits equally. On that day, the debit balance in P&L A/c was ₹30,000, and the General Reserve was ₹20,000. They decided not to distribute the reserves and profits. For adjusting the capitals, A’s Capital A/c will be _______ (debited/ credited) by _______.', '["Debited, ₹10,000", "Debited, ₹1,000", "Credited, ₹10,000", "Credited, ₹1,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q28'),
  ('Accountancy', 'Reconstitution of Partnership', 'Admission of partner', 'medium', 'Any change in the relationship of existing partners which ends the existing partnership and a new partnership is made is called:', '["Revaluation of partnership", "Dissolution of the firm", "Reconstitution of partnership", "None of the above"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q29'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'P , Q and R are partners sharing profits in the ratio of 4:3:2. On 1st April 2026, they decided to share future profits equally. On that date, the goodwill appeared in the books at ₹36,000, and the goodwill was valued at ₹54,000. The capital A/c of P will be increased or decreased by what amount?', '["Increased by ₹14000", "Decreased by ₹6000", "Increased by ₹8000", "Decreased by ₹10000 =====PAGE 34===== CUET UG Accountancy 30"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q30'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'In case of a change in profit-sharing ratio, the unrecorded asset will be:', '["Debited to Revaluation A/c", "Credited to Revaluation A/c", "Not Recorded at all", "Credited to Respective Asset A/c"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q31'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'P and Q are partners sharing profits in the ratio of 4:1. They agreed to share future profits in the ratio 1:1. The goodwill of the firm was valued as ₹30,000. What amount will be credited or debited to P?', '["Credited, ₹9000", "Credited, ₹30,000", "Debited, ₹9000", "Debited, ₹30,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q32'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'X, Y and Z are partners sharing profits in the ratio of 3 : 2 : 1. In future, Z agreed to acquire 1 5 th share of X and 1 5 th share from Y. The new profit-sharing ratio of X, Y and Z will be:', '["7 : 2 : 6", "6 : 2 : 7", "2 : 6 : 7", "6 : 7 : 2"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q33'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'The goodwill of a firm valued by capitalisation method is ₹1,50,000. The Capital Employed is 20,00,000 and normal rate of return is 10%. The average profit will be:', '["₹15,000", "₹20,000", "₹35,000", "₹25,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q34'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'easy', 'Which of the following affects goodwill?', '["Nature of Business", "Trend of Profits", "Favourable Location", "All of these"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q35'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'Goodwill of the firm was valued on the basis of 2 years purchase of the last three years average profits. The profits of last three years were: 2016-17 - ₹90,000 2017-18 - ₹1,30,000 2018-19 - ₹86,000 During the year 2018-19, there was a loss of ₹20,000 due to fire, which was not accounted for while calculating the profit. Goodwill of the firm will be:', '["₹2,04,000", "₹1,02,000", "₹2,17,333", "₹2,40,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q36'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'The new profit-sharing ratio of A, B and C is 2 : 1 : 1. A and C have gained 1 18 and 1 36 respectively, and B has sacrificed 1 12 . The old ratio of A, B and C was:', '["2 : 1 : 1", "4 : 3 : 2", "5 : 3 : 2", "2 : 2 : 1"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q37'),
  ('Accountancy', 'Reconstitution of Partnership', 'Revaluation', 'hard', 'The book value of the building is ₹50,000. On revaluation, it is increased to ₹60,000. Which of the following accounts will be debited and by how much?', '["Revaluation A/c by ₹10,000", "Building A/c by ₹10,000", "Revaluation A/c by ₹60,000", "Building A/c by ₹60,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q38'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'Average profit for the last 5 years is ₹60,000. The normal rate of return is 10%. Capital Employed is ₹5,00,000 The value of goodwill as per the capitalisation of the Super Profit method will be:', '["₹10,000", "₹3,00,000", "₹1,00,000", "₹5,00,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q39'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'As per AS 26, if no consideration is paid for acquiring goodwill:', '["It will be shown in books at full value", "It will not be shown in books", "It will be shown in books at the value decided by the partners", "It will be shown in books at 50% of its value"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q40'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'At the time of valuation of goodwill in the year 2024- 25, it was identified that the travel expense of ₹8000 had been wrongly capitalised at the beginning of the year 2020-21 and a depreciation of 10% per annum is charged on it on a written down value method. The net profit for the year 2022-23 is ₹80,000 before making any adjustment regarding the above. The amount of profit to be used for calculation of goodwill for the year 2022-23 will be:', '["₹88,000", "₹72,800", "₹72,000", "₹80,648"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q42'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'The goodwill valued 2.5 times of the average profit of 5 years is ₹60,000. The profit of the first 4 years were - ₹25,000; ₹45,000; ₹35,000 and ₹30,000 respectively. In the 5th year there was a _____ (profit/loss) of.', '["Profit, ₹15,000", "Loss, ₹15,000", "Profit, ₹20,000", "Loss, ₹20,000 =====PAGE 35===== Reconstitution of Partnership 31"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q43'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'Goodwill of the firm is valued at ₹4,50,000 at 3 years’ purchase of super profit. If the normal rate of return was 10% and actual profits amounted to ₹1,75,000. The capital employed will be:', '["₹5,00,000", "₹2,50,000", "₹7,50,000", "₹10,00,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q44'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'The profits for 3 years are given below: 1st Year = ₹60,000 (including abnormal gain of ₹20,000) 2nd Year = ₹40,000 (after charging abnormal loss of ₹30,000) 3rd Year = ₹ 35,000 (wages paid ₹5000 for installation of machinery was debited while calculating profit) The goodwill is valued at 1.5 times of the average profit of last 3 yea₹ The value of goodwill is:', '["₹75,000", "₹65,000", "₹25,000", "₹12,500"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q45'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'easy', 'Which of the following is true about goodwill?', '["It is an Intangible Asset", "It is a Tangible Asset", "It is a Current Asset", "It is a Fictitious Asset"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q46'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'medium', 'Goodwill can be defined as:', '["The capitalised value attached to the differential profit capacity of a business", "The present value of a firm’s anticipated excess earnings", "Both", "and (b) (d) None of the above"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q47'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'medium', 'Which of the following steps is not required for calculating goodwill by Capitalisation of Super Profit Method?', '["Calculation of Average and Normal Profit", "Calculation of Capitalised Value of Average Profit", "Calculation of Super Profit", "Dividing Super Profit by Normal Rate of Return"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q48'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'medium', 'Capitalised Value of Average Profit =', '["Capital employed x Normal Rate of Return", "Average Profit x Normal Rate of Return", "Capital employed / Normal Rate of Return", "Average Profit / Normal Rate of Return"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q49'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'easy', 'Q is neither gaining nor sacrificing', '["1, 2, and 5", "3 and 5", "4 and 6", "3 and 6"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q6'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'G, V and S are partners. Their new profit-sharing ratio is 2 : 1 : 1, where G sacrifices 1 3 and V and S gain 1 6 each. The old profit-sharing ratio of G, V and S will be:', '["1 : 1 : 1", "10 : 1 : 1", "2 : 2 : 1", "8 : 3 : 1"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q51'),
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'hard', 'A and B are partners in a firm sharing profits and losses in the ratio of 5 : 1, they decided to share future profits equally. On that date, the book value of Machinery was ₹ 40,000, which was found to be overvalued by 25%. The value of machinery to be shown in the new Balance Sheet will be:', '["₹ 50,000", "₹ 10,000", "₹ 8,000", "₹ 32,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q52'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'A, B and C are partners in a firm sharing profits and losses in the ratio of 2: 2: 1. On 1st April 2023, they decided to change their profit-sharing ratio to 5 : 3: 2. On that date, the debit balance of Profit & Loss A/c was ₹ 30,000. The partners decided not to close the books, in such case, the Capital A/c of ______ will be debited by _____.', '["B, ₹ 3000", "A, ₹ 3000", "A and B, ₹ 1500 each", "C, ₹ 3000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q53'),
  ('Accountancy', 'Reconstitution of Partnership', 'Profit sharing', 'hard', 'R and M were partners in a firm sharing profits or losses equally. With effect from 1st April, 2025, they agreed to share profits in the ratio of 4 : 3. Due to a change in profit sharing ratio, M’s gain or sacrifice will be:', '["Gain 1 14", "Sacrifice 1 14", "Gain 4 7", "Sacrifice 3 7"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q54');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Reconstitution of Partnership', 'Reconstitution of Partnership', 'medium', 'Which of the following is shown in the Balance Sheet?', '["Purchased Goodwill", "Self-Generated Goodwill", "Both", "None of these =====PAGE 36===== CUET UG Accountancy 32"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q55'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'medium', 'Which one of the following is NOT a characteristic of goodwill? ( i) It is a tangible asset. ( ii) It is a fictitious asset. ( iii) It is an attractive force that the old customers will resort to the old place. ( iv) It has a fixed value.', '["only (iii)", "(i) and (ii)", "All except (iii)", "All of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q56'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'hard', 'The weighted average method of goodwill valuation is used in which of the following cases:', '["When there is an increasing trend of profits.", "When there is a decreasing trend of profits.", "When profits show no trend.", "Both (a) and (b)"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q58'),
  ('Accountancy', 'Reconstitution of Partnership', 'Goodwill', 'medium', 'While calculating goodwill using the Weighted Average Profit Method, the maximum weight is assigned to:', '["The first year", "The last year", "The middle year", "Any year"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Reconstitution of Partnership · Q59'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'X and Y are partners sharing profits in the ratio of 2:1, they admit Z as a partner and their profit sharing ratio becomes 4:3:2. Z brings ₹15000 as premium for goodwill. The premium for goodwill will be credited to:', '["X and Y in 2:1", "X and Y in 4:3", "Only X", "Only Y"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q1'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'Rani, Maharani and Laxmi were partners in a firm sharing profits and losses in the ratio of 3:3:2. On 1st April 2025, they admitted Reena as a new partner for 1/5th share in the profits of the firm. Reena acquired her share from Rani and Maharani in the ratio of 3:2. The new profit-sharing ratio between Rani, Maharani, Laxmi and Reena will be:', '["51:59:40:50", "51:59:50:40", "59:51:50:40", "40:51:59:50"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q2'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'A, B and C were partners in a firm sharing profits and losses in the ratio of 3 : 2 : 1. On 1st April, 2024, D was admitted as a partner in the firm. The new profit sharing ratio was 2 : 2 : 1 : 1. The sacrificed share of A was :', '["1 th6", "NIL", "2 th6", "3 th6"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q3'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'A, B and C are partners sharing profit and losses in the ratio of 5:3:2. They admitted D, it was agreed that the ratio between C and D will be the same as between A and B. The new ratio of A, B, C and D will be:', '["5:3:5:3", "25:15:10:6", "5:3:3:5", "25:15:6:10"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q4'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'A and B were equal partners in a partnership. They admitted C for 1/4th share. He acquired his share equally from A and B. Which of the following statements is/are true? ( i) The sacrificing ratio of A and B is 1:1. ( ii) C acquired 1/8 from B. ( iii) The new profit sharing ratio of A, B and C will be 11: 6: 5.', '["( i) and (ii)", "only (i)", "only (ii)", "( i), (ii) and (iii)"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q5'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'hard', 'Mohit and Shobhit were partners in a firm sharing profits in the ratio of 3:2. Namit was admitted for 1/6th share in the profits of the firm. At the time of admission, Workmen’s Compensation Reserve appeared in the Balance Sheet of the firm at ₹64,000. The claim on account of workmen’s compensation was determined at ₹80,000. The excess amount of claim will be:', '["Credited to Revaluation Account", "Credited to the Capital Accounts of old partners", "Debited to Revaluation Account", "Debited to the Capital Accounts of all partners"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q6'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'medium', 'The premium for goodwill brought by the new partner is shared by:', '["Old partners in old ratio", "Old partners in new ratio", "Old partners in gaining ratio", "Sacrificing partners in sacrificing ratio"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q7'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'medium', 'At the time of admission of a partner, the unrecorded liability is:', '["Debited to the respective Liability A/c.", "Debited to the Capital A/c.", "Credited to the respective Liability A/c.", "Credited to the Revaluation A/c."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q8'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'hard', 'P and Q are partner’s sharing profit in the ratio of 2:3. R admitted for 1/4 share, half of which was given by P and the remaining was contributed by Q. Goodwill of the firm is valued at ₹40,000. How much of the goodwill will be credited to the old partner’s capital account ?', '["₹2,500 each", "₹5,000 each", "₹20,000 each", "None of the above."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q9'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'A and B are partners in a firm sharing profits in the ratio of 3:2. On 1st April 2025, they decided to admit C for 1/6th share in the profits. On that date their balance sheet had a general reserve of ₹30,000. Which of the following is the correct treatment of the general reserve?', '["The capital accounts of A and B will be credited by ₹18,000 and ₹12,000, respectively.", "The capital accounts of A and B will be debited by ₹18,000 and ₹12,000, respectively.", "The capital accounts of A, B, and C will be credited by ₹15,000, ₹10,000 and ₹5,000, respectively.", "The capital accounts of A, B, and C will be debited by ₹15,000, ₹10,000 and ₹5,000, respectively. PRACTICE CORNER =====PAGE 61===== Admission of a New Partner 57"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q10'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'medium', 'On admission of a new partner,', '["The old firm is dissolved", "Old partnership is dissolved", "Both firm and partnership is dissolved", "Neither firm nor partnership is dissolved"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q11'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'hard', 'Which of the following adjustments are made at the time of admission of a partner?', '["Calculation of new and sacrificing ratio", "Adjustment of Accumulated Profits and Reserves", "Valuation and adjustment of Goodwill", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q12'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'easy', 'On admission of a new partner, we calculate:', '["New Ratio", "Sacrificing Ratio", "Gaining Ratio", "Both new and sacrificing ratio"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q13'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'medium', 'For admitting a new partner in the firm:', '["Consent of all partners is required.", "Consent of a partner having maximum share in profit is required.", "Consent of majority of the partners is required.", "Consent of any one of the old partners is required."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q14'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'A, B and C are the partners in a firm sharing profits in the ratio of 1:1:1. They admitted D for 1/5th share in profit, which he gets entirely from B. The new ratio will be:', '["5:5:3:2", "5:5:2:3", "5:3:5:2", "5:2:5:3"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q15'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'P , Q and R are partners sharing profits in the ratio of 3:2:1. They admit S as a new partner for 1/4th share in the future profits and Q decided to retain his old share. P and R decided to share the future profits equally. The new profit sharing ratio of P , Q, R and S will be:', '["3:2:1:1", "5:8:5:6", "1:2:1:1", "5:5:5:6"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q16'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'P and Q are partners sharing profits in the ratio of 2:1, they admitted R as a new partner for 20% of share in profits and losses. Determine the new profit sharing ratio.', '["4:4:3", "8:4:3", "8:3:3", "2:1:1"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q17'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'A and B are partners sharing profit and losses in the ratio of 3:2. They admitted C. it was agreed that the ratio between B and C will be same as between A and B. The new ratio of A, B and C will be:', '["3:2:3", "9:4:6", "9:6:4", "3:2:1"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q18'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'A and B were partners in a firm sharing profits in the ratio of 5:3. C is admitted for 1/10th share half of which was gifted by A and remaining was taken by C equally from A & B, find the new ratio.', '["5:3:2", "5:2:3", "11:7:2", "12:5:3"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q19'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'hard', 'A and B are partners in a firm sharing profits and losses in the ratio of 3:2. They admitted C as a new partner in the firm for 1/5th share of profits. He brings in ₹30,000 as capital and ₹10,000 as his share of goodwill. The premium for goodwill will be credited to the capital accounts of A and B in:', '["Old Ratio", "New Ratio", "Sacrificing Ratio", "Gaining Ratio"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q20'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'medium', 'At the time of admission of a new partner the goodwill appearing in the books will be:', '["Credited to the capital A/c of old partners in old ratio", "Debited to the capital A/c of old partners in old ratio", "Credited to the capital A/c of old partners in sacrificing ratio", "Debited to the capital A/c of old partners in sacrificing ratio"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q21'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'A and B are partners sharing profits and losses in the ratio of 2:1. C is admitted and the profit-sharing ratio becomes 4:3:2. Goodwill is valued at ₹94,500. C brings required goodwill in cash. The premium for goodwill will be credited to A and B as:', '["₹14,000 and ₹7,000 respectively", "₹1,05,000 each", "₹21,000 to A only", "₹21,000 to B only"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q22'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'A and B were partners sharing profits in the ratio of 3:1. C was admitted for 1/5th share in the profits. C brought ₹30,000 as capital and ₹12,000 as his share of goodwill. The premium for goodwill was credited to the capital accounts of A and B as ₹4000 and ₹8000 respectively. The new profit sharing ratio of A, B, and C will be:', '["3:1:1", "5:3:2", "41:7:12", "2:2:1 =====PAGE 62===== CUET UG Accountancy 58"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q24'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'hard', 'A, B and C are partners sharing profits in the ratio of 2:2:1. D was admitted for 1/10th share, which he acquired from A and B in the ratio of 3:2. D brings ₹30,000 as premium for goodwill. The premium for goodwill will be credited to the:', '["Capital a/cs of A, B and C in 2:2:1.", "Capital a/cs of A and B in 2:2.", "Capital a/cs of A and B in 3:2.", "Capital a/cs of A, B, C and D in their new ratio"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q25'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'medium', 'When the new partner fails to bring his share of goodwill, the account to be debited is:', '["New Partner’s Capital A/c", "New Partner’s Current A/c", "Premium for Goodwill A/c", "Old Partners’ Capital A/c"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q26'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'hard', 'A and N are partners in a firm, sharing profits in the ratio of 2:1. M was admitted for 1/4th share, 1/8th of which was given by A and remaining was contributed by N. Goodwill of the firm valued at ₹36,000. What amount of goodwill will be credited to the capital accounts of A and N?', '["₹18000 each", "₹1125 to A and ₹7875 to N", "₹4500 each", "₹8000 to A and ₹1000 to N"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q27');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'hard', 'At the time of admission of a new partner, capital adjustment is required mainly to:', '["Increase total capital", "Equalise partners’ capital", "Distribute profits", "Prepare balance sheet"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q28'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'easy', 'When capitals are adjusted without bringing cash, the adjustment is made through:', '["Cash A/c", "Revaluation A/c", "Current A/c", "Goodwill A/c"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q29'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'medium', 'If the capital of a partner is more than required, then he/she will:', '["Bring Capital", "Withdraw Capital", "Transfer excess capital to Goodwill", "Demand an extra share in profit."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q30'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'medium', 'If a partner’s capital is less than the required capital, he/she will:', '["Introduce capital", "Withdraw capital", "Reduce share in profit", "Adjust from Goodwill"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q31'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'For capital adjustment, the total capital is based on:', '["The capital brought by the new partner.", "Total cash brought by the new partner.", "Total adjusted capital of old partners.", "Both A and C"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q32'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'Ajay is a partner in a firm for 3/6th share. The total capital of the firm is fixed at ₹6,00,000. The capital of Ajay after all adjustments is ₹3,50,000. It was decided that the capitals of the partners will be adjusted in their profit sharing ratio and the excess capital will be withdrawn and deficit capital will be introduced in cash by the partners. The journal entry for adjusting the capital of Ajay will be:', '["Cash A/c Dr 50,000 To Ajay’s Capital A/c 50,000", "Cash A/c Dr 2,50,000 To Ajay’s Capital A/c 2,50,000", "Ajay’s Capital A/c Dr 50,000 To Cash A/c 50,000", "Ajay’s Capital A/c Dr 2,50,000 To Cash A/c 2,50,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q33'),
  ('Accountancy', 'Admission of a New Partner', 'Profit sharing', 'hard', 'Vijay is a partner in a firm for 2/6th share. The total capital of the firm is fixed at ₹3,00,000. The capital of Vijay after all adjustments is ₹90,000. It was decided that the capitals of the partners will be adjusted in their profit sharing ratio and the excess capital will be withdrawn and deficit capital will be introduced in cash by the partners. The journal entry for adjusting the capital of Vijay will be:', '["Cash A/c Dr 10,000 To Vijay’s Capital A/c 10,000", "Vijay’s Capital A/c Dr 10,000 To Cash A/c 10,000", "Cash A/c Dr 1,00,000 To Vijay’s Capital A/c 1,00,000", "Vijay’s Capital A/c Dr 1,00,000 To Cash A/c 1,00,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q34'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'If the existing capital of a partner is ₹3,50,000 and the required capital is ₹5,00,000, and the capitals are to be adjusted by opening the current accounts, then the partner’s current account will have a:', '["Debit balance of ₹1,50,000", "Credit balance of ₹1,50,000", "Debit balance of ₹5,00,000", "Credit balance of ₹5,00,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q35'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'If the existing capital of a partner is ₹3,50,000 and the required capital is ₹3,00,000, and the capitals are to be adjusted by opening the current accounts, then the partner’s current account will appear on the _____ side of the balance sheet at ₹_____.', '["Asset, 50,000", "Liabilities, 50,000", "Asset, 3,50,000", "Liabilities, 3,00,000 =====PAGE 63===== Admission of a New Partner 59"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q36'),
  ('Accountancy', 'Admission of a New Partner', 'Goodwill', 'hard', 'A and B are partners in a firm sharing profits in the ratio of 3:2. They admit C for 1/4th share in the profits. C brings ₹50,000 for capital and ₹20,000 for his share in goodwill. The capital of A and B were to be adjusted on the basis of the capital brought by C. The total capital of the firm will be:', '["₹2,80,000", "₹2,00,000", "₹2,50,000", "₹3,50,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q37'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'A and B are partners in a firm sharing profits in the ratio of 3:2. They admit C for 1/5th share in the profits. The capitals of A and B after all adjustments is ₹3,00,000 and ₹2,60,000 respectively. It was decided that C will bring proportionate capital. The total capital of the firm will be:', '["₹5,60,000", "₹8,00,000", "₹6,00,000", "₹7,00,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q38'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'medium', 'The fictitious assets are _____ (debited/credited) to the capital a/c of ______ (old/sacrificing) partners on admission of a new partner.', '["Credited, Old", "Debited, Old", "Credited, Sacrificing", "Debited, Sacrificing"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q39'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'medium', 'The General Reserve appearing in the balance sheet at the time of the admission of a new partner will be:', '["Credited to the capital accounts of the old partners in their old ratio.", "Credited to the capital accounts of the old partners in their new ratio.", "Credited to the capital accounts of the all partners in their new ratio.", "Credited to the capital accounts of the sacrificing partners in their sacrificing ratio."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q40'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of a New Partner', 'hard', 'If the accumulated profits and reserves have a debit balance, which of the following will be the correct entry to write off the amount?', '["Accumulated Profits and Reserves A/c Dr (Total Amount) To Capital Account of Old Partners (in old ratio)", "Capital Account of Old Partners Dr (in old ratio) To Accumulated Profits and Reserves A/c (Total Amount)", "Capital Account of Old Partners Dr (in sacrificing ratio) To Accumulated Profits and Reserves A/c (Total Amount)", "Capital Account of Old Partners Dr (in sacrificing ratio) To Accumulated Profits and Reserves A/c (Share of new partner)"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q41'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'medium', 'The debit balance of Profit and Loss A/c at the time of admission of a new partner will be:', '["Credited to the capital account of the old partners in their sacrificing ratio.", "Credited to the capital account of the old partners in their old ratio.", "Credited to the capital account of the old partners in their new ratio.", "Debited to the capital account of the old partners in their old ratio."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q42'),
  ('Accountancy', 'Admission of a New Partner', 'Admission of partner', 'hard', 'If the accumulated profits and reserves have a debit balance, which of the following will be the correct entry to adjust the amount at the time of admission of a new partner, if the old partners decide not to close the books?', '["Accumulated Profits and Reserves A/c Dr (Total Amount) To Old Partners’ Capital A/c (in old ratio)", "New Partner’s Capital A/c Dr (Total Amount) To Old Partners’ Capital A/c (in sacrificing ratio)", "New Partner’s Capital A/c Dr (His share in Accumulated profits and reserves) To Old Partners’ Capital A/c (in sacrificing ratio)", "Old Partners’ Capital A/c Dr (in sacrificing ratio) To New Partner’s Capital A/c (His share in Accumulated profits and reserves)"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Admission of a New Partner · Q43'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'medium', 'As per section 32(1) of the Indian Partnership Act, 1932, which of the following conditions are laid down for the retirement of a partner:', '["A partner may retire with the consent of all the partners.", "A partner may retire in accordance with an express agreement amongst the partners.", "A partner may retire by issuing a notice in writing to all the partners stating the intention to retire.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q1'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'X, Y and Z were partners sharing profits and losses in the ratio of 5 : 4 : 3. Y retired on 1st April, 2026. X and Z purchased his share of profit by giving him ₹ 60,000. ₹ 40,000 was paid by X, and ₹ 20,000 by Z. Gaining ratio is:', '["2 : 1", "5 : 3", "1 : 1", "1 : 2"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q2'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'B, C and D were partners in a firm sharing profits in the ratio of 5:4:1. The profit of the firm for the year ending on 31st March 2025 was ₹1,00,000. C died on June 30,2025. B and D decided to share future profits equally. C’s share of profit will be calculated on the basis of last year’s profit. What will be C’s share of profit for the period from April 1 to June 30, 2025?', '["₹20,000", "₹10,000", "₹40,000", "₹50,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q3'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'A, B and C are partners in a firm sharing profits equally. C retired on 31st March 2025, and the amount due to him is ₹60,000, which has been transferred to his loan account. In the year 2024-25, the firm earns a profit of ₹2,10,000, and the capitals of A and B are ₹90,000 and ₹1,50,000. As per the provisions of Section 37, C is entitled to receive:', '["₹60,000", "₹3,600", "₹42,000", "Either of (b) and (c)"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q4'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'medium', 'The remaining partners compensate the retiring partner for the valued goodwill of the firm in:', '["Old Ratio", "Sacrificing Ratio", "Gaining Ratio", "New Ratio"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q5'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'X, Y and Z were partners in a firm sharing profits in the ratio of 3 : 2 : 1. X retired, and the new profit- sharing ratio between Yand Z will be 5:4. On X’s retirement, the goodwill of the firm was valued at ₹54,000. Journal entry will be:', '["Y’s Capital A/c Dr. 24,000 Z’s Capital A/c Dr. 30,000 To X’s Capital A/c 54,000", "Y’s Capital A/c Dr. 15,000 Z’s Capital A/c Dr. 12,000 To X’s Capital A/c 27,000", "Y’s Capital A/c Dr. 12,000 Z’s Capital A/c Dr. 15,000 To X’s Capital A/c 27,000", "X’s Capital A/c Dr. 27,000 To Y’s Capital A/c 12,000 To Z’s Capital A/c 15,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q6'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'X, Y and Z were partners in a firm sharing profits in the ratio of 2 : 2 : 1. Z died on 1st Oct, 2025. Z’s share of profit was to be calculated on the basis of sales. The sales during the year 2024-25 were ₹8,00,000, and the profit for the year was ₹1,00,000. The sales from April 1, 2025, to Sep 30, 2025, were ₹3,00,000. Z’s share in profit will be:', '["₹7,500", "₹20,000", "₹10,000", "₹3,750"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q7'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'X, Y and Z are partners in a firm. Y retires, and his claim, including his capital and his share of goodwill, is ₹1,20,000. He is paid partly in cash and partly in kind. A vehicle of ₹60,000 unrecorded in the books of the firm was valued at 20% less than its value and was given to Y, and the balance in cash was given to him to settle his account. The amount of cash to be paid to Y will be:', '["₹80,000", "₹60,000", "₹48,000", "₹72,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q9'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'medium', 'In the absence of any information regarding the acquisition of the share in profit of the retiring/ deceased partner by the remaining partners. It is assumed that they will acquire his/her shares:', '["Old Profit Sharing ratio", "New Profit Sharing ratio", "Equal Ratio", "None of these PRACTICE CORNER =====PAGE 94===== CUET UG Accountancy 90"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q10'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'Chaman, Raman and Suman are partners sharing profit in the ratio of 5 : 3 : 2. Raman retires; the new profit-sharing ratio between Chaman and Suman will be 1 : 1. The goodwill of the firm is valued at ₹1,00,000; Raman’s share of goodwill will be adjusted:', '["By debiting Chaman’s Capital account and Suman’s Capital Account with ₹15,000 each.", "By debiting Chaman’s Capital account and Suman’s Capital Account with ₹21,429 and ₹8,571, respectively.", "By debiting only Suman’s Capital Account with ₹30,000.", "By debiting only Chaman’s Capital account with ₹30,000."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q11'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'B, C and D were partners in a firm sharing profits in the ratio of 5 : 4 : 1. C died on 1st Oct, 2025. B and D decided to share profits equally. C’s share of profit was to be calculated on the basis of average profits of the last three years, which were ₹1,36,000 for 2024-25, ₹1,54,000 for 2023-24 and ₹1,00,000 for 2022-23. C’s share of profit will be:', '["₹13,000", "₹26,000", "₹52,000", "₹60,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q12'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'X, Y and Z are partners sharing profits and losses in the ratio of 2 : 2 : 1. Z died on 31st Jan, 2026. For the year 2025-26, the proportionate profit of 2024-25 is to be taken into consideration after making an adjustment for bad debts amounting to ₹6,000. The profit for the year 2024-25 was ₹30,000 before the adjustment of bad debts. Z’s share of profit till his death will be:', '["₹6,250", "₹7,083", "₹4,000", "₹24,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q13'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Interest on drawings', 'hard', 'Which of the following items are deducted from the total of sums due to the legal representative of the deceased partner? ( i) Drawings made by the deceased partner ( ii) Interest on drawings, if provided in the partnership deed ( iii) Share of losses upon revaluation of assets and liabilities ( iv) Share in the balance of Profit and Loss Account appearing on the liabilities side of the Balance Sheet. ( v) Advance or loan granted to him by the firm, if any.', '["( i), (iii), (iv), (v)", "( i), (ii), (iii), (v)", "( i), (ii), (iv)", "( i), (ii), (iii)"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q14'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'Which of the following adjustments are required at the time of retirement of a partner?', '["Adjustment of reserves and accumulated profits or losses and Capital", "Determination of the new profit-sharing ratio and gaining ratio.", "Treatment of goodwill.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q15');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Retirement and Death of a Partner', 'Revaluation', 'hard', 'P , Q and R are partners sharing profits in the ratio of 2 : 2 : 1. P retired on 31st March 2026. On that date, their Balance Sheet had: Debtors: ₹40,000 Provision for Doubtful Debts: ₹2,000. On P’s retirement, Debtors worth ₹5,000 proved to be bad, and a new provision was to be made at the existing rate. In such a case, the Revaluation A/c will be debited by:', '["₹5,000", "₹3,000", "₹4,750", "₹6,750"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q16'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'medium', 'Which of the following is true?', '["Revaluation Account is unaffected when an unrecorded asset is taken over by the executors of a deceased partner.", "Revaluation Account is debited with the decrease in the value of creditors on the death of a partner.", "Revaluation Account is credited when an unrecorded asset is sold on the death of a partner", "Revaluation Account is unaffected when revaluation expenses are paid by a partner"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q17'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Interest on capital', 'hard', 'X, Y and Z are partners in a firm. Their profit-sharing ratio is 3 : 2 : 1. Y died on 1st November 2025. His capital on 1st April 2025 was ₹60,000. He was entitled to receive interest on capital @10% per annum. The books are closed on 31st March every year. Y’s interest on capital for the year 2025-26 will be:', '["₹6,000", "₹3,500", "₹4,000", "₹3,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q18'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'medium', 'Increase in liability at the time of retirement of a partner is:', '["Credited to Revaluation Account", "Credited to Capital Account", "Debited to Profit and Loss Account", "Debited to Revaluation Account"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q19'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'P , Q and R were partners in a firm sharing profits in the ratio of 4 : 3 : 1. R retired, and his entire share was taken up by P . The new profit-sharing ratio of P and Q will be:', '["1 : 1", "5 : 3", "3 : 5", "5 : 2 =====PAGE 95===== Retirement and Death of a Partner 91"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q20'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'M, N and S are partners in a firm sharing profits in the ratio of 2 : 1 : 1. N retires. The capital accounts of M and S show a credit balance of ₹1,64,000 and ₹1,36,000, respectively, after making all the adjustments. M and S decided to bring additional capital or withdraw excess capital to main tain their capital in their new ratio. The journal entry for capital adjustment will be:', '["M’s Capital A/c Dr 36,000 To Cash A/c 36,000", "S’s Capital A/c Dr 36,000 To Cash A/c 36,000", "Cash A/c Dr 36,000 To M’s Capital A/c 36,000", "Both (b) and (c)"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q21'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'medium', 'The amount payable to the deceased partner is transferred to:', '["The debit of his/her current account", "The credit of his/her capital account", "The debit of the Remaining Partner’s Capital Accounts", "His/her Executor’s Account"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q22'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'Lisa, Monika and Nisha are partners in a firm, sharing profits in the ratio of 2 : 2 : 1. Their capitals Accounts stood as ₹50,000, ₹50,000 and ₹25,000, respectively. Monika died, and the balance in the reserve on that date was ₹15,000. If the goodwill of the firm is ₹30,000 and the profit on revaluation is ₹7,050. What amount will be transferred to Monika’s Executors’ Account?', '["₹50,820", "₹70,820", "₹8,820", "₹60,820"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q23'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'medium', 'While calculating the amount to be paid to the retiring partner, which of the following will decrease the final amount payable to him?', '["Share in Revaluation loss", "Share in Revaluation profit", "Share in General Reserve", "Share in Goodwill"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q24'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'F, G and H are partners sharing profits and losses in the ratio of 3 : 4 : 2. G has retired from the firm, and his share is taken by H. What will be the new profit- sharing ratio between partners?', '["2 : 1", "1 : 2", "3 : 4", "None of the above"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q25'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'N, S and H were partners in a firm sharing profits in the ratio of 3 : 2 : 1. S retired from the firm. On the date of S’s retirement, ₹60,000 was due to him. The remaining partners decided to pay him in three yearly instalments starting from the end of the first year. ₹60,000 will be transferred to which of the following accounts?', '["S’s Loan Account", "S’s Executor’s Accounts", "S’s Bank Account", "S’s Current Account"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q26'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'A, B and C are sharing profits in the ratio of 5:3:2. C died on 31st March, 2026. Accounts are closed on 31st December every year. The sales for the year 2025 amounted to ₹10 lakh, and the profit of that year was ₹2,00,000. The Sales for the period of 1st January, 2026 to 31st March, 2026 amounted to ₹2,00,000. Determine the profit to be credited to the capital account of C on the date of his death.', '["₹2,00,000", "₹40,000", "₹10,000", "₹8,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q27'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Revaluation', 'hard', 'F, G and H are partners sharing profits and losses in the ratio of 4:3:3. G retired from the firm, and his capital on the date of retirement was ₹100000. Profit on Revaluation of assets and liabilities was ₹20000, and General Reserve was ₹10000. What will be the journal entry for the payment of the amount due to G?', '["G’s Capital A/c Dr 109000 To Bank A/c 109000", "G’s Capital A/c Dr 100000 To Bank A/c 100000", "G’s Capital A/c Dr 103000 To Bank A/c 103000", "None of the above"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q28'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'C, D and E are partners sharing profits and losses in the ratio of 2:1:1. E retired from the firm and surrendered 1 5 th of his share of profit to C and remaining in favour of D. Calculate the new profit- sharing ratio of C and D.', '["11 : 5", "9 : 11", "11 : 9", "None of the above"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q29'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'In the case of retirement, if full or part of the amount payable to the retiring partner remains to be paid, and there is no agreement among the partners, then the retiring partner will get: ( i) Interest @ 6% p.a. on the Balance amount. ( ii) Share of profit earned proportionate to his amount outstanding to the total capital of the firm ( iii) Interest @ 9% p.a. on the balance amount. =====PAGE 96===== CUET UG Accountancy 92 Which out of the following is correct?', '["only (i)", "only (iii)", "( i) and (ii)", "( i) or (ii)"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q30'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'P , Q and R are partners in a firm sharing profits and losses in the ratio of 7 : 5 : 8. P died on 30th September, 2025, and Q and R decided to share future profits equally. His share in the profits of the firm till the date of his death was determined at ₹25,000. It will be debited to which of the following accounts?', '["Profit and Loss Suspense Account", "Profit and Loss Account", "Capital A/c of Gaining Partners", "Profit and Loss Appropriation Account"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q31'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'Kiran, Umesh and Aditya were in a partnership firm. Suddenly, on October 31, 2025, Kiran retired. Amount payable to her on that date amounted to ₹1,05,000. ₹5000 was paid immediately, and the balance was paid in 4 equal annual instalments along with interest @ 12% p.a. starting from 31st October 2025. Calculate the interest due as on 31st March, 2026. The financial year was followed by the accounting year of the firm.', '["₹2,500", "₹3,000", "₹5,000", "₹3,750"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q32'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'D, E and F are partners sharing profits and losses in the ratio of 2 : 3 : 2. F retired from the firm and surrendered 2 9 th of his share of profit to D, and the remaining in favour of E. What will be the gaining ratio between D and E?', '["3 : 2", "2 : 7", "2 : 3", "None of the above"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q33'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'On the retirement of H from the firm of H, R and S, the Balance Sheet showed a debit balance of ₹12,000 in the Profit and Loss Account. For calculating the amount payable to H, the balance will be transferred:', '["To the credit of the capital accounts of H, R and S equally", "To the debit of the capital accounts of H, R and S equally", "To the debit of the capital accounts of R and S equally", "To the credit of the capital accounts of R and S equally"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q34'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'A, B and C were partners in a firm sharing profits and losses in the ratio of 5 : 3 : 2. C retired, and his capital balance after adjustments regarding reserves, accumulated profits/losses and his share of gain on revaluation was ₹2,50,000. C was paid ₹3,22,000, including his share of goodwill. The amount credited to C’s capital account, on his retirement, for goodwill will be:', '["₹72,000", "₹7,200", "₹24,000", "₹36,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q36'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'The old profit sharing ratio among R, S and T was 2 : 2 : 1. The New Profit Sharing Ratio after S’s retirement is 3 : 2. The gaining ratio of R and T is:', '["3 : 2", "2 : 1", "1 : 1", "2 : 2"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q37'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'A, B and C were partners sharing profits in the ratio 2 : 2 : 1, having capital accounts of ₹25,000, ₹25,000 and ₹25,000, respectively. B retired. On that date, the balance in the General Reserve was ₹25,000. If the firm’s Goodwill is valued at ₹15,000 and the gain (profit) on Revaluation is ₹7,500, the amount payable to B will be:', '["₹50,820", "₹9,000", "₹8,820", "₹44,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q38'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Financial statements', 'hard', 'A, B and C are partners. B died on 18th December, 2025, and as per the agreement surviving partners, A and C, directed the accountant to prepare financial statements as on 18th December, 2025 and accordingly, the share of profits of B (deceased partner) was calculated as ₹6,00,000. Which account will be debited to transfer B’s share of profits?', '["Profit and Loss Suspense Account", "Profit and Loss Account", "Profit and Loss Appropriation Account", "Gaining Partner’s Capital A/c"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q39'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'Anil, Sunil, and Vimal are partners in a firm sharing profits in the ratio of 3:2:1. Vimal retired on 31st March 2026, and Anil and Sunil decided to share future profits equally. The goodwill of the firm was valued at ₹60,000 on Vimal’s retirement. =====PAGE 97===== Retirement and Death of a Partner 93 The correct entry for adjusting goodwill will be:', '["Vimal’s Capital A/c Dr 10,000 To Anil’s Capital A/c 6,000 To Sunil’s Capital A/c 4,000", "Sunil’s Capital A/c Dr 10,000 To Vimal’s Capital A/c 10,000", "Vimal’s Capital A/c Dr 10,000 To Anil’s Capital A/c 10,000", "Goodwill A/c Dr 60,000 To Anil’s Capital A/c 30,000 To Sunil’s Capital A/c 20,000 To Vimal’s Capital A/c 10,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q40'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'X, Y and Z are partners sharing profits in the ratio of 5:3:2. X retired. On the date of retirement of X, the goodwill of the firm was valued at ₹1,60,000. The journal entry made for adjusting the valued goodwill was: Z’s Capital A/c Dr 1,20,000 To X’s Capital A/c 80,000 To Y’s Capital A/c 40,000 Determine the new ratio of Y and Z.', '["2 : 1", "3 : 2", "3 : 1", "1 : 19"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q41'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'Abhishek, Rajat and Vivek are partners sharing profits in the ratio of 5:3:2. If Rajat retires, the new profit- sharing ratio between Abhishek and Vivek will be:', '["3 : 2", "5 : 3", "5 : 2", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q42'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'Rajesh, Rakesh and Ramesh are partners sharing profits and losses in the ratio of 2:1:2. Ramesh died on 1st August 2025. His share of profit was based on the profit of the last accounting year, which was ₹36,000. Books are closed on 31st March every year. How much profit will be credited to Ramesh’s Capital Account?', '["₹4,000", "₹13,000", "₹7,200", "₹4,800"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q43'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Goodwill', 'hard', 'A, B and C were partners sharing profits in the ratio 2:2:1, having capital accounts as ₹20,000, ₹25,000 and ₹30,000, respectively. B retired. On that date, the balance in the General Reserve was ₹25,000, and the P&L A/c had a debit balance of ₹15,000. If the firm’s Goodwill is valued at ₹60,000 and the gain (profit) on Revaluation is ₹10,000, the amount payable to B will be:', '["₹32,000", "₹44,000", "₹69,000", "₹57,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q44'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'A, B and C are partners in a firm. B retired, and his share was taken over by A and C in the ratio of 3:2. The new profit-sharing ratio of A and C will be:', '["3 : 2", "1 : 1", "8 : 7", "7 : 8"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q45'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'C, D and E are partners sharing profits and losses in the ratio of 2 : 1 : 1. E retired from the firm and surrendered 1/3rd of his share of profit to C, and the remaining in favour of D. Calculate the gaining share of D.', '["2 12", "1 12", "2 4", "None of the above"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q46');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'A, B and C were partners in a firm sharing profits in the ratio of 3 : 2 : 1. B retired from the firm. On the date of B’s retirement, ₹30,000 was due to her. A and C decided to pay her in three equal annual instalments alongwith interest @10% per annum. Which of the following statements is correct in the given scenario?', '["The interest per annum will remain the same.", "The instalment per annum will remain the same.", "The instalment per annum will vary.", "None of the above"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q47'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'Ram, Rahim and Rahman are partners sharing profits and losses in the ratio of 2 : 1 : 1. Rahim died on 30th June 2025, and his share in profit till the date of his death amounted to ₹30,000. Ram and Rahman decided to share future profits equally. Which of the following will be the correct entry for crediting profit to Rahim’s capital A/c?', '["P&L Suspense A/c Dr 30,000 To Rahim’s Capital A/c 30,000", "Ram’s Capital A/c Dr 30,000 To Rahim’s Capital A/c 30,000", "Rahman’s Capital A/c Dr 30,000 To Rahim’s Capital A/c 30,000", "Ram’s Capital A/c Dr 20,000 Rahman’s Capital A/c Dr 10,000 To Rahim’s Capital A/c 30,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q48'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'On the retirement of a partner, debtors of ₹50,000 were shown in the Balance Sheet. Out of these, the debtors worth ₹5,000 became bad. Out of the remaining debtors, one debtor became insolvent, and only 70% were recovered from him out of ₹10,000. A new provision for doubtful debts was to be created on debtors @10%. The provision for doubtful debts will be:', '["₹3,500", "₹4,500", "₹4,200", "₹5,000 =====PAGE 98===== CUET UG Accountancy 94"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q49'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'medium', 'Identify the correct statement.', '["New share = Old share + Gained Share", "New share = Old share – Gained Share", "New share = Old share + Sacrificed Share", "New share = Gained share + Sacrificed Share"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q50'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'A, B, and C were partners. C retired on April 1, 2025. On that date, the amount due to him was ₹2,00,000. The remaining partners, A and B, continued the business for 6 months without paying C. During these 6 months, they earned a profit of ₹40,000. The total capital of the firm (including C’s unpaid share) was ₹10,00,000. Under Section 37, what is the maximum amount C can claim for these 6 months?', '["₹6,000", "₹8,000", "₹12,000", "₹4,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q51'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'A, B, and C are partners sharing profits in the ratio of 3 : 2 : 1. B retires on March 31, 2026. After making all adjustments for reserves, revaluation of assets, and reassessment of liabilities, B’s Capital Account shows a credit balance of ₹1,60,000. A and C agree to pay him ₹2,00,000 in full settlement of his claim. If the new profit-sharing ratio between A and C is 3 : 2, what is the value of the Total Goodwill of the firm?', '["₹40,000", "₹1,00,000", "₹1,20,000", "₹80,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q52'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'A, B, and C are partners with capitals of ₹2,00,000, ₹1,50,000, and ₹1,00,000, respectively. B retires. A and C decide that the total capital of the new firm will be fixed at ₹4,00,000 in their new profit-sharing ratio of 3 : 2. How much cash will A bring in or withdraw?', '["Bring in ₹40,000", "Withdraw ₹40,000", "Bring in ₹50,000", "Withdraw ₹50,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q53'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Profit sharing', 'hard', 'X, Y, and Z share profits in 5 : 3 : 2. Y retires. After all adjustments (revaluation, reserves, etc.), the capitals of X and Z are ₹2,10,000 and ₹70,000, respectively. They decide to adjust their capital in their profit- sharing ratio by bringing in or paying out cash. What is the new capital of Z?', '["₹80,000", "₹90,000", "₹1,00,000", "₹2,00,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q54'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and Death of a Partner', 'hard', 'P , Q, and R are partners. R retires. The adjusted capitals of P and Q are ₹40,000 and ₹30,000. The amount due to R is ₹20,000. P and Q decide to bring in sufficient cash to pay R and to make their capital proportionate to their new ratio of 3 : 2. What is the new total capital of the firm?', '["₹70,000", "₹90,000", "₹50,000", "₹1,10,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q55'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'In case of the death of a partner, ₹80,000 was transferred to his Executor’s Loan A/c. It was to be paid in 4 equal annual installments of ₹25,000 each. The rate of interest is 10% per annum. Find the amount of interest paid along with the 4th (last) instalment.', '["₹2,373", "₹1,270", "₹8,000", "₹2,500"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q56'),
  ('Accountancy', 'Retirement and Death of a Partner', 'Retirement and death', 'hard', 'In case of the death of a partner, ₹1,20,000 was transferred to his Executor’s Loan A/c. It was to be paid in 4 equal half-yearly instalments along with interest @6% per annum. The third instalment will be of:', '["₹33,600", "₹40,000", "₹30,000", "₹31,800 Assertion – Reason – Based Questions Given below are two statements, one labelled as Assertion (A) and the other labelled as Reason (R). Read the statements and choose the correct option. (A) Both A and R are true, and R is the correct explanation of A. (B) Both A and R are true, but R is not the correct explanation of A. (C) A is true, but R is false. (D) A is false, but R is true. (E) Both A and R are incorrect."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Retirement and Death of a Partner · Q57'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'Which of the following is NOT the mode of dissolution of the firm?', '["Dissolution by the court", "Mutual Agreement", "Retirement of a partner", "All of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q1'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'At the time of dissolution of a firm, the General Reserve appearing in the Balance Sheet is transferred to:', '["Realisation Account", "Partners’ Capital Accounts in profit-sharing ratio", "Partners’ Capital Accounts in capital ratio", "Bank A/c"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q2'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'Pick the odd one out with reference to Realisation A/c in case of dissolution of a firm.', '["Employees’ provident fund", "Partner’s brother’s loan", "Partner’s loan", "Creditors"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q3'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'Investments valued ₹20,000 were taken over by the creditors in full satisfaction of their debt of ₹22,000 at the time of dissolution of the firm. Which of the following statements is true for the given case?', '["Realisation A/c will be debited by ₹20,000", "Bank A/c will be credited by ₹2000", "Both", "and (b) (d) The given transaction will not be recorded."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q4'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'In case of dissolution of the firm, the Deferred Revenue Expenditure appearing in the asset side of the B/S will be:', '["Debited to the Realisation A/c", "Credited to the Realisation A/c", "Debited to the Capital A/cs of the partners", "Credited to the Capital A/cs of the partners"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q5'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'In which of the following cases can the Court order the dissolution of a firm?', '["When a partner deliberately commits a breach of agreements relating to the management of the firm.", "When a partner has become mentally disturbed or has unsound mind.", "When the court is satisfied that the firm cannot be carried on except at a loss.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q6'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'medium', 'A firm will be compulsorily dissolved in which of the following situations?', '["The business of the firm is declared to be illegal", "On the death of all or all but one partner", "On insolvency of all or all but one partner", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q7'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'Which of the following is the correct entry for the sale of an unrecorded asset on the dissolution of a firm?', '["Cash A/c Dr To Realisation A/c", "Realisation Account A/c Dr To Respective Asset A/c", "Cash A/c Dr To Respective Asset A/c", "Respective Asset A/c Dr To Realisation A/c"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q8'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'medium', 'The amount realised from assets is first utilised for paying off the:', '["External liabilities of the firm", "Partner’s loan", "Partner’s capital", "Any of the above."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q9'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'On dissolution of a firm, a partner took over investments worth ₹17000 for ₹14,000. Which one of the following will be the correct treatment?', '["Realisation Account will be credited by ₹3,000", "Partner’s Capital Account will be debited by ₹14,000", "Partner’s Capital Account will be credited by ₹17,000", "Realisation Account will be credited by ₹17,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q10'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'In case of dissolution of the firm, if the firm’s assets are in surplus, then they are applied towards payment of the partner’s private debts to the extent of his:', '["Share in profit", "Share in capital", "Due amount", "Share in profit or capital, whichever is more PRACTICE CORNER =====PAGE 119===== Dissolution of a Partnership Firm 115"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q11'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'On dissolution of a firm, creditors worth ₹18000 took over the stock whose book value is ₹20,000. Which of the following accounts will be debited:', '["Realisation A/c", "Bank A/c", "Partner’s Capital A/c", "Not recorded"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q12'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'At the time of dissolution of the firm, Partner’s current accounts are transferred to:', '["Partners’ Loan A/c", "Realisation A/c", "Partners’ Capital Accounts", "Bank A/c"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q13'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'X and Y were partners in a firm. On the dissolution of the firm, the loan given by X to the firm was Rs. 30000, by Y was Rs. 15000 and by Mrs X was Rs. 10000. Whose loan will be repaid first and why?', '["X’s loan, as he has lent the maximum amount", "Mrs X’s loan, as she has lent the minimum amount", "Y’s loan as X and Mrs X belong to the same family", "Mrs X’s loan as her loan is an external liability"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q14'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'At the time of dissolution of a firm, all assets (except cash/bank and fictitious assets) are transferred to the ————— (Debit/Credit) side of ——————— Account (Realisation/Capital).', '["Debit, Capital", "Debit, Realisation", "Credit, Capital", "Credit, Realisation"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q15'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'easy', 'Realisation A/c is a:', '["Personal A/c", "Real A/c", "Nominal A/c", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q16'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'medium', 'As per Section 49 of Indian Partnership Act, 1932, firm’s assets are first utilized for settlement of _____ .', '["Firm’s debt", "Private debt of partners", "Any of the above", "None of the above"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q17'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Partner''s loan', 'hard', 'Partner’s Loan of ₹50,000 was settled for ₹45000 at the time of dissolution of the firm. The Realisation A/c will be ______.', '["Debited by ₹45000", "Debited by ₹50000", "Debited by ₹5000", "Credited by ₹5000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q18'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'At the time of dissolution of the firm, the balance sheet of the firm has Debtors of ₹50,000 and Provision for doubtful debts of ₹5,000. Further, it is given that only 80% could be realised from debtors. While transferring the assets, the Realisation A/c will be debited by _______ and for amount realised from debtors, the Realisation A/c will be credited by ________.', '["₹50,000; ₹40,000", "₹45,000; ₹40,000", "₹45,000; ₹36,000", "₹50,000; ₹36,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q19');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'easy', 'Identify the odd one out in the context of Realisation A/c.', '["Cash", "Debtors", "Provision for Doubtful Debts", "Bank Loan"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q20'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'The assets are transferred to Realisation A/c at:', '["Their book value", "Their market value", "Higher of book value and market value", "Lower of book value and market value"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q21'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'The effect of following on Realisation A/c will be: Unrecorded asset of ₹8000 was sold for ₹11000.', '["Realisation A/c will be credited by ₹3000", "Realisation A/c will be credited by ₹11000", "Realisation A/c will be debited by ₹8000 and credited by ₹11000", "Not recorded in Realisation A/c"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q22'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Partner''s loan', 'hard', 'Which of the following statement (s) is/are true in the context of dissolution of a firm? (i) The sale of an unrecorded asset is not shown in Realisation A/c. (ii) When a creditor is paid by giving him an asset, then it is shown in the debit side of Realisation A/c. (iii) Payment of Partner’s Loan is debited to Realisation A/c. (iv) All the assets are transferred to the debit side of Realisation A/c.', '["Only (iv)", "Only (ii)", "(ii) and (iv)", "None of the given statements"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q23'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'Total assets of a partnership firm, which was dissolved, were ₹15,00,000, and its total liabilities were ₹3,00,000. Assets were realised at 90%, and liabilities were settled at 5% less. The profit or loss on dissolution was:', '["Profit ₹ 1,35,000", "Loss ₹ 1,35,000", "Profit ₹ 1,65,000", "Loss ₹ 1,65,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q24'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'medium', 'Unrecorded assets when taken over by a partner are shown in:', '["Debit of Realisation Account", "Debit of Bank Account", "Credit of Realisation Account", "Credit of Bank Account. =====PAGE 120===== CUET UG Accountancy 116"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q25'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'easy', 'On dissolution of the firm, partner’s capital accounts are closed through:', '["Realisation Account", "Drawings Account", "Bank Account", "Loan Account."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q26'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'On dissolution of a partnership firm, X, a partner took over 80% of debtors at ₹18000 (being 90% of book value) and the remaining debtors could realise only 80% of book value. The cash received on realisation of remaining debtors will be:', '["₹4000", "₹10,368", "₹16,000", "₹22,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q27'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'At the time of dissolution of the firm, the accumulated profits and reserves will be:', '["Transferred to the Realisation A/c", "Credited to Partners’ Capital A/c in their profit sharing ratio", "Debited to Partners’ Capital A/c in their profit sharing ratio", "Credited to Partners’ Capital A/c in their capital ratio"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q28'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'Upon the dissolution of a partnership firm, X, a partner took over 25% of an asset at ₹30,000 (being 60% of the book value). Find the book value of the remaining asset.', '["₹1,00,000", "₹64,000", "₹50,000", "₹1,50,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q29'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'At the time of dissolution of the firm it was decided that the process of realisation will be accomplished by X, a partner, for which he will be paid ₹10,000 along with the amount of expense which amounted to 2% of total cash realised from the Assets on dissolution. Some assets were sold for cash at a cumulative value of ₹12,00,000 and the remaining were taken over by creditors at a valuation of ₹3,00,000. The total expense on realisation for the firm will be:', '["₹10,000", "₹34,000", "₹24,000", "₹40,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q30'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'hard', 'Total assets of a partnership firm, which was dissolved, were ₹15,00,000 and its total liabilities were ₹3,00,000. Assets costing ₹4,00,000 were given to creditors for settlement of claim, and the remaining assets were realised at 10% above book value. The cash realised from assets is:', '["₹1,10,000", "₹11,00,000", "₹12,10,000", "₹15,10,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q31'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'What Journal Entry will be passed on dissolution of a partnership firm when a partner agreed to bear the dissolution expenses for ₹20,000, and the actual expenses paid by the partner were ₹25,000?', '["Realisation A/c Dr. 25,000 To Partner’s Capital A/c 25,000", "Realisation A/c Dr. 20,000 To Partner’s Capital A/c 20,000", "Realisation A/c Dr. 5,000 Dissolution Exp. A/c Dr. 20,000 To Bank A/c 25,000", "Realisation A/c Dr. 25,000 To Bank A/c 25,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q32'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'Which of the following is the correct entry: If the realisation expenses were to be borne by a partner but have been paid by the firm?', '["Bank A/c Dr. To Partner’s Capital A/c", "Realisation A/c Dr. To Bank A/c", "Partner’s Capital A/c Dr. To Bank A/c", "Realisation A/c Dr. To Partner’s Capital A/c"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q33'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'On dissolution of a firm, debtors amounted to ₹27,000, and provision for doubtful debts was of ₹2,500. Debtors worth ₹2,000 proved to be bad, and only 50% could be realised from the remaining debtors. Which of the following statements is true with respect to realisation of debtors?', '["Realisation Account will be credited by ₹13,500", "Realisation Account will be credited by ₹12,500", "Realisation Account will be credited by ₹11,250", "Realisation Account will be credited by ₹13,750"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q34'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'On dissolution of a firm, a partner took over an unrecorded asset for ₹15,000. Which of the following accounts will be credited:', '["Realisation A/c", "Partner’s Capital A/c", "Bank A/c", "It will not be recorded."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q35'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'hard', 'On 1st April 2025, the Balance Sheet of Radha and Mohan showed a loan of ₹ 10,000 given by Mohan to the firm. The firm was dissolved on this date. Mohan’s loan will be discharged by crediting which of the following accounts?', '["Realisation Account", "Mohan’s Capital Account", "Mohan’s Current Account", "Bank Account =====PAGE 121===== Dissolution of a Partnership Firm 117"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q36'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'At the time of dissolution, Creditors appeared in Balance Sheet at ₹30,000. 60% of the creditors accepted ₹15000 in full settlement and remaining accepted an old computer of book value ₹10,000 at ₹8,000 and balance in cash. The amount credited to cash account for payment to the creditors will be:', '["₹15,000", "₹19,000", "₹17,000", "₹28,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q37'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'hard', 'Investments valued at ₹20,000 were taken over by the creditors of ₹30,000, and the balance was paid in cash. Which of the following statements is true for the given case:', '["Realisation A/c will be debited by ₹20,000", "Realisation A/c will be debited by ₹10,000", "Realisation A/c will be debited by ₹30,000", "Realisation A/c will be credited by ₹20,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q39'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'X, a partner, paid a Realisation expense of Rs. 8000 on behalf of the firm. The journal entry will be:', '["Realisation A/c Dr 8000 To Cash A/c 8000", "X’s Capital A/c Dr 8000 To Cash A/c 8000", "X’s Capital A/c Dr 8000 To Realisation A/c 8000", "Realisation A/c Dr 8000 To X’s Capital A/c 8000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q40'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'On the date of dissolution of the firm of A and B, the Balance Sheet revealed: Sundry Creditors: ₹32,000 Total Capital: ₹25,000 A’s Loan: ₹12,000 Cash: ₹4,000 If the assets are realised for ₹80,000. The profit/loss on realisation will be:', '["Profit of ₹11,000", "Loss of ₹17000", "Profit of ₹15,000", "Insufficient Information"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q41'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'At the time of dissolution of a firm, Machinery appeared in the books at ₹80,000. A part of the machinery was sold for ₹40,000, being 20% less than the book value, and the remaining was sold at 30% above the book value. The amount realised from Machinery is:', '["₹71,000", "₹79,000", "₹80,000", "₹92,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q42'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'A and B are partners in a firm. On 31st March 2026, they decided to dissolve the firm as the business had been running in loss for the last three years. This mode of dissolution is known as _______ and is covered by Section _____ of the Partnership Act, 1932.', '["Compulsory Dissolution, 41", "Dissolution by Agreement, 41", "Compulsory Dissolution, 40", "Dissolution by Agreement, 40"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q43'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'At the time of dissolution of a firm, which of the following will NOT be debited to the Realisation A/c?', '["Realisation of Asset", "Payment of Liability by a partner", "Liability taken over by a partner", "Realisation Expense"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q45'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'medium', 'Which of the following will NOT be recorded in the Realisation A/c?', '["Payment of unrecorded liabilities.", "Realisation of unrecorded assets.", "Assets taken over by a creditor for the settlement of his claim.", "Realisation expenses paid by a partner."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q46'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'The firm of A and B was dissolved. A agreed to pay the expenses on dissolution. The expense on dissolution amounted to ₹10,000, which was paid by the firm on behalf of A. Which of the following is the correct journal entry for recording it?', '["Realisation A/c Dr To Cash A/c", "Realisation A/c Dr To A’s Capital A/c", "A’s Capital A/c Dr To Cash A/c", "A’s Capital A/c Dr To Realisation A/c =====PAGE 122===== CUET UG Accountancy 118"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q47'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Goodwill', 'hard', 'At the time of dissolution of the firm, goodwill appeared in the books at ₹30,000. No information was given regarding its realisation. Which of the following will be the correct treatment?', '["Goodwill will only be debited to the Realisation A/c by ₹30,000.", "Goodwill will be debited and credited to the Realisation A/c by ₹30,000.", "Goodwill will be debited to the Realisation A/c and credited to capital accounts of the partners by ₹30,000.", "No entry will be made for goodwill."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q48'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'easy', 'Which of the following sections of the Partnership Act 1932 defines dissolution of the firm?', '["Section 32", "Section 39", "Section 35", "Section 37"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q50'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'hard', 'A firm is dissolved with assets worth ₹1,00,000. The liabilities are as follows: Outside Creditors: ₹40,000 Partner A’s Loan to the firm: ₹20,000 Partner B’s Capital: ₹50,000 Partner A’s Capital: ₹30,000 The assets realised for ₹1,60,000. According to Section 48, what is the final amount Partner B will receive?', '["₹50,000", "₹60,000", "₹40,000", "₹12,500"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q51'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'Partners X and Y share profits in a 3:2 ratio. Upon dissolution, the firm suffers a loss of ₹50,000 (including capital deficiency). X’s capital is ₹40,000, and Y’s capital is ₹10,000. According to Section 48', '[", how much must Partner Y contribute to cover the loss?", "₹10,000", "₹20,000", "₹25,000 (d) ₹30,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q52');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution of a Partnership Firm', 'hard', 'Z, a partner in a firm being dissolved, has private property worth ₹80,000 and private debts of ₹50,000. The firm owes ₹ 1,00,000 to its creditors. How much of Z’s private property can be used to pay the firm’s creditors?', '["₹80,000", "₹50,000", "₹30,000", "Nil"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q53'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'In the Balance Sheet of a firm, Bank Overdraft appears at ₹20,000. There is no Bank balance on the asset side. At the time of dissolution, how will the bank overdraft be dealt?', '["Bank Overdraft will be transferred to the debit of the Realisation A/c.", "Bank Overdraft will be transferred to the credit of the Realisation A/c.", "Bank Overdraft will be transferred to the debit of the Cash A/c.", "Bank Overdraft will be transferred to the credit of the Cash A/c."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q54'),
  ('Accountancy', 'Dissolution of a Partnership Firm', 'Dissolution', 'hard', 'The Balance Sheet shows Bank Balance (Asset Side): ₹5,000 and Bank Overdraft (Liability Side): ₹12,000. If the accountant decides to maintain a single Bank Account for dissolution, what is the opening balance of the Bank Account?', '["Debit balance of ₹5,000", "Credit balance of ₹12,000", "Credit balance of ₹7,000", "Debit balance of ₹7,000 Assertion – Reason – Based Questions Given below are two statements, one labelled as Assertion (A) and the other labelled as Reason (R). Read the statements and choose the correct option. (a) Both A and R are true, and R is the correct explanation of A. (b) Both A and R are true, but R is not the correct explanation of A. (C) A is true, but R is false. (d) A is false, but R is true. ( e) Both A and R are incorrect."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Dissolution of a Partnership Firm · Q55'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'hard', 'A Ltd. issued 50,000 shares of ₹10 each, and applications were received for 75,000 shares. Some of the shares were rejected, and others were allotted on a pro-rata basis in such a way that those who applied for 9000 shares were allotted 7500 shares. Find the number of applications that were rejected.', '["15000", "1500", "25000", "10000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q1'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'The minimum subscription should be received within:', '["45 days of issue of the prospectus", "30 days of issue of the prospectus", "120 days of issue of the prospectus", "90 days of issue of the prospectus"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q2'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'As per Companies Act 2013, the application money on shares should not be less than:', '["5% of Issue Price", "25% of Issue Price", "5% of Nominal Value", "25% of Nominal Value"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q3'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'Share Application A/c is a ______ account.', '["Personal", "Nominal", "Real", "None of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q4'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'ESOP offered by the company helps to create:', '["A sense of belongingness in employees", "High calibre", "High Productivity", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q5'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'The rules contained in Table F become applicable:', '["When Memorandum of Association is silent", "When Prospectus is silent", "When Articles of Association is silent", "Always."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q6'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'Pro-rata allotment is made in case of:', '["Undersubscription of shares", "Oversubscription of shares", "Full Subscription of shares", "None of the above"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q7'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'X Ltd issued 10,000 equity shares of ₹10 each, the amount was payable as ₹2 on Application, ₹4 on Allotment and balance in two equal instalments. All the shares were duly applied. Mr. A, the holder of 500 shares failed to pay allotment and call money. Mr. B, the holder of 300 shares failed to pay both calls, and Mr. C the holder of 200 shares failed to pay the final call money. The amount of share capital shown in B/s will be:', '["₹90,000", "₹1,00,000", "₹94,000", "₹94,400"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q8'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'X Ltd issued 10,000 equity shares of ₹10 each, the amount was payable as ₹2 on Application, ₹4 on Allotment and balance in two equal instalments. Applications were received for 15000 shares, out of which 3000 applications were rejected and remaining were allotted on pro-rata basis. All the money was duly received. The Subscribed share capital will be:', '["₹1,00,000", "₹1,50,000", "₹50,000", "₹1,20,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q9'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'Preference shares cannot be redeemed during the life time of the company.', '["Only 1", "Only 1 and 2", "Only 3", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q3'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'The first step in the procedure of issue of shares is:', '["Allotting Shares", "Accepting applications", "Issuing Prospectus", "Making Calls"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q11'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'hard', 'Which of the following statements is correct?', '["Subscribed Capital is the amount of share capital which a company is authorised to issue by its Memorandum of Association.", "Subscribed Capital is that part of the called-up capital which has been actually received from shareholders.", "Subscribed Capital is that part of authorised capital which is actually issued to the public for subscription.", "Subscribed Capital is that part of the issued capital which has been actually subscribed by the public."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q12'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'Shares on which the company has not received the entire nominal value is shown under:', '["Subscribed but not fully paid-up", "Paid up capital", "Subscribed and fully paid-up", "Called up capital PRACTICE CORNER =====PAGE 149===== Accounting for Share Capital 145"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q13'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'L Ltd. forfeited M’s shares. M, who had applied for 1200 shares of ₹10 each and was allotted 800 shares, failed to pay allotment money of ₹ 4 per share including premium of ₹2. She had paid only the application money of ₹2 per share. The first and final call was not yet called. The Journal entry for forfeiture of shares by opening calls in arrears account will be:', '["Share Capital A/c Dr 12000 To Calls in Arrears A/c 4800 To Share Forfeiture A/c 7200", "Share Capital A/c Dr 4800 Securities Premium A/c Dr 12400 To Calls in Arrears A/c 3200 To Share Forfeiture A/c 4000", "Share Capital A/c Dr 3200 Securities Premium A/c Dr 1600 To Calls in Arrears A/c 2400 To Share Forfeiture A/c 2400", "Share Capital A/c Dr 3200 Securities Premium A/c Dr 1600 To Calls in Arrears A/c 3200 To Share Forfeiture A/c 1600"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q14'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'A forfeited share can:', '["Not be re-issued at discount", "Be re-issued at a maximum discount of 10%", "Be re-issued at a maximum discount equal to the amount forfeited", "Be re-issued at a maximum discount equal to the called up amount"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q15'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'A company forfeited 4,000 shares of ₹10 each on which application money of ₹3 has been paid. Out of these 2,000 shares were reissued as fully paid up and ₹4,000 has been transferred to capital reserve. Calculate the rate at which these shares were reissued:', '["₹10 per share", "₹9 per share", "₹11 per share", "₹8 per share"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q16'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'The part of authorised capital which can be called up only on the company being wound up is called:', '["Authorised Capital", "Called-up Capital", "Reserve Capital", "Paid-up Capital"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q17'),
  ('Accountancy', 'Accounting for Share Capital', 'Financial Management', 'medium', 'They have a preferential right to receive dividend but at a fixed rate, they are:', '["Equity Shareholders", "Preference Shareholders", "Debenture holders", "Promoters"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q18'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'Issued capital is a part of ______.', '["Authorised Capital", "Subscribed Capital", "Unsubscribed Capital", "None of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q19'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'G Ltd. is a newly formed company. How much discount per share can it allow for issuing its shares to the public?', '["12%", "5%", "10%", "Shares cannot be issued at discount."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q20'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'When forfeited shares are re-issued the amount of discount allowed on these shares cannot exceed:', '["10% of called-up capital per share", "10% of paid-up capital per share", "10% of nominal value per share", "The forfeited amount per share"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q21'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'The ‘minimum subscription’ of capital cannot be less than _____ of the issued amount.', '["10%", "25%", "15%", "90%"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q22'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'According to which feature of a company we can say that “Members may come, Members may go but the company goes on forever” .', '["Limited Liability", "Separate Legal Entity", "Perpetual Existence", "Common Seal"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q23'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'Which of the following is NOT a feature of One Person Company?', '["No minimum capital required", "Requires only one natural person", "Its average annual turnover of three years exceeds Rs. 2 Crores.", "It cannot carry out non-banking financial investment activities."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q24'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'easy', 'Forfeiture of shares leads to reduction of _____ Capital.', '["Authorised", "Subscribed", "Uncalled up", "Issued"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q25'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'Which one of the following is a liability for the company?', '["Interim Dividend", "Dividend Arrears on Cumulative Preference Shares", "Unclaimed Dividend", "Proposed Dividend =====PAGE 150===== CUET UG Accountancy 146"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q26'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'What is the maximum limit of premium on issue of share?', '["25%", "10%", "20%", "Unlimited"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q27');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'Z Ltd. issued 10,000 shares, and applications were received for 12,000 shares. Which of the following options are available to the company:', '["Reject 2000 applications", "Allot 10,000 shares to the applicants of 12000 shares on proportionate basis.", "Allot full shares to some of the applicants and on proportionate basis to some of them.", "All of the above."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q28'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'hard', 'Issued Capital = 10,000 shares of ₹10 each. Applications received = 9,000 shares. Identify the kind of subscription.', '["Over Subscription", "Under Subscription", "Full Subscription", "Minimum Subscription"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q29'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'medium', 'Which of the following is NOT a purpose for which the Securities Premium amount can be used?', '["Issuing partly paid-up bonus shares to shareholders", "Writing off preliminary expenses of the company", "Buy back of shares", "To write off the commission paid or expenses on issue of shares/debentures."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q30'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'The first stage of incorporating a company is:', '["Registration", "Commencement of business", "Promotion", "Issue of Shares"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q31'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'The owners of the shares are called:', '["Creditors", "Partners", "Shareholders", "Debtors"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q32'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'Reserve capital is NOT a part of:', '["Authorised Capital", "Unsubscribed Capital", "Subscribed Capital", "Uncalled up Capital"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q33'),
  ('Accountancy', 'Accounting for Share Capital', 'Financial Markets', 'easy', 'As per SEBI, application money on shares should not be less than:', '["25% of issue price", "25% of par value", "5% of issue price", "5% of par value"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q34'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'easy', 'As per the rules given in Table F, interest on calls in advance is allowed at rate of:', '["10% per annum", "12% per annum", "10%", "12%"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q35'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'A notice of atleast ______ should be given to the defaulters before forfeiting their shares.', '["7 days", "14 days", "21 days", "30 days"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q36'),
  ('Accountancy', 'Accounting for Share Capital', 'Marketing', 'hard', 'Mr. X, the applicant of 15000 shares was allotted 5000 shares. He paid ₹3 per share with application. The allotment money was ₹4 per share and the first and final call was ₹3 per share. It was decided that the excess money received on application will be adjusted towards allotment and call. The amount received as call in advance by Mr X is:', '["Nil", "₹10,000", "₹15,000", "₹30,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q37'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'hard', 'Which of the following statements is true?', '["The rate of dividend is fixed on preference shares", "Preference shareholders have the right to receive dividends before the equity holders.", "Preference shares can be redeemed during the lifetime of the company", "All of these"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q38'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'A company issued 5,000 equity shares of ₹100 each at par payable as: ₹40 on application; ₹50 on allotment and ₹10 on call. Applications were received for 8,000 shares. The allotment was made on pro-rata. How much amount will be received in cash on allotment?', '["₹2,50,000", "₹1,20,000", "₹1,30,000", "₹50,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q39'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'A Ltd issued 10,000 shares @ ₹10 each, the whole amount was payable along with the application. Applications were received for 15,000 shares, and all applicants were allotted on pro-rata basis. What amount will be credited to Share Capital A/c?', '["₹1,00,000", "₹1,50,000", "₹50,000", "None of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q40'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'hard', 'A building was purchased for ₹9,00,000, and payment was made in shares of ₹100 each issued at 20% premium. Securities Premium A/c will be____________', '["Debited by ₹1,50,000", "Credited by ₹1,50,000", "Debited by ₹1,80,000", "Credited by ₹1,80,000 =====PAGE 151===== Accounting for Share Capital 147"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q41'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'Shares can be issued:', '["Only for Cash", "Only for consideration other than cash", "For cash or for consideration other than cash", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q42'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'If Shares of ₹4,00,000 are issued for purchase of assets of ₹5,00,000; ₹1,00,000 will be treated as_______', '["Discount", "Premium", "Profit", "Loss"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q43'),
  ('Accountancy', 'Accounting for Share Capital', 'Accounting for Share Capital', 'easy', 'An issue of shares to a selected group of persons is called:', '["Public offer", "Private placement of shares", "Initial public offer", "None of these"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q44'),
  ('Accountancy', 'Accounting for Share Capital', 'Goodwill', 'hard', 'A Ltd. acquired the following assets and liabilities of B Ltd. for a purchase consideration of ₹5,00,000. ₹ Inventory 1,00,000 Machinery 3,00,000 Debtors 80,000 Creditors 30,000 In the given case, there is a _______ (goodwill/capital reserve) of ₹_____.', '["Goodwill, 50,000", "Capital Reserve, 50,000", "Goodwill, 10,000", "Capital Reserve, 10,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q45'),
  ('Accountancy', 'Accounting for Share Capital', 'Financial Management', 'medium', 'Which type of preference share ensures that if a company misses a dividend payment, the unpaid amount is carried forward as arrears and must be settled before any dividends are distributed to common shareholders?', '["Non-cumulative Preference Shares", "Cumulative Preference Shares", "Non-participating Preference Shares", "Adjustable-rate Preferred Stock"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q46'),
  ('Accountancy', 'Accounting for Share Capital', 'Share capital', 'hard', 'Holders of which type of preference share are entitled to receive a fixed dividend and also participate in additional surplus profits alongside equity shareholders if the company achieves certain financial milestones?', '["Participating Preference Shares", "Non-participating Preference Shares", "Convertible Preference Shares", "Redeemable Preference Shares Assertion – Reason – Based Questions Given below are two statements, one labelled as Assertion (A) and the other labelled as Reason (R). Read the statements and choose the correct option. (a) Both A and R are true, and R is the correct explanation of A. (b) Both A and R are true, but R is not the correct explanation of A. (c) A is true, but R is false. (d) A is false, but R is true. ( e) Both A and R are incorrect."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Accounting for Share Capital · Q47'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'The debentures where a charge is created on the assets of the company for the purpose of payment in case of default are known as:', '["Secured Debentures", "Unsecured Debentures", "Redeemable Debentures", "Convertible Debentures"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q2'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'N Ltd purchased assets of the value of ₹4,20,000 from P Ltd and agreed to make the payment by a cheque of ₹40,000 and the remaining by issuing 4,000, 10% debentures of ₹100. Identify the correct entry to be made at the time of making payment to P Ltd.', '["P Ltd Dr 4,20,000 To Bank A/c 40,000 To 10% Debentures A/c 3,60,000", "P Ltd Dr 4,60,000 To Bank A/c 40,000 To 10% Debentures A/c 4,00,000", "P Ltd Dr 4,20,000 Discount on Issue of Debentures A/c Dr 20,000 To Bank A/c 40,000 To 10% Debentures A/c 4,00,000", "P Ltd Dr 4,20,000 Goodwill A/c Dr 20,000 To Bank A/c 40,000 To 10% Debentures A/c 4,00,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q3'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A debenture of ₹100 is issued at 10% discount and is redeemable at 5% premium. The amount debited to Loss on Issue of Debentures A/c will be:', '["₹10", "₹5", "₹15", "Nil"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q4'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'Which of the following statements is NOT true about debentures?', '["Interest on debentures is a charge against profits.", "Debentures cannot be issued at a discount.", "Debenture holders are the creditors of a company.", "Interest is not paid on Debentures issued as Collateral Security."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q5'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'S Ltd. issued 3,000, 7% Debentures of ₹100 each at a premium of 10%. According to the terms of issue, 30% of the amount was payable on application and the balance on allotment. The issue was fully subscribed and all amounts were duly received. Determine the amount received on application.', '["₹90,000", "₹99,000", "₹95,000", "₹3,00,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q6'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'Which of the following is incorrect about debentures?', '["Loss on Issue of Debentures is a capital loss for the company.", "Loss on Issue of Debentures can be written off from Securities Premium and Statement of Profit and Loss.", "Loss on issue of debentures includes discount on issue of debentures and premium on redemption of debentures.", "None of these"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q7'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'P Ltd. purchased assets of the value of ₹3,20,000 from A Ltd. and made the payment of purchase consideration by issuing 11% Debentures of ₹100 each at a discount of 20%. The number of debentures issued by P Ltd. were:', '["3,200", "32,000", "40,000", "4,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q8'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'Debenture holders are:', '["Supplier of the Company", "Shareholders of the Company", "Creditors of the Company", "Promoters of the Company"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q9'),
  ('Accountancy', 'Issue of Debentures', 'Issue of Debentures', 'hard', 'Which of the following statements is NOT correct?', '["A debenture is a formal document (or certificate) issued by a company under its common seal, acknowledging its debt to the holder.", "Irredeemable debentures are repaid during the lifetime of the company.", "A debenture is a part of borrowed capital.", "The debentures can be issued at par, premium or discount. PRACTICE CORNER =====PAGE 181===== Issue of Debentures 177"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q10'),
  ('Accountancy', 'Issue of Debentures', 'Issue of Debentures', 'easy', 'Collateral Security means primary security.', '["Only 3", "Only 1", "Both 1 and 2", "All of the given statements"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q3');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'Premium on Redemption of Debentures Account is:', '["Personal Account", "Real Account", "Nominal Account", "All of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q12'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'X Ltd., issued 10,000, 11% debentures of ₹100 each at a premium of 10% payable as follows: On application: ₹40 per debenture On allotment: ₹60 per debenture What amount will be debited to Debentures Allotment A/c while making the allotment money due?', '["₹6,00,000", "₹6,60,000", "₹7,00,000", "₹1,10,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q13'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'At the time of issue, the Debentures Account is:', '["Credited by the face value of debentures.", "Credited by the amount received.", "Credited by the issue price of the debentures.", "None of the above."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q14'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'The word debenture comes from the Latin word debere, which means ______.', '["To lend", "To give", "To borrow", "To purchase"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q15'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A debenture of ₹100 is issued at 5% premium and is redeemable at 10% premium. The amount debited to Loss on Issue of Debentures A/c will be:', '["₹5", "₹10", "₹15", "Nil"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q16'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'These debentures that do not carry a particular rate of interest are called ______.', '["Unsecured Debentures", "Convertible Debentures", "Zero-Coupon Rate Debentures", "Bearer Debentures"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q17'),
  ('Accountancy', 'Issue of Debentures', 'Issue of Debentures', 'hard', 'Which of the following statements is false?', '["At maturity, debenture holders get back their money.", "Debentures can be forfeited for non-payment of call money.", "In the company’s balance sheet, debentures are shown under the head Long-term Borrowings.", "Interest on debentures is a charge against profits."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q18'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'Which of the following statements is incorrect with respect of convertible debentures?', '["They can be converted into equity shares or into any other security, either at the choice of the enterprise or the debenture holders.", "They can be either fully convertible or partly convertible.", "Both of the above statements.", "None of the above statements."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q19'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'At the time of issue of debentures as collateral security, the amount of debentures issued is debited to:', '["Debentures A/c", "Statement of P&L", "Debentures Suspense A/c", "Capital Reserve A/c"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q20'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'These debentures are also called as Perpetual Debentures; these are:', '["Convertible Debentures", "Secured Debentures", "Zero-coupon rate debentures", "Irredeemable debentures"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q21'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'N Ltd purchased assets of the value of ₹5,80,000 from M Ltd and agreed to make the payment of purchase consideration by issuing 6,000, 10% debentures of ₹100. The debentures are issued at a ______ (premium/ discount) of ₹____ .', '["Premium, 20,000", "Premium, 10,000", "Discount, 20,000", "Discount, 10,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q22'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'The debentures can be issued:', '["At Par only", "At Discount or Premium only", "At Par or Premium only", "At Par, Premium or Discount"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q23'),
  ('Accountancy', 'Issue of Debentures', 'Issue of Debentures', 'medium', 'A fixed charge is created on a _____ asset whereas a floating charge is on the ____ assets of the company.', '["Specific, fixed", "General, current", "Fixed, general", "Specific, general"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q24'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'Debentures are shown in the Balance Sheet of a company under the head of:', '["Non-current Liabilities", "Current Liabilities", "Share Capital", "Reserves and Surplus =====PAGE 182===== CUET UG Accountancy 178"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q25'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A Ltd purchased assets of the book value of ₹4,00,000 from B Ltd and agreed to make the payment of purchase consideration by issuing 4,200, 10% debentures of ₹100 each. The debentures are issued at:', '["Premium of 5%", "Discount of 5%", "Premium of 10%", "Par"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q26'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'Which of the following statements is true with respect to convertible debentures?', '["They can be converted into equity shares or into any other security only at the choice of the company.", "They can be converted into equity shares or into any other security only at the choice of the debenture holders.", "They can be converted into equity shares or into any other security either at the choice of the enterprise or the debenture holders.", "They cannot be converted into equity shares or in any other security."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q27'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'N Ltd issued 5,000, 10% debentures of Rs. 100 each at 5% discount and redeemable at 10% premium. The balance in the Securities Premium Account is ₹50,000. What amount of loss on the issue of debentures will be written off against the Statement of P&L?', '["₹75,000", "₹50,000", "₹25,000", "Nil"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q28'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'T Ltd., issued 10,000, 12% debentures of ₹100 each at a discount of 5%, payable as follows: On application: ₹40 per debenture On allotment: ₹55 per debenture What amount will be debited to 12% Debentures A/c while making the allotment money due?', '["₹5,50,000", "₹6,00,000", "₹5,22,500", "₹9,50,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q29'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'E Ltd. issued 2,000, 9% Debentures of ₹100 each at a discount and redeemable at 5% premium. On the issue of these debentures, ‘Loss on Issue of Debentures Account’ was debited with ₹30,000. The discount on issue of debentures is:', '["₹10,000", "₹20,000", "₹25,000", "₹5,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q30'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A Ltd. issued 10,000, 7% debentures of ₹100 each at a discount of 5%, redeemable at a premium of 5%. Discount on issue and premium on redemption were accounted for through ‘Loss on Issue of Debentures Account.’ On the issue of debentures, ‘Loss on Issue of Debentures Account’ will be:', '["Debited by ₹50,000", "Debited by ₹1,00,000", "Credited by ₹50,000", "Credited by ₹1,00,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q31'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'The debentures whose principal amount is not repayable by the company during its lifetime, but the payment is made only at the time of Liquidation of the company, such debentures are called', '["Bearer Debentures", "Redeemable Debentures", "Irredeemable Debentures", "Non-Convertible Debentures"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q32'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'Debenture holders are entitled to receive ______ from the company.', '["Dividend", "Interest at fixed rate", "Interest at flexible rates", "Share of Profit"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q33'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'G Ltd. purchased assets of the book value of ₹1,20,000 from Ram Bros. It was agreed that the purchase consideration will be paid by issuing 10% debentures of ₹100 each at 20% premium. Identify the correct journal entry to be made for making a payment to the vendor.', '["Ram Bros Dr 1,00,000 To 10% Debenture A/c 1,00,000", "Ram Bros Dr 1,20,000 To 10% Debenture A/c 1,20,000", "Ram Bros Dr 1,20,000 To 10% Debenture A/c 1,00,000 To Securities Premium A/c 20,000", "Ram Bros Dr 1,40,000 To 10% Debenture A/c 1,20,000 To Securities Premium A/c 20,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q34'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'The payment of interest on debentures is _____ profits of the company.', '["Charge against", "Appropriation of", "Neither charge nor appropriation", "Both charge and appropriation"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q35'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', '1000, 12% Debentures of ₹100 each are issued at 10% discount and redeemable at 5% premium. The Balance in Securities Premium A/c is ₹6,000, and the Statement of Profit and Loss shows a credit balance of ₹15,000. =====PAGE 183===== Issue of Debentures 179 While writing off the ‘Loss on Issue of Debentures’ , the Securities Premium A/c will be debited by:', '["₹15,000", "₹6,000", "₹9,000", "Nil"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q36'),
  ('Accountancy', 'Issue of Debentures', 'Goodwill', 'hard', 'B Ltd., purchased assets worth ₹1,50,000 and took over liabilities of ₹30,000 for a purchase consideration of ₹1,00,000, which was paid by issuing 10% debentures at par. Here there is ________ (goodwill or capital reserve) of ₹______.', '["Goodwill, 20,000", "Capital Reserve, 20,000", "Goodwill, 50,000", "Capital Reserve, 50,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q37'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'The discount on issue of debentures is:', '["Capital Reserve", "Capital gain", "Capital loss", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q38'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'X Ltd., issued 10,000, 12% debentures of Rs. 100 each at a premium of 10%, payable as follows: On application: ₹60 per debenture On allotment: ₹50 per debenture What amount will be debited to 12% Debentures A/c while making the allotment money due?', '["₹5,50,000", "₹6,00,000", "₹5,00,000", "₹4,00,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q39'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'Debentures cannot be issued as Collateral Security.', '["Both 1 and 2", "Only 1", "Only 2", "All of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q3'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A Company issued 2,000, 12% debentures of ₹100 each at par but redeemable at 5% premium. Loss on issue of debentures will be:', '["₹10,000", "₹12,000", "₹11,000", "None of the three"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q41');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'Premium received on issue of debentures is credited to _____ Account.', '["Capital Reserve", "General Reserve", "Securities Premium", "Any of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q42'),
  ('Accountancy', 'Issue of Debentures', 'Issue of Debentures', 'hard', 'Which of the following statements is NOT true?', '["Debentures can be issued for cash only.", "Debentures can be issued at a discount.", "Debentures can be issued for consideration other than cash.", "Debentures can be issued as collateral security."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q43'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'The debentures which can be transferred by way of delivery are called:', '["Unsecured Debentures", "Non-Convertible Debentures", "Registered Debentures", "Bearer Debentures"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q44'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', '5000, 12% Debentures of ₹100 each are issued at 5% discount and redeemable at 10% premium. The Balance in Securities Premium A/c is ₹60,000 and the Statement of Profit and Loss shows a credit balance of ₹1,50,000. While writing off the ‘Loss on Issue of Debentures’ , the Statement of Profit and Loss will be debited by:', '["₹75,000", "₹15,000", "₹1,50,000", "Nil"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q45'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'N Ltd purchased assets of the value of ₹4,20,000 from P Ltd and agreed to make the payment by a cheque of ₹20,000 and the remaining by issuing 3,600, 10% debentures of ₹100. Identify the correct entry to be made at the time of making payment to P Ltd.', '["P Ltd Dr 4,20,000 To Bank A/c 20,000 To 10% Debentures A/c 3,60,000 To Securities Premium A/c 40,000", "P Ltd Dr 4,20,000 To 10% Debentures A/c 3,60,000 To Securities Premium A/c 60,000", "P Ltd Dr 3,80,000 To Bank A/c 20,000 To 10% Debentures A/c 3,60,000", "P Ltd Dr 4,20,000 To Bank A/c 20,000 To 10% Debentures A/c 3,60,000 To Capital Reserve A/c 40,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q46'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'S Ltd. issued 3,000, 7% Debentures of ₹100 each at a premium of 10%. According to the terms of issue, 40% of the amount was payable on application and the balance on allotment. The issue was fully subscribed and all amounts were duly received. Determine the amount received on allotment.', '["₹2,10,000", "₹2,40,000", "₹3,30,000", "₹2,31,000 =====PAGE 184===== CUET UG Accountancy 180"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q47'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'easy', 'A debenture of ₹100 is issued at par and redeemable at 5% premium. The amount of loss on debentures will be:', '["₹5", "₹105", "₹95", "Nil"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q48'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'G Ltd. purchased assets of the book value of ₹1,20,000 from H Ltd. It was agreed that the purchase consideration would be paid by issuing 10% debentures of ₹100 each at 20% discount. Identify the correct journal entry to be made for making a payment to the vendor.', '["H Ltd Dr 90,000 Discount on Issue of Debentures Dr 30,000 To 10% Debenture A/c 1,20,000", "H Ltd Dr 1,20,000 Discount on Issue of Debentures Dr 30,000 To 10% Debenture A/c 1,50,000", "H Ltd Dr 1,50,000 To 10% Debenture A/c 1,50,000", "H Ltd Dr 1,20,000 To 10% Debenture A/c 1,20,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q49'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A company takes a loan of ₹5,00,000 from a bank and issues 6,000, 10% Debentures of ₹100 each as collateral security. If the company decides not to pass a journal entry for the issue of debentures, how will this be shown in the Balance Sheet?', '["Debentures will be added to Long-term Borrowings.", "A footnote/note to accounts will be added under the Bank Loan.", "₹6,00,000 will be shown as an asset.", "Only the interest of 10% will be recorded."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q50'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'X Ltd. took a loan of ₹8,00,000 from SBI and issued 10,000, 9% Debentures of ₹100 each as collateral security. The company follows the method of recording the issue by passing a journal entry. What is the balance in the Debenture Suspense Account?', '["₹8,00,000", "₹1,80,000", "₹10,00,000", "₹2,00,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q51'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'medium', 'How is the Debenture Suspense Account presented in the Balance Sheet?', '["As a Current Asset", "As a deduction from the Debentures Account under Long-term Borrowings", "As a Non-Current Asset", "As an addition to the Bank Loan"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q52'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'A company issues ₹2,00,000, 12% Debentures as collateral security for a bank loan of ₹1,50,000. The bank loan carries an interest rate of 10% p.a. What is the total interest expense recorded by the company on these debentures at the end of the year?', '["₹24,000", "₹15,000", "₹39,000", "Nil"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q53'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'Y Ltd. defaulted on a loan of ₹4,00,000 (including interest). The bank held ₹5,00,000 worth of debentures as collateral. Upon default, the bank invokes the collateral. What happens to the “Debenture Suspense Account”?', '["It is transferred to the Profit & Loss Account.", "It is cancelled by a reverse entry.", "It is shown as a Loss on Issue of Debentures.", "It is added to the Capital Reserve."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q54'),
  ('Accountancy', 'Issue of Debentures', 'Debentures', 'hard', 'X Ltd. issued 10,000 12% Debentures of ₹100 each on 1st October 2025 at 10% discount. The debenture interest is to be paid half-yearly. The Reserves and Surplus consisted of Capital Reserve of ₹50,000 and a balance in Statement of Profit and Loss of ₹1,80,000. On 31st March 2026, the Statement of Profit and Loss will be debited by:', '["₹1,20,000", "₹60,000", "₹1,60,000", "₹1,10,000 Assertion – Reason – Based Questions Given below are two statements, one labelled as Assertion (A) and the other labelled as Reason (R). Read the statements and choose the correct option. (a) Both A and R are true, and R is the correct explanation of A. (b) Both A and R are true, but R is not the correct explanation of A. (c) A is true, but R is false. (d) A is false, but R is true. ( e) Both A and R are incorrect."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Issue of Debentures · Q55'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'The balance sheet is also known as:', '["Income Statement", "Position Statement", "Cash Flow Statement", "None of these"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q5'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Share capital', 'easy', 'Which of the following is added to ‘Subscribed Share Capital’?', '["Calls-in-Advance", "Forfeited Share Account", "Calls-in-Arrears", "None of these"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q6'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'hard', 'In a company, current assets are ₹90,000 and total assets are ₹9,00,000. What will be the percentage of current assets to total assets?', '["10%", "15%", "5%", "7.5%"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q7'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'medium', '_________ appear in a Company’s Balance Sheet under the Sub-head Short term provision.', '["Interest Accrued but not due on Borrowings", "Provision for Tax", "Calls in Advance", "Unpaid Dividend"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q8'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'In a company, revenue from operations is ₹10,00,000 in 2022-23 and ₹16,00,000 in 2023-24, what will be the percentage change?', '["60%", "50%", "45%", "80%"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q9'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'medium', 'The balance sheet of a company must be in the form set out in:', '["Part I of Schedule III of the Companies Act, 2013", "Part III of Schedule III of the Companies Act, 2013", "Part II of Schedule III of the Companies Act, 2013", "Part I of Schedule II of the Companies Act, 2013"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q10'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'medium', '‘Public Deposits’ appear in the company’s Balance Sheet under the head/subhead:', '["Intangible Assets", "Current Liabilities", "Non-Current Liabilities", "Current Assets"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q11'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial statements', 'easy', 'Common Size statement is also known as:', '["Horizontal Analysis", "Vertical Analysis", "Trend Analysis", "None of these"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q12'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial statements', 'medium', 'In a common size statement of profit and loss, which figure is assumed to be equal to 100?', '["Revenue from operations", "Net profit", "Total Expenses", "Any of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q13'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'medium', 'The analysis of actual movement of cash into and out of an organisation is called:', '["Comparative Statements", "Cash Flow Analysis", "Trend Analysis", "Ratio Analysis PRACTICE CORNER =====PAGE 210===== CUET UG Accountancy 206"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q14'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'Loose Tools 6. Capital Advances', '["1, 2 and 4", "1, 3 and 4", "1,3 and 5", "All of these"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q5'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial statements', 'hard', 'Assertion: Comparative statements are useful for evaluating a company’s financial performance against industry benchmarks. Reason: Comparative statements allow for an assessment of how a company is performing compared to industry benchmarks, which can provide helpful insights for making strategic decisions.', '["Both assertion", "and reason (R) are true, and reason (R) is the correct explanation of assertion", ".", "Both assertion (A) and reason (R) are true, but reason (R) is not the correct explanation of assertion (A). (c) Assertion (A) is true, but reason (R) is false. (d) Assertion (A) is false, but reason (R) is true. Directions (6-10): Read the following passage and answer the given questions. Study the data given below carefully: Particulars 2022-23 2021-22 Revenue from operations ₹6,00,000 ₹5,00,000 Other incomes (% of revenue from operations) 20% 20% Employee benefit expenses (% of Total Revenue) "]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q5'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'Find the absolute and percentage change in the total revenue.', '["1,00,000 and 20%", "20,000 and 20%", "1,20,000 and 20%", "20,000 and 40%"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q6'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'The percentage change in Employee benefit expenses is:', '["40%", "30%", "10%", "60%"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q7'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'medium', 'The profit before tax for 2021-22 is Rs.______ and 2022- 23 is Rs.________.', '["4,32,000; 4,20,000", "4,20,000; 4,32,000", "4,12,000; 4,20,000", "4,20,000; 4,12,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q8'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'medium', 'The percentage change in profit before tax and profit after tax will be the same because:', '["Rate of Tax is the same in both years", "Percentage change in total revenue and revenue from operations is the same", "Both of the above", "None of the above"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q9');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Share capital', 'hard', 'Mrs. X wants to know the absolute increase or decrease in the share capital of PQR Ltd. Which tool of analysis will help her in identifying this?', '["Comparative statement", "Common-size statements", "Trend Analysis", "Balance Sheet Directions (11-15): Read the following passage and answer the given questions. Study the Common Size Balance Sheet given below. Particulars 2022-23 2023-24 % of Balance Sheet Total I. Equity and Liabilities 2022-23 2023-24"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q10'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Share capital', 'easy', 'The share capital for 2023-24 will be:', '["18,00,000", "24,00,000", "9,00,000", "28,00,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q11'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'The total non-current assets for 2022-23 wil be:', '["21,00,000", "2,10,000", "15,00,000", "6,00,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q12'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Planning', 'hard', 'Statement I: The value of Property, Plant and Equipment is the same in both years. Statement II: The percentage of Property, Plant and Equipment as to total assets is the same in both years.', '["Statement I is correct, and Statement II is incorrect", "Statement I is incorrect, and Statement II is correct", "Both statements are correct", "Both statements are incorrect =====PAGE 217===== Financial Statements and Tools for Financial Analysis 213  "]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q13'),
  ('Accountancy', 'Financial Statements and Tools for Financial Analysis', 'Financial Statements and Tools for Financial Analysis', 'easy', 'The difference in the value of Cash and Cash Equivalents in both years is:', '["10,000", "1,00,000", "Nil", "3,00,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Financial Statements and Tools for Financial Analysis · Q14'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'easy', 'Which of the following is NOT included in Current assets?', '["Bills Receivable", "Inventory", "Goodwill", "Prepaid Expenses"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q1'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'hard', 'If the current Ratio of a firm is 2.5:1 and its current liabilities are ₹4,00,000. The current assets will be of:', '["₹6,00,000", "₹8,00,000", "₹16,00,000", "₹10,00,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q2'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'hard', 'Which of the following ratios provides the information regarding the long-run operation of the firm?', '["Liquidity Ratios", "Activity Ratios", "Solvency Ratios", "Profitability Ratios"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q3'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'easy', 'The ideal Debt-Equity Ratio is:', '["2:1", "1:1", "1:2", "1.5:1"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q4'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'hard', 'Average Inventory ₹30,000; Inventory turnover ratio 8 times, selling price 25% above cost. Revenue from Operations will be:', '["₹2,50,000", "₹3,00,000", "₹1,80,000", "₹2,40,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q5'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'hard', 'The debt equity ratio of X Ltd. is 0.5:1. Which of the given transactions will not affect the ratio?', '["Sale of goods on a cash basis ₹50,000.", "Further issue of equity shares ₹1,00,000.", "Further issue of debentures ₹1,00,000.", "None of the above"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q6'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'easy', 'Current ratio = 2.5:1 Quick ratio = 1.5:1 Current Liabilities = ₹36,000 The Inventories are of:', '["₹36,000", "₹54,000", "₹90,000", "₹24,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q7'),
  ('Accountancy', 'Ratio Analysis', 'Debentures', 'hard', 'Profit after tax amounted to ₹ 6,00,000, and the tax rate was 20%. If earnings before interest and tax were ₹ 9,50,000 and debentures amounted to ₹ 40,00,000 (assuming the only debt of the company). The Interest Coverage Ratio is:', '["4.57 times", "4.75 times", "5.47 times", "4.45 times"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q8'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'easy', '________ are calculated to analyse the earning capacity of the business', '["Solvency Ratios", "Liquidity Ratios", "Profitability Ratios", "Activity Ratios"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q9'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'hard', 'Which of the following is an objective of Ratio Analysis?', '["To provide information useful for making projections and estimates for the future", "To provide a deeper analysis of the profitability, liquidity, solvency and efficiency levels in the business", "To know about the potential areas which can be improved", "All of these"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q10'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'easy', 'Which of the following is NOT a Solvency Ratio?', '["Interest Coverage Ratio", "Total Assets to Debt Ratio", "Return on Investment", "Debt-Equity Ratio"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q11'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'hard', 'The debt equity ratio of X Ltd. is 0.5:1. Which of the following transactions will result in a decrease in the ratio?', '["Sale of goods on cash basis ₹50,000.", "Further issue of equity shares ₹1,00,000.", "Further issue of debentures ₹1,00,000.", "Both B and C"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q12'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'easy', 'Change in gross profit ratio may be due to:', '["Change in selling price", "Change in cost of revenue from operations", "Both", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q13'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'medium', 'Which of the following is correct?', '["Proprietors’ Funds = Share Capital + Reserves and Surplus", "Proprietors’ Funds = Non-current Assets + Working Capital - Non-current Liabilities.", "Proprietors’ Funds = Non-current Assets + Current Assets - Non-current Liabilities - Current Liabilities", "All of the above PRACTICE CORNER =====PAGE 235===== Ratio Analysis 231"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q14'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'hard', 'Current ratio of a company is 3: 2. The accounts manager wants to maintain it at the ideal ratio. Which of the following options shall he choose? (i) He can repay bills payable (ii) He can purchase goods on credit (iii) He can take a short-term loan', '["Only (i)", "Only (ii)", "Only (i) and (iii)", "Only (ii) and (iii)"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q15'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'hard', 'Gross Profit Ratio of a Company is 25%. Cost of revenue from operations are 3/4th of revenue from operations. If revenue from operations is ₹60,00,000, the Gross Profit of the Company will be:', '["₹25,00,000", "₹45,00,000", "₹15,00,000", "₹11,25,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q16'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'easy', 'Current ratio =4.5:1 Quick ratio =3:1 Inventory = ₹36,000 The Current Liabilities are of:', '["₹36,000", "₹24,000", "₹30,000", "₹35,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q17'),
  ('Accountancy', 'Ratio Analysis', 'Ratio analysis', 'hard', 'A company’s current assets are ₹90,000, cost of revenue from operations is ₹1,25,000 current ratio is 3:1, Gross profit on cost is 10%, its working capital turnover ratio will be:', '["1.94 times", "2.29 times", "1.46 times", "2 times"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q18'),
  ('Accountancy', 'Ratio Analysis', 'Ratio Analysis', 'hard', 'Which of the following is NOT a limitation of Ratio Analysis?', '["Ignores Price Level Changes", "Ignores Qualitative Aspect", "Enables SWOT Analysis", "Analyses historical data"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Ratio Analysis · Q19'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'The cash flow statement analyses which of the following activities?', '["Operating activities", "Financing activities", "Investing activities", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q1'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Cash inflows from investing activities include:', '["Cash receipt from disposal of fixed assets, including intangibles.", "Cash receipt from the repayment of advances or loans made to third parties", "Cash receipt from disposal of shares, warrants or debt instruments of other enterprises except those held for trading purposes.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q2'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'While calculating cash flow from operating activities, which of the following will be added to the net profit?', '["Increase in Inventory", "Decrease in Inventory", "Increase in Debtors", "Decrease in Creditors"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q3'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'Mention the net amount of source or use of cash when a fixed asset (having book value ₹1,20,000) is sold at a loss of ₹40,000 in terms of cash flow.', '["Cash outflow ₹1,20,000", "Cash inflow ₹40,000", "Cash inflow ₹80,000", "Cash outflow ₹1,60,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q4'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following is considered while calculating cash from operating activity for a financial company?', '["Sale of the fixed asset", "Interest received from bank on term deposits", "Redemption of debentures", "Issuing Equity Shares"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q5'),
  ('Accountancy', 'Cash Flow Statement', 'Financial statements', 'medium', 'A financial statement that shows the inflows and outflows of cash during a particular period of time is known as:', '["Income statement", "Statement of retained earning", "Statement of cash flows", "Balance sheet"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q6');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'easy', 'Cash Flow Statement is based upon:', '["Cash basis of accounting", "Accrual basis of accounting", "Both of these", "None of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q7'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'easy', 'Which one of following is NOT a non-cash item?', '["Cash Sales", "Goodwill written off", "Depreciation", "Provision of Bad Debts"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q8'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'hard', 'Calculate Purchase of Investment, using the following information: Opening balance of Investment - ₹2,50,000, Closing balance Investment - ₹5,00,000, Sale of Investment - ₹1,37,500, Profit on sale - ₹12,500.', '["₹ 2,50,000", "₹ 3,75,000", "₹ 3,50,000", "₹ 2,75,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q9'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following results in the decrease in cash from operating activities?', '["Increase in Inventories", "Decrease in Trade Payables", "Both", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q10'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'medium', 'Which of the following transactions will result into ‘Flow of Cash’?', '["Deposited ₹10,000 into the bank.", "Withdrew cash from the bank ₹14,500.", "Sale of machinery of the book value of ₹74,000 at a loss of ₹9,000.", "Converted 2,00,000, 9% debentures into equity shares."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q11'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'easy', 'Cash Flow Statement is prepared from:', '["Balance Sheet", "Additional Information", "Statement of Profit and Loss", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q12'),
  ('Accountancy', 'Cash Flow Statement', 'Financial Management', 'medium', 'A dividend paid by a financial company is shown as cash outflow under:', '["Operating Activities", "Investing Activities", "Financing Activities", "Cash and Cash Equivalent PRACTICE CORNER =====PAGE 261===== Cash Flow Statement 257"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q13'),
  ('Accountancy', 'Cash Flow Statement', 'Goodwill', 'hard', 'If net profit is ₹35,000 after writing off goodwill ₹ 6,000 and loss on sale of furniture ₹1,000, cash flow from operating activities will be :', '["₹ 35,000", "₹ 42,000", "₹ 29,000", "₹ 28,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q14'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'medium', 'Which of the following transactions will result in NO flow of cash?', '["Purchase of machinery", "Sale of investments", "Acquisition of machinery by issue of equity shares", "Redemption of debentures"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q15'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'The proposed dividend for the year 2024-25 is ₹50,000 and for the year 2025-26 is ₹65,000. Which of the following statements is correct in respect of the treatment of proposed dividend while making cash flow statement for the year 2025-26?', '["₹50,000 will be added to NP for calculating Cash flow from Operating Activities.", "₹50,000 will be subtracted for calculating Cash flow from Financing Activities.", "₹65,000 will not be recorded in the cash flow statement.", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q16'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'Cash flow from Operating Activities = ₹28,000 Cash Flow from Financing Activities = ₹4,73,000 Opening Balance: Cash and Cash Equivalents = ₹1,60,000 Closing Balance: Cash and Cash Equivalents = ₹3,90,000 Cash Flow from/(Used in) Investing Activities = ?', '["Cash Flow from Investing Activities ₹2,71,000", "Cash Flow from Investing Activities ₹2,93,000", "Cash Used in Investing Activities ₹2,71,000", "Cash Used in Investing Activities ₹27,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q17'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following will NOT result in a cash flow from operating activities?', '["Collection of cash from receivables", "Payment of income tax", "Payment of cash for operating expenses", "Purchase of equipment for cash"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q18'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following is shown under Financing Activity?', '["Issue of Equity shares for cash", "Issue of Equity shares for consideration other than cash", "Purchase of Equity shares for cash", "All of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q19'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'hard', 'In case of a financial enterprise whose main business is lending and borrowing, ‘interest paid’ and ‘interest received’ are classified as:', '["Operating activities", "Investing activities", "Financing activities", "None of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q20'),
  ('Accountancy', 'Cash Flow Statement', 'Financial Management', 'hard', 'A Ltd., engaged in the business of retailing of two- wheelers, invested ₹50,00,000 in the shares of a manufacturing company. Dividend received on this investment will be:', '["Cash Flow from Investing Activities", "Cash Flow from Financing Activities", "Cash Flow from Operating Activities", "Cash Equivalent"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q21'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following will NOT result in cash flow?', '["Redemption of Debentures", "Loan taken from bank", "Conversion of Debentures into Equity Shares", "Payment to creditors"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q22'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'Cash flow from Operating Activities is ₹12,00,000, Cash used in Investing activities is ₹5,00,000 and Cash flow from Financing Activities is ₹3,00,000. What will be the amount of net increase or decrease in Cash and Cash equivalents?', '["Net Increase of ₹20,00,000", "Net decrease of ₹20,00,000", "Net Increase of ₹10,00,000", "Net decrease of ₹10,00,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q23'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'VK Ltd. has the following information: Cash flow from Operating Activities = ₹1,00,000 Cash used in Investing Activities = ₹30,000 Cash used in Financing Activities = ₹40,000 Opening Balance: Short term Investments = ₹78,000 Cash and Cash Equivalents = ₹80,000 Closing Balance: Short term Investments = ₹90,000 Cash and Cash Equivalents =?', '["₹ 98,000", "₹ 2,38,000", "₹ 68,000", "₹ 38,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q24'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following will result in cash flow?', '["Cash deposited into bank", "Depreciation on Fixed Asset", "Cash withdrawn from bank", "None of these =====PAGE 262===== CUET UG Accountancy 258"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q25'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'easy', 'When an asset having book value of ₹26,500 is sold at a loss of ₹16,500, the net cash flow will be:', '["₹ 20,000", "₹ 16,000", "₹ 10,000", "₹ 6,500"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q26'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Dividend paid by a Trading company is classified under which kind of activity while preparing Cash Flow Statement?', '["Cash outflow from Financing Activity", "Cash inflow from Operating Activity", "Cash outflow from Investing Activity", "Cash inflow from Financing Activity"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q27'),
  ('Accountancy', 'Cash Flow Statement', 'Goodwill', 'hard', 'If the net profit is ₹50,000 after writing off goodwill of ₹10,000, then what will be the cash flow from operating activities?', '["₹60,000", "₹50,000", "₹40,000", "₹70,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q28'),
  ('Accountancy', 'Cash Flow Statement', 'Debentures', 'hard', 'G Ltd. purchased machinery of ₹10,00,000 issuing a cheque of ₹2,50,000 and 10% Debentures of ₹7,50,000. In the Cash Flow Statement, the transaction will be shown as:', '["Outflow under Investing Activity ₹10,00,000, inflow under Financing Activity as Receipt for Debentures ₹7,50,000.", "Outflow under Investing Activity ₹2,50,000.", "Inflow of ₹7,50,000 as Financing Activity.", "None of these."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q29'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'hard', 'While calculating cash from operations which will be added to net profit?', '["Depreciation", "Goodwill written off", "Preliminary Expenses written off", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q30'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following results in Cash Outflows from investing activities?', '["Cash payments to acquire fixed assets", "Cash payments to acquire shares, warrants or debt instruments of other enterprises other than the instruments those held for trading purposes.", "Cash advances and loans made to third party", "All of the above"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q31'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'medium', 'While calculating operating profit which will be added to net profit:', '["Interest received", "Profit on sale of Asset", "Increase in General Reserve", "Refund of Tax"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q32'),
  ('Accountancy', 'Cash Flow Statement', 'Share capital', 'hard', 'X Ltd. purchased furniture for ₹20,00,000 paying 60% by issue of equity shares of ₹10 each and the balance by a cheque. This transaction will result in:', '["Cash generated from financing activities ₹12,00,000", "Cash used in investing activities ₹20,00,000", "Cash used in investing activities ₹8,00,000", "Increase in cash and cash equivalents ₹8,00,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q33'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'easy', 'Cash flow from operating activities can be calculated by:', '["Direct Method", "Indirect Method", "Any of these", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q35'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Investing activities are related with which of the following:', '["Sale or purchase of non-current assets", "Issue and Redemption of shares and Debentures", "Increase or Decrease in Current Assets", "Increase or Decrease in Current Liabilities"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q36'),
  ('Accountancy', 'Cash Flow Statement', 'Share capital', 'hard', 'On the basis of the following information, Net Cash Flow from Financing Activities will be: 31st March 2025 (₹) 31st March 2026 (₹) Equity Share Capital 4,00,000 5,00,000 12% Debentures 1,50,000 1,00,000 Securities Premium 40,000 50,000 Additional Information: Interest paid on debentures ₹18,000.', '["₹ 40,000", "₹ 42,000", "₹ 48,000", "₹ 50,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q37');
  INSERT INTO _ebook_q VALUES
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'If the net profits earned during the year is ₹50,000 and the amount of debtors in the beginning and the end of the year is ₹10,000 and ₹20,000 respectively, then what will be the cash from operating activities?', '["₹50,000", "₹60,000", "₹70,000", "₹40,000 =====PAGE 263===== Cash Flow Statement 259"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q38'),
  ('Accountancy', 'Cash Flow Statement', 'Financial Management', 'easy', 'A dividend paid by a non-financial company is shown in:', '["Operating Activities", "Investing Activities", "Financing Activities", "Cash and Cash Equivalent"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q39'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'Which of the following is included in Cash Flow from Operating Activities?', '["Royalties, Fees, Commission", "Purchase of Debentures", "Purchase of Machinery", "Issue of Shares"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q40'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'What is the Cash flow from operating activities from the following information? Particulars 31st March 2017 31st March 2016 Surplus i.e. Balance in statement of profit and Loss 7,70,000 8,40,000 Trade Receivable 3,50,000 4,34,000 Outstanding Rent 1,68,000 2,94,000 Prepaid Expenses 56,000 28,000 Trade Payables 1,82,000 2,66,000', '["₹14,000", "₹(70,000)", "₹(2,24,000)", "₹2,24,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q41'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'hard', 'From the books of E Ltd. we have As at 31st March 2025 As at 31st March 2026 Provision for Tax 50,000 75,000 Provision for tax made during the year ₹65000. The tax paid will be:', '["₹50,000", "₹60,000", "₹40,000", "₹75,000"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q42'),
  ('Accountancy', 'Cash Flow Statement', 'Partner''s loan', 'hard', 'From the following information, calculate operating profit before working capital changes Particulars Amount Net profit before working Tax and Extraordinary items 2,50,000 Depreciation 10,500 Interest on loan 2,000 Goodwill written off 2,500 Loss on sale of plant 1,250 Premium on Redemption of Debenture 800 Interest and Dividend received on Investments 7,400 Profit on sale of investment 1,500', '["₹2,58,150", "₹2,67,050", "₹2,50,000", "₹2,58,510"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q43'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'If a machine whose original cost is ₹40,000, having accumulated depreciation ₹12,000, was sold for ₹ 34,000, then while preparing the Cash Flow Statement, its effect on cash flow will be:', '["Cash flow from investing activities ₹34,000", "Cash flow from financing activities ₹34,000", "Cash flow from investing activities ₹6,000", "Cash flow from financing activities ₹6,000"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q44'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'easy', 'Interest paid is shown in the Cash Flow Statement under', '["Operating Activities", "Investing Activities", "Financing Activities", "None of these"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q47'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'medium', 'While preparing a Cash Flow Statement, Payment of Income Tax is shown as:', '["Operating Activity", "Investing Activity", "Financing Activity", "None of these"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q48'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'Net Profit during the year ₹1,00,000 Debtors at the beginning of the year: ₹30,000 Debtors at the end of the year: ₹36,000 What is the amount of cash from operating activities?', '["₹ 30,000", "₹ 94,000", "₹ 1,06,000", "₹ 1,16,000"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q49'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'hard', 'Which of the following Accounting Standards are related to the preparation of the Cash Flow Statement?', '["AS-3", "AS-6", "AS-9", "AS-12 =====PAGE 264===== CUET UG Accountancy 260 Assertion – Reason – Based Questions Given below are two statements, one labelled as Assertion (A) and the other labelled as Reason (R). Read the statements and choose the correct option. (A) Both A and R are true, and R is the correct explanation of A. (B) Both A and R are true, but R is not the correct explanation of A. (C) A is true, but R is false. (D) A is false, but R is true."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q50'),
  ('Accountancy', 'Cash Flow Statement', 'Cash Flow Statement', 'easy', 'The Net profit before Tax and extraordinary Items is:', '["₹1,10,000", "₹1,50,000", "₹90,000", "₹1,40,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q1'),
  ('Accountancy', 'Cash Flow Statement', 'Financial Management', 'easy', 'The Operating profit before working Capital changes is:', '["₹1,85,000", "₹1,90,000", "₹1,80,000", "₹1,75,000"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q2'),
  ('Accountancy', 'Cash Flow Statement', 'Cash flow statement', 'easy', 'The Cash Flow from Operating Activities is:', '["₹1,05,000", "₹1,45,000", "₹1,60,000", "₹1,15,000 =====PAGE 265===== Cash Flow Statement 261"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Accountancy · Ch:Cash Flow Statement · Q3'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Management is called a multi-dimensional concept because it includes:', '["Management of Work and People", "Management of People and Operations", "Management of Work, People, and Operations", "Management of Goals and Finance"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q1'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Which of the following designations is NOT associat- ed with Top Level Management?', '["Chief Operating Officer", "Vice President", "Production Manager", "Chairman"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q2'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Successful organisations do not achieve goals by chance but by following a deliberate process known as:', '["Planning", "Coordination", "Controlling", "Management"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q3'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Identify correct statements:', '["Management is a group activity", "Management is a one-time function", "Management requires coordination", "Management works towards goals (a) A, C, D (b) A, B, C (c) B, C, D (d) A and D"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q4'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Which statements reflect the significance of manage- ment?', '["Helps in achieving group goals", "Reduces competition", "Improves standard of living", "Ensures development of society (a) A, C, D (b) A and B (c) B and D (d) A only"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q5'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Which pair is correctly matched?', '["Effectiveness – Low cost", "Efficiency – Goal achievement", "Efficiency – Resource optimisation", "Effectiveness – Cost reduction"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q6'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', '“Management principles are not as rigid as principles of pure science.” Which characteristic of management as a science is highlighted here?', '["Systematized body of knowledge", "Universal validity", "Principles based on experimentation", "Management is an inexact science"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q7'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Identification of organizational objectives like ‘Sur - vival, Profit, and Growth’ falls under the category of:', '["Social Objectives", "Personal Objectives", "Organizational/Economic Objectives", "Legal Objectives"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q8'),
  ('Business Studies', 'Nature and Significance of Management', 'Marketing', 'hard', '‘Bright Vision Ltd.’ is a large organization manufac - turing high-end electronics. The company has sepa - rate departments for Production, Marketing, Finance, and Human Resources. Because the organization is very large, the employees of the Production depart - ment often do not know what the Sales department is promising to customers. This leads to a situation where sales are booked, but the product is not avail- able in stock. The CEO realizes that as the company expands, it becomes difficult to integrate the efforts of so many diverse individuals and departments. Identify the importance of coordination highlight- ed in the above case:', '["Specialization", "Growth in size", "Functional differentiation", "Management of Work"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q9'),
  ('Business Studies', 'Nature and Significance of Management', 'Planning', 'hard', 'Aman is responsible for the performance of the ‘North Zone’ of a multinational food chain. His daily tasks involve interpreting the broad goals set by the Board of Directors and ensuring that the Store Managers in his region have the necessary resources to execute these plans. He also acts as a link between the low - er-level supervisors and the CEO. Which level of management does Aman belong to?', '["Top level", "Middle level", "Supervisory level", "Operational Management"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q10'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'hard', 'In ‘Mega Architects,’ there are various experts like Civil Engineers, Interior Designers, and Landscape Architects. Each expert feels that they are the most qualified to make decisions regarding the project and often disregard the advice of others. This “ex - pert-clash” leads to delays in project completion. To PRACTICE CORNER ---PAGE 9--- 6 CUET UG Business Studies resolve this, the Project Manager must integrate the opinions and activities of these specialists to achieve the common goal. Identify the importance of coordination that is specifically needed here to handle ‘experts’:', '["Functional differentiation", "Growth in size", "Specialization", "All-pervasive nature 12 Kartik is a manager at a luxury hotel. He believes that while there are many books and theories on how to manage people, his success depends on how he per - sonally applies that knowledge to solve unique prob- lems every day. He uses his intuition and experience to handle difficult guests and motivate his staff in his own unique style. Which aspect of the ‘Nature of Management’ is Kartik demonstrating? (a) Management as a Science (b) Management as a Profession (c) Managem"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q11'),
  ('Business Studies', 'Nature and Significance of Management', 'Staffing', 'medium', 'Virat Kohli and Rohit Sharma both follow the same rulebook of cricket and have studied the same tech - niques of the game. However, their batting styles, shot selections, and ways of leading their teams are vastly different. Identify the feature of ‘Management as an Art’ highlighted here:', '["Based on practice and creativity", "Existence of theoretical knowledge", "Personalized application", "Universal validity"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q13'),
  ('Business Studies', 'Nature and Significance of Management', 'Planning', 'medium', '‘Global Connect Ltd.’ is a company that provides in - ternet services. To stay profitable, it regularly updates its technology and pricing plans based on the moves of its competitors and changes in government regu - lations. Which characteristic of management is being practiced?', '["Management is a goal-oriented process", "Management is a dynamic function", "Management is a continuous process", "Management is all-pervasive"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q14'),
  ('Business Studies', 'Nature and Significance of Management', 'Planning', 'medium', 'Kavita is a Branch Manager at a nationalized bank. She spends a significant portion of her day translating the broad strategies formulated by the Board of Directors into actionable plans for the tellers and clerks at her branch. Which level of management does Kavita be - long to?', '["Top Level", "Middle Level", "Operational Level", "First-line Level"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q15'),
  ('Business Studies', 'Nature and Significance of Management', 'Planning', 'medium', 'Once the plans are formulated, management must identify and group the various activities, assign duties to different departments, and establish reporting relationships to ensure a systematic flow of work. Identify the function:', '["Staffing", "Planning", "Organising", "Directing"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q16'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'At ‘Bloom Cosmetics,’ the HR manager is currently busy screening resumes and conducting interviews to fill three vacant positions in the Research and Development department. Which function of management is being performed?', '["Staffing", "Organising", "Planning", "Directing"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q17');
  INSERT INTO _ebook_q VALUES
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'hard', 'A company’s policy is to hire only MBA graduates from Tier-1 institutes for managerial positions. However, a highly experienced employee with no formal degree has been promoted to a Departmental Head role due to exceptional performance. In the context of “Man - agement as a Profession,” this scenario proves that:', '["Management is a full-fledged profession because the company prefers MBAs.", "Management lacks restricted entry because a degree is not a legal mandate for the role.", "Management is an Art because the employee uses creativity.", "Management is a Science as it uses a systematized body of knowledge."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q18'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Alpha Ltd.’ is facing a conflict where the Sales team wants to offer heavy discounts to meet targets, but the Finance team refuses because it reduces profit margins. This indicates that the “departmental bound- aries are becoming rigid.” Identify the aspect of coordination needed here:', '["Growth in Size", "Functional Differentiation", "Management as a Science", "Personal Objectives"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q19'),
  ('Business Studies', 'Nature and Significance of Management', 'Nature and Significance of Management', 'medium', 'Management is often described as a “Social Science.” Which of the following justifies this classification?', '["Its principles are as exact and static as the laws of Physics.", "It deals with human behavior, which is complex and unpredictable.", "It does not require any theoretical body of knowl- edge.", "It is purely based on the personal whims of the manager. ---PAGE 10--- Nature and Significance of Management 7"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Nature and Significance of Management · Q20'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Which technique of Scientific Management aims at eliminating unnecessary movements while perform- ing a particular task?', '["Time Study", "Motion Study", "Fatigue Study", "Method Study"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q1'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'The principle of ‘Esprit de Corps’ emphasizes:', '["Replacing ‘I’ with ‘We’", "Replacing ‘We’ with ‘I’", "Individual contribution over team goals", "Strict hierarchy"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q2'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', '“The intention of this principle is to produce more and better work for the same effort. It applies to all kinds of work, technical as well as managerial.” Identify the principle of Henri Fayol described here:', '["Discipline", "Authority and Responsibility", "Division of Work", "Remuneration of Employees"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q3'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Which technique of Scientific Management involves a ‘mental revolution’ to change the attitude of workers and management towards one another?', '["Functional Foremanship", "Harmony, Not Discord", "Standardization", "Cooperation, Not Individualism"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q4'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Fayol’s principle of ‘Equity’ emphasizes that there should be no discrimination on account of sex, reli - gion, language, caste, or belief. However, Equity does NOT mean:', '["Kindness in the behavior of managers", "Justice in the treatment of employees", "Equal salary for all employees regardless of their position or performance", "Maintaining a cordial relation between superior and subordinate"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q5'),
  ('Business Studies', 'Principles of Management', 'Planning', 'medium', 'The CEO of ‘ Aman Ltd.’ believes in encouraging his subordinates to come up with their own plans for cost reduction and rewards the best ideas. This fosters a sense of belonging among the workers. Which princi- ple is the CEO following?', '["Initiative", "Remuneration", "Equity", "Stability of Personnel"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q6'),
  ('Business Studies', 'Principles of Management', 'Planning', 'medium', 'A company manufactures multiple products: Electron- ics, Clothing, and Footwear. Each product line has its own independent department, its own resources, and its own head who plans specifically for that category. This ensures all efforts are integrated toward the department’s goal. Identify the principle:', '["Centralization", "Division of Work", "Unity of Direction", "Esprit de corps"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q7'),
  ('Business Studies', 'Principles of Management', 'Marketing', 'medium', 'At ‘Zenco Ltd.’ , the Marketing Manager gives instruc- tions to a salesperson to offer a 10% discount to a bulk buyer. At the same time, the Finance Manager tells the same salesperson not to offer more than a 5% dis - count. The salesperson is now confused. Which prin- ciple is violated?', '["Unity of Direction", "Unity of Command", "Division of Work", "Subordination of Individual Interest"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q8'),
  ('Business Studies', 'Principles of Management', 'Marketing', 'medium', 'In a manufacturing unit, the Production Manager noticed that workers were wasting time searching for tools. He decided to assign a fixed place for every tool and a fixed desk for every supervisor. This significant- ly improved efficiency. Identify the principle:', '["Equity", "Stability of Personnel", "Order", "Initiative"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q9'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Which principle of management promotes the idea that “loyalty and devotion” should be elicited from personnel by a combination of kindness and justice?', '["Discipline", "Esprit de Corps", "Equity", "Stability of Personnel"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q10'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Principles of management are NOT:', '["Universal in application.", "Formed by practice and experimentation.", "Flexible guidelines.", "Absolute rules like mathematical formulas."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q11'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'hard', '‘Safe-Drive Ltd.’ produces high-quality helmets. The CEO, Mr. Gupta, ensures that even the smallest task, such as the placement of safety stickers, is analyzed to find the most efficient method. He believes that the “hit-and-trial” method should be completely eliminat- ed to save time and resources. Identify the principle of Scientific Management being followed.', '["Harmony, Not Discord", "Science, Not Rule of Thumb", "Cooperation, Not Individualism", "Development of Each and Every Person PRACTICE CORNER ---PAGE 26--- Principles of Management 23"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q12'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'hard', 'At ‘Bright Future Academy’ , the Principal allows the administrative staff to communicate directly with him in case of a fire or medical emergency, bypassing the usual hierarchy of Coordinators and Vice-Principals. Which concept of the Scalar Chain is being applied here?', '["Functional Foremanship", "Unity of Command", "Gang Plank", "Discipline"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q13'),
  ('Business Studies', 'Principles of Management', 'Marketing', 'hard', 'The Production Manager of a toy factory realizes that many workers are getting tired quickly and their productivity drops significantly after 4 hours of con- tinuous work. He decides to conduct a study to deter- mine the frequency and duration of rest intervals required to regain their stamina. Identify the tech - nique of Scientific Management used.', '["Time Study", "Motion Study", "Method Study", "Fatigue Study"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q14'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'The principle of ‘Initiative’ is violated when a manag- er __________.', '["Encourages suggestions from workers", "Rewards cost-reduction ideas", "Adopts a rigid “my way or the highway” approach", "Delegates authority to subordinates"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q15'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Which technique of Scientific Management is an ex - tension of the principle of ‘Division of Work’?', '["Differential Piece Wage System", "Fatigue Study", "Functional Foremanship", "Standardization"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q16'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Taylor’s ‘Simplification of Work’ aims at eliminating __________ of products.', '["Essential features", "Unnecessary diversity and sizes", "Quality standards", "Profit margins"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q17'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'hard', '“In ‘Ziva Ltd.’ , the CEO believes that all instructions should flow through a clear, formal chain of command from top to bottom. However, in case of an emergency, he allows two employees at the same level to commu- nicate directly with each other to avoid delays.” The concept highlighted here to avoid delays is:', '["Scalar Chain", "Gang Plank", "Unity of Command", "Order Comprehension Read the following text and answer the questions that follow: Aryan and Meera are entrepreneurs who started ‘Green- Tech Solutions,’ a company manufacturing eco-friendly packaging. Aryan handles the factory operations, while Meera manages sales and finance. In the factory, Aryan has ensured that each worker receives orders from only one supervisor to avoid confusion and conflicting instructions. However, he noticed that the pro- duction line was slow because every small decis"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q18'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', '“Each worker receives orders from only one supervi- sor.” Identify the Principle of Management highlighted here.', '["Unity of Direction", "Division of Work", "Unity of Command", "Discipline"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q1'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Aryan decided to share decision-making power with supervisors while keeping key powers to himself. Which concept is being applied?', '["Centralisation and Decentralisation", "Scalar Chain", "Remuneration of Employees", "Order"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q2'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'Meera implemented a policy to ensure employees are kept for at least two years. Which principle is she following?', '["Equity", "Stability of Personnel", "Initiative", "Esprit de Corps"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q3'),
  ('Business Studies', 'Principles of Management', 'Planning', 'medium', 'Meera encouraged the marketing team to “come up with their own plans and execute them.” Identify the principle.', '["Authority and Responsibility", "Discipline", "Initiative", "Scalar Chain"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q4'),
  ('Business Studies', 'Principles of Management', 'Principles of Management', 'medium', 'If Green-Tech Solutions decides to create a formal line of authority from highest to lowest ranks for commu- nication, it would be following the principle of:', '["Unity of Command", "Scalar Chain", "Order", "Equity ---PAGE 27--- 24 CUET UG Business Studies"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Principles of Management · Q5'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'The government of a country decides to cap the pric- es of essential medicines to ensure affordability. This move primarily reflects the impact of which two di - mensions of the business environment?', '["Economic and Social", "Legal and Political", "Political and Economic", "Technological and Social"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q1'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'A major automobile company shifts its focus from diesel engines to electric vehicles (EVs) after the Na- tional Green Tribunal (NGT) imposed a ban on 10-year-old diesel vehicles in the capital. This scenar- io illustrates which characteristic of the business environment?', '["Relativity", "Inter-relatedness", "Uncertainty", "Totality of external forces"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q2'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'Analyzing the business environment helps a manager to get information about a new competitor entering the market. This helps the firm to prepare itself for the challenge. This represents:', '["Assisting in planning and policy formulation", "Identification of threats and early warning signals", "Improving performance", "Tapping useful resources"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q3'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'Which of the following is NOT a characteristic of Lib- eralization?', '["Abolishing licensing requirements in most indus- tries", "Freedom in fixing prices of goods and services", "Integration of the national economy with the world economy", "Reduction in tax rates and lifting of unnecessary controls"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q4');
  INSERT INTO _ebook_q VALUES
  ('Business Studies', 'Business Environment', 'Business Environment', 'easy', 'Which of the following is considered a ‘General Force’ of the business environment?', '["Investors", "Customers", "Competitors", "Social Conditions"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q5'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', '“ An increase in the interest rates on loans by the Re- serve Bank of India makes it expensive for a construc- tion company to borrow money.” This is part of the:', '["Legal Environment", "Economic Environment", "Political Environment", "Social Environment"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q6'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', '“The court passed an order to ban the use of plastic bags in the city, and the administrative authorities were directed to penalize violators.” Which dimension is this?', '["Political Environment", "Economic Environment", "Legal Environment", "Social Environment"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q7'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'The Indian Government’s “Digital India” initiative has encouraged many small businesses to adopt online payment methods. This is an example of the impact of which two dimensions?', '["Political and Technological", "Social and Legal", "Economic and Social", "Legal and Technological"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q8'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'Which dimension of the business environment in - cludes factors like life expectancy, literacy rates, and shifts in consumer preferences?', '["Economic Environment", "Social Environment", "Political Environment", "Legal Environment"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q9'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', '“The shift from using landline phones to smartphones destroyed the business of many traditional telecom equipment manufacturers.” This is an example of which feature of the business environment?', '["Uncertainty", "Dynamic Nature", "Relativity", "Complexity"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q10'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'Selling equity of public sector enterprises to the pri- vate sector is known as:', '["Liberalization", "Globalization", "Disinvestment (Privatization)", "Demonetization PRACTICE CORNER ---PAGE 45--- 42 CUET UG Business Studies"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q11'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'The business environment is said to be ___________ because it is difficult to predict future happenings, especially in high-tech industries.', '["Stable", "Reciprocal", "Uncertain", "Simple"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q12'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'A soft drink company finds it difficult to understand the exact impact of social, economic, and political changes on its demand simultaneously. This highlights which characteristic?', '["Totality of external forces", "Complexity", "Inter-relatedness", "Relativity"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q13'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'Which of the following is an example of “Inter-relat - edness” in the business environment?', '["Increased life expectancy leading to higher de - mand for health products.", "A change in the government leading to a change in the stock market.", "High competition leading to lower prices.", "Different impacts of GST on different industries."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q14'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'Which of the following is an example of the ‘Relativi- ty’ feature of the business environment?', '["It consists of many interrelated parts.", "It differs from country to country and region to region.", "It is constantly changing.", "It is easier to understand in parts but difficult to understand in totality. Case Based Questions"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q15'),
  ('Business Studies', 'Business Environment', 'Marketing', 'hard', 'Following the 1991 reforms, ‘Global-Tech Inc.’ entered the Indian market without needing a prior govern - ment license to expand its production capacity. This allowed the company to respond quickly to market demand and lowered the barriers to entry for their international competitors. Identify the concepts of New Economic Policy (1991) highlighted above:', '["Globalization and Privatization", "Liberalization and Globalization", "Privatization and Liberalization", "Demonetization and Globalization"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q1'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'hard', 'A sudden hike in the Repo Rate by the Reserve Bank of India has made home loans expensive. While this has caused a slump in the sales of ‘Dream-Abode De- velopers,’ it hasn’t significantly affected the operations of ‘Quick-Fix Software Services.’ Which feature of the business environment is being illustrated here?', '["Uncertainty", "Dynamic Nature", "Relativity", "Specific and General Forces"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q2'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'hard', 'Z-Fashion’ was the first brand to identify a shift in consumer preference toward “Sustainable and Ethi - cally Sourced” clothing. By launching an organic cotton line six months before its competitors, it captured 40% of the niche market. Which point of “Importance of Business Environment” is highlighted here?', '["It helps in tapping useful resources.", "It helps in coping with rapid changes.", "It enables the firm to identify opportunities and get the first-mover advantage.", "It helps in improving performance. “With the rise of the ‘Digital India’ mission, there has been a massive surge in UPI transactions. This led to a decline in the demand for physical wallets and leather accessories. ‘Hide & Sleek,’ a luxury leather brand, noticed this trend early and pivoted to manufacturing ‘RFID-blocking’ smart cardholders and laptop sleeves. This move helped them maintain their profit margins despite the shrinking tradi - tional wallet market.”"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q3'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', 'The “Digital India” mission is primarily an example of which environment?', '["Technological Environment", "Political Environment", "Economic Environment", "Legal Environment"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q4'),
  ('Business Studies', 'Business Environment', 'Business Environment', 'medium', '‘Hide & Sleek’ identifying the trend early to maintain profit margins illustrates which importance of study- ing the business environment.?', '["It helps in tapping useful resources.", "It helps in coping with rapid changes.", "It helps in improving performance.", "It helps in policy formulation."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Business Environment · Q5'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'The Board of Directors of “TechVibe Ltd.” has set a target to increase profits by 15%. The Planning De - partment has started making assumptions about fu - ture inflation rates, government tax policies, and consumer behavior for the coming year. Which step of the planning process are they current- ly at?', '["Setting Objectives", "Developing Premises", "Evaluating alternative courses", "Implementation of the plan"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q1'),
  ('Business Studies', 'Planning', 'Planning', 'hard', 'A software company has a strict internal guideline that says, “No employee is allowed to use personal USB drives on office computers to prevent data theft.” Violation of this leads to a fine of ₹1,000. Identify the type of plan mentioned above:', '["Policy", "Procedure", "Rule", "Method"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q2'),
  ('Business Studies', 'Planning', 'Planning', 'hard', '“Quick-Serve,” a food delivery startup, followed its 2-year expansion plan strictly. Suddenly, a new com- petitor entered the market offering 10-minute deliv- ery. “Quick-Serve” managers couldn’t react because they were told to stick to the pre-decided budget and path. Which limitation of planning is highlighted here?', '["Planning involves huge costs", "Planning reduces creativity", "Planning leads to rigidity", "Planning does not guarantee success"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q3'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'While making the annual plan for a garment factory, the manager realizes that the planning for ‘Production’ depends on the ‘Sales’ forecast, and the ‘Finance’ plan depends on the ‘Production’ plan. All departments must plan simultaneously. Which feature of planning is being discussed?', '["Planning is a mental exercise", "Planning is pervasive", "Planning is continuous", "Planning is futuristic"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q4'),
  ('Business Studies', 'Planning', 'Planning', 'hard', 'In an organization where no plans are made, the Mar- keting department is promoting a product that the Production department has already stopped manu - facturing. This has led to a total waste of resources and confusion among customers. Which point of ‘Importance of Planning’ is missing in this company?', '["Planning provides directions", "Planning reduces the risks of uncertainty", "Planning promotes innovative ideas", "Planning establishes standards for controlling"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q5'),
  ('Business Studies', 'Planning', 'Planning', 'hard', 'At “Everest Textiles,” the production manager sets a target to produce 10,000 units, but the sales manager is only planning to sell 5,000 units. Because there was no initial coordination or shared plan, the company ended up with massive unsold inventory and wasted labor costs. Which importance of planning was ignored here?', '["Planning reduces the risks of uncertainty.", "Planning provides direction.", "Planning promotes innovative ideas.", "Planning reduces overlapping and wasteful activ- ities."]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q6'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'Mr. Aryan, the CEO of a tech firm, spends hours ana - lyzing market trends, consumer behavior, and com - petitor moves before finalizing the year’s roadmap. He relies on data and logical reasoning rather than “gut feeling” or “luck.” Identify the feature of planning highlighted:', '["Planning is a continuous process.", "Planning is a mental exercise.", "Planning is futuristic.", "Planning involves decision-making."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q7'),
  ('Business Studies', 'Planning', 'Planning', 'medium', '“Z-Plus Security” implemented a new plan to use AI-integrated cameras for surveillance. After three months, the manager checked the performance re - ports to see if the cameras actually reduced theft as predicted. He found the results were positive. Which step of the planning process is the manager performing now?', '["Selecting an alternative.", "Implementation of the plan.", "Follow-up action.", "Evaluating alternative courses."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q8'),
  ('Business Studies', 'Planning', 'Planning', 'hard', 'A school’s management states: “We have a strict pol- icy of promoting internal staff to senior positions whenever a vacancy arises.” To apply for such a pro- motion, an employee must first fill out Form A, get it signed by the HOD, and then appear for an interview. PRACTICE CORNER ---PAGE 60--- Planning 57 Identify the two types of plans mentioned:', '["Strategy and Rule", "Policy and Procedure", "Objective and Method", "Rule and Method"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q9'),
  ('Business Studies', 'Planning', 'Planning', 'hard', 'A tourism company planned a grand international summer tour package in January 2024. However, in April, a sudden geopolitical conflict led to the closure of airspace in that region, making the entire plan useless despite the heavy costs already spent on ad - vertising. Which limitation of planning does this scenario illus- trate?', '["Planning is a time-consuming process.", "Planning does not guarantee success.", "Planning may not work in a dynamic environment.", "Planning reduces creativity."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q10'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'In the planning process, “Evaluation of Alternatives” is specifically based on which two main criteria?', '["Feasibility and Profitability", "Risk and Opportunity", "Innovation and Cost", "Duration and Complexity"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q11'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'If a manager is forced to ignore a more profitable path because it contradicts the pre-set assumptions of the company, which limitation is highlighted?', '["Planning is time-consuming", "Planning reduces creativity", "Planning leads to rigidity", "Planning involves huge costs"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q12'),
  ('Business Studies', 'Planning', 'Planning', 'easy', 'A statement of “Expected Results” expressed in nu - merical terms is known as:', '["Objective", "Budget", "Program", "Strategy"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q13'),
  ('Business Studies', 'Planning', 'Planning', 'medium', '“Planning is a mental exercise” because it replaces _______ with _______.', '["Facts with Guesswork", "Guesswork with Logical Thinking", "Objectives with Methods", "Analysis with Intuition"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q14');
  INSERT INTO _ebook_q VALUES
  ('Business Studies', 'Planning', 'Planning', 'medium', '“Planning is essentially blind without controlling, and controlling is meaningless without planning.” Which importance of planning does this statement support?', '["Planning provides direction.", "Planning reduces the risks of uncertainty.", "Planning establishes standards for controlling.", "Planning promotes innovative ideas."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q15'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'In the planning process, if the “best” alternative cannot be mathematically determined, what does a manager primarily rely on during the ‘Selection’ step?', '["Developing more premises.", "Experience, judgment, and intuition.", "Increasing the budget.", "Repeating the evaluation step."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q16'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'A “Program” is a complex mixture of which of the following?', '["Objectives, policies, procedures, and rules.", "Budgets and methods only.", "Strategies and premises only.", "Standing plans and objectives only."]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q17'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'Which of the following is a “Controllable Premise” for a business?', '["Change in government policy.", "Entry of a new competitor.", "Expansion of the company’s own production capacity.", "Fluctuations in the stock market."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q18'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'If a sales manager calculates the exact “cost per unit” of a marketing campaign, they are most likely prepar- ing which type of plan?', '["Policy", "Procedure", "Budget", "Method"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q19'),
  ('Business Studies', 'Planning', 'Planning', 'medium', 'Why is planning described as “Pervasive” rather than “Top-level exclusive”?', '["Because it is done by the CEO.", "Because the scope of planning differs across dif- ferent levels of management.", "Because it is a continuous process.", "Because it involves huge costs."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Planning · Q20'),
  ('Business Studies', 'Organising', 'Organising', 'medium', '“ At ‘Glow Cosmetics’ , the duties of every employee are clearly defined, and they know exactly who they have to report to. This has resulted in no overlapping of work and a smooth flow of communication.” Which point of importance of organising is highlighted here?', '["Adaptation to change", "Clarity in working relationships", "Development of personnel", "Expansion and growth"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Organising · Q1'),
  ('Business Studies', 'Organising', 'Organising', 'medium', '“By dividing the work into manageable activities and assigning them to people based on their skills, ‘ Auto- Parts Ltd.’ has ensured that employees become experts in their specific tasks over time.” Identify the impor- tance highlighted.', '["Benefits of specialisation", "Effective administration", "Optimum utilization of resources", "Development of personnel"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Organising · Q2'),
  ('Business Studies', 'Organising', 'Marketing', 'hard', 'Auto-Parts Ltd.’ is divided into departments like Pro- duction, Finance, and Sales. Recently, the Sales depart- ment promised a large order to a client with a very short deadline without consulting the Production department. The Production Manager now claims it’s impossible to manufacture the goods in time. Which specific disadvantage of the Functional Structure is highlighted here?', '["It leads to occupational specialisation.", "It makes training of employees easier.", "Conflict of interest between departments.", "Difficulty in multi-product diversification."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Organising · Q3'),
  ('Business Studies', 'Organising', 'Organising', 'hard', 'Multi-Tech Corp’ has three divisions: Mobile Phones, Laptops, and Home Appliances. The company’s annu- al report shows that while Mobiles and Laptops are highly profitable, the Home Appliances division has been losing money for three consecutive years. The Board decides to shut down only the Home Applianc- es division without affecting the other two. Which merit of the Divisional Structure allowed the company to identify and take action on the losing division so easily?', '["Product Specialisation", "Flexibility and Fast Decision Making", "Accountability and easy fixation of responsibility", "Economical as it avoids duplication of resources"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Organising · Q4'),
  ('Business Studies', 'Staffing', 'Planning', 'hard', 'The Production Manager of ‘Vidhata Ltd.’ realizes that the current assembly line is moving slowly. Upon in- vestigation, he finds that while they have 50 workers (as planned), 10 of them are specialized in “quality control” and are not trained for “assembly,” leading to a bottleneck in actual production. He reports that while the quantity of staff is correct, the type is mis - matched. Which aspect of the staffing process did the manager primarily highlight through this observation?', '["Workload Analysis", "Workforce Analysis", "Comparison of Workload and Workforce", "Job Description"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q1'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', 'After clear rounds of interviews and tests, Sunidhi was called by “Tech-Innovate” to verify her previous em- ployment records and check her character through the references she provided in her application. Iden- tify the step of the selection process.', '["Selection Decision", "Medical Examination", "Reference and Background Checks", "Employment Interview"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q2'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', 'A large multinational bank wants to hire “fresh blood” for its new digital banking wing. They decide to visit top-tier management institutes to recruit graduating students directly. Identify the source of recruitment.', '["Recommendation of employees", "Campus Recruitment", "Placement Agencies", "Casual Callers"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q3'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', 'Due to a vacancy in the branch at Mumbai, Mr. Sharma, who was working at the Delhi branch, was shifted to Mumbai in the same capacity and rank. This is an example of:', '["Promotion", "Transfer", "Direct Recruitment", "Selection"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q4'),
  ('Business Studies', 'Staffing', 'Planning', 'medium', 'Newly appointed pilots at “Sky-High Airways” are required to practice in a sophisticated cabin that rep- licates the actual cockpit of a plane. This allows them to learn without risking expensive equipment or lives. Identify the method of training.', '["Apprenticeship Training", "Internship Training", "Vestibule Training", "Coaching"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q5'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', 'A plumber trainee is asked to work under a master craftsman for two years to learn the intricacies of the trade before he is allowed to work independently. Which training method is being used?', '["Induction Training", "Apprenticeship Program", "Job Rotation", "Vestibule Training"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q6'),
  ('Business Studies', 'Staffing', 'Staffing', 'hard', 'Ridhima received a document from ‘Global Banks’ stating she had been selected for the post of ‘ Analyst’ and asking her to report for duty on the 1st of next month. However, the document did not specify her leaves, grievance redressal procedure, or termination clauses. These details were provided to her in a sep- arate, detailed legal document she had to sign on her first day. Identify the two steps of the selection process men - tioned here.', '["Selection Decision and Job Offer", "Job Offer and Contract of Employment", "Reference Check and Selection Decision", "Employment Interview and Job Offer"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q7'),
  ('Business Studies', 'Staffing', 'Staffing', 'hard', 'A reputed hospital in Mumbai has a policy of filling all senior surgeon positions only through promotions from within. Over five years, the Hospital Board no - tices that the surgical techniques being used are be - coming outdated, and the senior staff is resistant to adopting new robotic surgery methods used globally. Which specific limitation of internal recruitment is being highlighted here?', '["It is a time-consuming process.", "It reduces the morale of existing employees.", "It leads to ‘Inbreeding’ and stops the infusion of fresh talent.", "It is an expensive source of recruitment."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q8'),
  ('Business Studies', 'Staffing', 'Staffing', 'hard', 'During the selection process for a Creative Director at an Ad Agency, the candidate was asked to react to a hypothetical situation where a major client rejects a campaign at the last minute. The observers were carefully noting the candidate’s facial expressions, level of calmness, and how he handled the stress of the “client’s” simulated anger. Identify the two selection tests being merged in this practical round.', '["Intelligence test and Trade test", "Personality test and Aptitude test PRACTICE CORNER ---PAGE 97--- 94 CUET UG Business Studies", "Interest test and Intelligence test", "Trade test and Interest test"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q9'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', '“Due to a sudden rush of orders, ‘Gourmet Foods’ needs 20 additional delivery boys for just two weeks. They placed a notice on the factory gate to hire casu- al workers on a daily wage basis.” Identify the source of recruitment.', '["Casual Callers", "Direct Recruitment", "Labor Contractors", "Advertising"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q10'),
  ('Business Studies', 'Staffing', 'Directing', 'hard', '‘ Apex Softwares’ sends its top-performing Senior Engineers to a weekend retreat titled “Leadership and Emotional Intelligence in the AI Era.” The goal is not to teach them new coding languages, but to prepare them for future roles as Department Heads where they will manage diverse teams. Identify the concept and the correct reason behind it.', '["Training; because it is increasing their technical efficiency.", "Development; because it is a career-oriented process focusing on future growth.", "Orientation; because they are being introduced to new leadership roles.", "Education; because it is providing them with theoretical knowledge of AI."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q11'),
  ('Business Studies', 'Staffing', 'Staffing', 'hard', '‘Tech-Giant Corp’ wants to hire a new CEO. Instead of giving an open advertisement in the newspaper, which might attract thousands of unqualified resumes, they hire a private firm that maintains a secret database of high-level executives currently working in other com- panies. Identify the source of recruitment and its primary benefit.', '["Employment Exchange; because it is run by the government.", "Placement Agencies; because they provide un - skilled labor.", "Management Consultants; because they help in recruiting top-level executives and maintain high secrecy.", "Web Publishing; because it uses a database."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q12'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', '“Maintaining a data bank of candidates who had ap - plied for jobs in the past but were not selected” refers to which source of recruitment?', '["Labor Contractors", "Casual Callers", "Advertising", "Recommendations"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Staffing · Q13'),
  ('Business Studies', 'Directing', 'Directing', 'hard', 'At ‘Z-Tech Ltd.’ , there is a strict policy that all information must flow through the official chain of command. However, during lunch breaks, employees from different departments meet in the cafeteria to discuss potential changes in company policy and vent their frustrations about the new work hours. Which type of communication network is being formed in the cafeteria?', '["Vertical communication", "Grapevine", "Scalar chain", "Wheel network"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q1'),
  ('Business Studies', 'Directing', 'Directing', 'hard', 'Kartik is a brilliant software engineer. He earns a high salary and has a permanent job. Recently, he has been feeling demoted because he feels his work is not being recognized by his peers and he isn’t given any significant titles or responsibilities that reflect his seniority. Which level of Maslow’s hierarchy is currently unfulfilled for Kartik?', '["Basic Physiological Needs", "Safety/Security Needs", "Esteem Needs", "Self-actualization Needs"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q2'),
  ('Business Studies', 'Directing', 'Directing', 'hard', 'Sameer, a production manager, was in a hurry to reach a meeting. While passing by the assembly line, he told a worker, “Make sure the output is fine.” The worker thought Sameer meant the quality should be high, so he slowed down the machine. Sameer actually meant the quantity (volume) should be high. Identify the communication barrier highlighted here.', '["Premature evaluation", "Lack of attention", "Faulty translations", "Poor retention"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q3'),
  ('Business Studies', 'Directing', 'Directing', 'hard', 'Ms. Nalini, the CEO of an advertising agency, believes that her creative team is highly skilled and self- motivated. She provides them with the goals and resources they need and then steps back, allowing them to make their own decisions and solve their own problems without her interference. Identify the leadership style practiced by Ms. Nalini.', '["Autocratic Leadership", "Democratic Leadership", "Free-rein (Laissez-faire) Leadership", "Paternalistic Leadership"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q4'),
  ('Business Studies', 'Directing', 'Marketing', 'medium', 'To improve productivity during the festive season, ‘Vision Electronics’ announced that any salesperson who exceeds their target by 20% will be given a 5% share in the extra profits generated by those additional sales. Identify the financial incentive offered by the company.', '["Perquisites", "Co-partnership", "Profit Sharing", "Bonus"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q5'),
  ('Business Studies', 'Directing', 'Directing', 'medium', 'A manager sent a technical manual written in high- level jargon to a group of new interns who had no prior engineering background. The interns were unable to understand the instructions. This is an example of which type of Semantic Barrier?', '["Symbols with different meanings", "Technical Jargon", "Unclarified assumptions", "Body language and gesture decoding"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q6'),
  ('Business Studies', 'Directing', 'Directing', 'medium', 'Rohan works as a first-line manager in a chocolate factory. He acts as a “linking pin” between the workers and the middle management. He ensures that the workers’ grievances are heard by the higher-ups and that the production targets set by the department head are clearly explained to the workers. Which aspect of the Directing function is Rohan primarily performing?', '["Motivation", "Leadership", "Supervision", "Communication"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q7');
  INSERT INTO _ebook_q VALUES
  ('Business Studies', 'Directing', 'Directing', 'medium', 'Kavita, a senior manager, does not have confidence in the competency of her subordinates. As a result, she rarely seeks their advice or involves them in any meaningful conversation, fearing they might give wrong suggestions or challenge her authority. Identify the type of barrier to communication described above.', '["Organizational Barrier", "Personal Barrier", "Semantic Barrier", "Psychological Barrier"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q8'),
  ('Business Studies', 'Directing', 'Directing', 'hard', 'The IT department at ‘Innovate Ltd.’ has decided to give its software developers more autonomy and powers to decide their own work schedules and choose the programming languages for their projects without seeking constant approval from the Project Lead. PRACTICE CORNER ---PAGE 120--- Directing 117 Which non-financial incentive is being highlighted here?', '["Job Enrichment", "Organizational Climate", "Employee Empowerment", "Career Advancement"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q9'),
  ('Business Studies', 'Directing', 'Directing', 'medium', 'During a performance appraisal meeting, a manager was praising an employee’s hard work, but he was constantly looking at his watch and tapping his pen impatiently. The employee felt that the manager wasn’t actually happy with his performance. Identify the communication barrier in this scenario.', '["Symbols with different meanings", "Faulty translations", "Body language and gesture decoding", "Unclarified assumptions"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q10'),
  ('Business Studies', 'Directing', 'Directing', 'medium', 'Under a new scheme, ‘Tech-Giant Corp’ offered its employees the right to purchase company shares at a price lower than the current market price as a reward for their loyalty and performance. Which financial incentive is the company using?', '["Bonus", "Profit Sharing", "Co-partnership/Stock Option", "Retirement Benefits"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q11'),
  ('Business Studies', 'Directing', 'Directing', 'easy', 'Supervising the work in progress Options:', '["2, 5, 4, 1, 3", "2, 4, 1, 5, 3", "1, 2, 4, 5, 3", "4, 1, 2, 5, 3"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q5'),
  ('Business Studies', 'Directing', 'Directing', 'easy', 'Communication of the scheme to staff Options:', '["4, 2, 1, 3", "2, 4, 1, 3", "2, 1, 4, 3", "4, 1, 2, 3"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q4'),
  ('Business Studies', 'Directing', 'Directing', 'easy', 'Selecting the appropriate leadership style Options:', '["1, 3, 5, 2, 4", "3, 1, 5, 2, 4", "1, 5, 3, 2, 4", "3, 5, 1, 2, 4"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Directing · Q5'),
  ('Business Studies', 'Financial Management', 'Share capital', 'hard', '‘Zenith Ltd.’ is a large-scale manufacturing company. It needs ₹50 crores for modernization. The manage - ment is debating whether to raise this money by issu- ing Equity Shares or by taking a long-term loan from a bank. They finally decide on the loan because the current stock market is bearish and they want to take advantage of the tax-deductibility of interest. Which financial decision is being highlighted here?', '["Investment decision", "Financing decision", "Dividend decision", "Working capital decision"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Management · Q1'),
  ('Business Studies', 'Financial Management', 'Financial Management', 'hard', '‘HealthKart’ has earned a significant profit this year. However, the board of directors noticed that there are several high-growth investment opportunities available in the market for next year. To fund these projects internally, the board decided to distribute only a small fraction of the profits to shareholders and keep the rest as retained earnings. Which financial decision does this scenario represent?', '["Capital Budgeting decision", "Financing decision", "Dividend decision", "Short-term investment decision"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Management · Q2'),
  ('Business Studies', 'Financial Management', 'Financial Management', 'hard', '‘FreshBites’ is a seasonal business that sells mango- based desserts. During the summer months, the company needs more cash to purchase raw materials and pay for higher electricity bills, whereas, in the winter, their cash requirement drops significantly. Which type of financial requirement is being discussed in this case?', '["Fixed Capital requirement", "Long-term investment decision", "Working Capital requirement", "Capital Structure decision"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Management · Q3'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'medium', '“Zodiac Events Ltd.” needs to pay its staff salaries and immediate electricity bills, but its cash is tied up in long-term projects. To meet these immediate requirements, the company issues a short-term, unsecured negotiable instrument with a maturity period of 3 months to another corporate house. Which money market instrument is being used here?', '["Treasury Bill", "Commercial Paper", "Call Money", "Certificate of Deposit"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q1'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'medium', '“Tech-Nova Ltd.” is a highly successful software company. It wants to raise capital for a new AI project. Instead of inviting the general public, it decides to issue shares to its existing shareholders in proportion to their current holding at a price lower than the market price. Identify the method of floatation used.', '["Offer for Sale", "Private Placement", "Rights Issue", "e-IPO"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q2'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'medium', 'Ms. Sneha wants to invest in the stock market for the first time. She opens an account where her shares will be held in electronic form to avoid the risk of theft or forgery associated with physical share certificates. What is the name of the account Ms. Sneha opened?', '["Savings Account", "Demat Account", "Current Account", "Fixed Deposit Account"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q3'),
  ('Business Studies', 'Financial Markets', 'Staffing', 'medium', 'To improve the transparency of the Indian stock market, SEBI has recently started conducting online training programs for investors and has published a “Code of Conduct” for intermediaries like brokers to follow. Which two functions of SEBI are highlighted in the scenario above?', '["Protective and Regulatory", "Development and Regulatory", "Protective and Development", "Regulatory and Executive"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q4'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'hard', 'During a volatile week in the market, the price of “BlueChip Ltd.” shares increased by 20% in just two hours. The Stock Exchange provided a continuous platform where buyers and sellers could trade these shares instantly, ensuring that the asset remained liquid for investors who wanted to exit. Which function of the Stock Exchange is highlighted here?', '["Safety of transactions", "Providing liquidity and marketability to existing securities", "Pricing of securities", "Spreading of equity cult"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q5'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'hard', 'In the modern era, the physical “trading floor” where brokers shouted prices has been replaced by a fully automated computer network. This allows an investor to sit in their office and buy shares in a company located thousands of miles away instantly. This system ensures that all participants see the same price at the same time, promoting transparency. Identify the system discussed above:', '["Dematerialisation", "Screen-based Trading", "Rematerialisation", "National Stock Exchange"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q6'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'medium', '“Wealth Builders Ltd.” is a startup looking to expand its manufacturing unit. To raise the necessary capital, the company decides to issue new shares to the general public for the very first time. This process allows the company to convert savings into long-term investments directly from the public. Identify the market being described:', '["Secondary Market", "Money Market", "Primary Market", "Commercial Paper Market"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q7'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'hard', 'To protect the interests of investors, a regulatory body has prohibited “Insider Trading” and has clamped down on “Price Rigging” where certain parties artifi- cially inflate share prices to dupe innocent buyers. These steps are taken to ensure a fair and transparent environment in the securities market. Identify the function being performed by SEBI:', '["Development function", "Protective function", "Regulatory function", "Executive function"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q8'),
  ('Business Studies', 'Financial Markets', 'Financial Markets', 'medium', 'To trade in the modern electronic system, an investor must open an account with an intermediary like a bank or a brokerage firm. These intermediaries act as agents for the Depository (like NSDL or CDSL) and maintain the investor’s electronic holdings. PRACTICE CORNER ---PAGE 184--- Financial Markets 183 Identify the intermediary discussed above:', '["Stock Exchange", "Depository Participant (DP)", "Clearing House", "Registrar"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Financial Markets · Q9'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', '‘Pure Water Ltd.’ is a company manufacturing water purifiers. While designing their latest model, they focused on making the product highly efficient and durable. However, they ignored whether the average consumer could afford it or if it was easily available in rural markets. They believe that if the quality is superior, customers will automatically buy it. Identify the marketing management philosophy followed by the company:', '["Production Concept", "Product Concept", "Marketing Concept", "Selling Concept"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q1'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', '‘Glow & Lovely’ is a skincare brand. On their new face cream tube, they have provided a detailed ‘List of Ingredients’ , ‘Directions for Use’ , and ‘Manufacturing Date’ . Additionally, they have highlighted that the product is “Paraben Free” to attract health-conscious users. Which function of Labelling is highlighted by the phrase “Paraben Free”?', '["Identification of the product or brand", "Grading of the product", "Promotion of the product", "Providing information required by law"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q2'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', '‘ Auto-Gear’ , a manufacturer of luxury electric bikes, has decided to sell its products only through a few selected authorized showrooms in major metro cities. They want to ensure that the staff can provide high- end technical demonstrations and maintain the brand’s premium exclusivity. Identify the type of distribution channel/strategy being used:', '["Intensive Distribution", "Selective Distribution", "Direct Channel (Zero Level)", "Indirect Channel (Two Level)"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q3'),
  ('Business Studies', 'Marketing Management', 'Planning', 'medium', 'To counter negative news regarding the sugar content in its beverages, ‘Fruit-Z’ organized a massive tree- plantation drive across 50 cities. They invited local NGOs and media houses to cover the event, aiming to improve the company’s standing in the eyes of the general public and government bodies. Identify the tool of promotion used by ‘Fruit-Z’:', '["Advertising", "Sales Promotion", "Personal Selling", "Public Relations"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q4'),
  ('Business Studies', 'Marketing Management', 'Marketing Management', 'hard', '‘Quick-Fix’ is a new entrant in the instant adhesive market. Since the market is already dominated by established players like ‘Fevikwik’ , ‘Quick-Fix’ decided to set their price 20% lower than the competitors to penetrate the market and build a large customer base quickly. Which factor affecting price determination is highlighted in the above case?', '["Product Cost", "The Utility and Demand", "Extent of Competition in the Market", "Government and Legal Regulations"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q5'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', 'Eco-Breathe Ltd. is a company manufacturing air purifiers. Recently, the company noticed a dip in sales. Upon investigation, they found that while their prod- uct was technically superior, customers found the price too high compared to competitors. The Market- ing Manager decided to introduce a new “Base Model” with fewer features at a significantly lower price to capture the middle-class segment. Simultaneously, they launched an exchange offer where old purifiers could be traded in for a discount on the new model. Which dimension of the Marketing Mix is being primarily addressed by the company’s decision to launch the “Base Model” and provide an “Exchange Offer”?', '["Product", "Price", "Promotion", "Place"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q6'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', 'Pure Drop Water is a premium bottled water brand. To ensure that their product stands out on a crowded retail shelf, they designed a unique hexagonal bottle that is easy to grip. They also ensured that the bottle is made of 100% biodegradable plastic. The label on the bottle contains a QR code that, when scanned, shows the exact Himalayan spring from which that specific bottle was sourced. The decision to use a “unique hexagonal bottle” and “100% biodegradable plastic” relates to which function of marketing?', '["Branding", "Grading", "Product Designing and Development", "Standardisation PRACTICE CORNER ---PAGE 205--- 204 CUET UG Business Studies"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q7'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', 'Zenith Electronics sells high-end home theatre systems. Since these systems are complex to install and expensive, the company does not sell them through general electronic stores. Instead, they have opened exclusive “Experience Centers” in major cities where customers can test the sound quality before buying. They also provide free installation and a two- year home-maintenance contract. Which element of the “Promotion Mix” is NOT being discussed in the scenario above?', '["Personal Selling", "Sales Promotion", "Public Relations", "Direct Marketing"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q8'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'medium', '‘Vayu’ is a startup that manufactures premium electric bicycles. To ensure that its products reach the right customers, it sells only through its own website and a limited number of Exclusive Brand Outlets (EBOs) in metro cities, without involving wholesalers or retailers. Which type of distribution channel is being used by ‘Vayu’?', '["Three-level Channel", "Two-level Channel", "One-level Channel", "Zero-level Channel"]'::jsonb, 3, 'Answer (d) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q9'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'medium', 'The marketing manager of ‘Fresh-Bites’ , a fruit juice company, believes that instead of simply selling what the company produces, it should first understand customer needs and then develop products accord - ingly. Which marketing philosophy is being followed here?', '["Marketing Concept", "Societal Marketing Concept", "Product Concept", "Production Concept"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q10'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'medium', 'A clothing brand uses a unique ‘Golden Eagle’ logo on all its products. This symbol helps customers identify the brand and legally prevents other companies from using a similar mark. What is this ‘Golden Eagle’ symbol called?', '["Trade Character", "Brand Mark", "Brand Name", "Generic Name"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q11');
  INSERT INTO _ebook_q VALUES
  ('Business Studies', 'Marketing Management', 'Planning', 'medium', 'When ‘Z-Tech’ introduced its new smartphone, it set a very low initial price to attract many customers and quickly gain market share. After establishing its brand, it planned to launch higher-priced models. This pricing strategy is known as:', '["Competitive Pricing", "Penetration Pricing", "Price Skimming", "Cost-plus Pricing"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q12'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'medium', 'Packaging performs several functions. If a milk carton is designed with a spout for easy pouring and a shape that fits neatly in a refrigerator door, which function of packaging is being highlighted?', '["Facilitating Use of the Product", "Product Promotion", "Product Identification", "Product Protection"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q13'),
  ('Business Studies', 'Marketing Management', 'Marketing', 'hard', '‘ Quick-Move’ is a company that manufactures high- end fragile glassware. To reduce the risk of breakage during transit and ensure the products reach the retailers exactly when needed to avoid stock-outs, the manager focuses heavily on choosing the right specialized containers and optimizing the frequency of shipments. Which two components of ‘Physical Distribution’ are being highlighted here?', '["Transportation and Inventory Control", "Warehousing and Order Processing", "Transportation and Warehousing", "Order Processing and Inventory Control"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q14'),
  ('Business Studies', 'Marketing Management', 'Marketing Management', 'hard', 'After a series of negative reviews regarding the sugar content in their drinks, ‘Health-First Beverages’ organized a national “Fitness Marathon” and donated all proceeds to a diabetes research foundation. They also invited prominent journalists to tour their factory to see their new “Zero-Sugar” processing line. Which specific tool of Public Relations is being utilized by inviting journalists to the factory?', '["Press Release", "Corporate Identity Building", "Press Relations/Lobbying", "Written Communication"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Marketing Management · Q15'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'Anil saw an advertisement for a “100% Organic Juice.” After purchasing and drinking it, he fell ill. Upon lab testing, it was found that the juice contained harmful synthetic preservatives not mentioned on the label. Anil decided to sue the company not just for the illness, but for the misleading information. Which two rights of Anil have been violated here?', '["Right to be Informed and Right to Safety", "Right to Choose and Right to be Heard", "Right to Consumer Education and Right to Safety", "Right to be Informed and Right to be Heard"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q1'),
  ('Business Studies', 'Consumer Protection', 'Marketing', 'hard', '‘Fresh Bakes’ , a local bakery, purchased 10 industrial- sized ovens worth ₹15 Lakh from a manufacturer to expand its commercial production of biscuits for sale in the city. Within a week, three ovens stopped working. The manufacturer refused to provide a warranty. Can ‘Fresh Bakes’ file a complaint as a “consumer” in a consumer forum?', '["Yes, because they paid for the goods.", "No, because the ovens were purchased for commercial purposes.", "Yes, because the amount is more than ₹10 Lakh.", "No, because they are a registered firm."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q2'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'Anika was overcharged by ₹50 on a bottle of juice that had an MRP of ₹150. When she complained to the store manager, he laughed and said, “It’s just 50 rupees, why are you making a big deal?” Anika decided to approach a consumer forum to claim a refund of the overcharged amount and compensation for the mental agony. Which right allows Anika to move the court for compensation and legal remedy?', '["Right to be Heard", "Right to seek Redressal", "Right to Choose", "Right to Safety"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q3'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'Sarthak purchased a brand-new high-speed ceiling fan. While installing it, he noticed there were no instructions regarding the electrical wiring or safety earthing. When he called the retailer to ask for a safety manual, the retailer told him, “It’s a simple fan, just connect the wires. We don’t provide manuals for such small items.” Which consumer right is being violated by the retailer in this case?', '["Right to Safety", "Right to be Informed", "Right to Choose", "Right to Consumer Education"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q4'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'A group of consumers filed a “Class Action” suit against a real estate developer for failing to give possession of flats. The total value of the dispute (total money paid by all consumers) amounts to ₹2.5 Crore. In which commission should this complaint be filed initially?', '["District Commission", "State Commission", "National Commission", "High Court"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q5'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'medium', 'The Central Consumer Protection Authority (CCPA) has the power to recall goods or withdraw services that are dangerous or unsafe. Who heads the “Inves- tigative Wing” of the CCPA?', '["The Chief Commissioner", "The Director-General", "The District Collector", "The Registrar of the National Commission"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q6'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'Reena purchased a high-end designer sofa worth ₹1.5 lakhs. Upon delivery, she discovered that the sofa’s frame was infested with termites. She filed a complaint before the District Commission. The Commission observed that the issue involves a simple defect and suggested that both parties attempt to resolve the dispute through mediation. Which of the following statements is correct under the Consumer Protection Act, 2019?', '["Mediation is compulsory before the Commission can proceed with the case.", "If the dispute is settled through mediation, no appeal can be filed against the settlement order.", "Mediation is allowed only at the National Commission level.", "Reena can file an appeal before the State Commission even after agreeing to the mediation settlement."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q7'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'Mr. Bajaj owns a large garment manufacturing factory. He purchased 50 industrial sewing machines for use in his factory. Within a week, 10 of these machines PRACTICE CORNER ---PAGE 225--- 224 CUET UG Business Studies developed technical defects and stopped functioning. He then filed a complaint before the District Commission, claiming protection as a “consumer.” Will Mr. Bajaj’s complaint be admitted under the Consumer Protection Act, 2019?', '["Yes, because the machines are defective.", "No, because goods purchased for commercial purposes are excluded from the definition of a ‘consumer.’", "Yes, because he is the end-user of the machines in his factory.", "No, because he should have approached the High Court directly."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q8'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'Aakash booked a flat with a prominent builder. The builder’s agreement stated: “In case of delay in payment by the buyer, an interest of 18% p.a. will be charged. However, if the builder delays the possession, the builder will only pay 2% p.a. interest to the buyer.” Aakash finds this highly one-sided. Under the 2019 Act, this scenario falls under which category, and which Commission has the power to declare such terms null and void?', '["Misleading Advertisement; District Commission", "Unfair Trade Practice; National Commission only", "Unfair Contract; State or National Commission", "Restrictive Trade Practice; Any District Forum"]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q9'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'hard', 'A wholesaler, “CheapDeals,” was caught selling counterfeit luxury watches that looked exactly like the original brand but used cheap, hazardous lead paint. No physical injury has occurred yet, but the fraud was discovered during a raid. According to the 2019 Act, what is the penalty for a person who manufactures or sells “Spurious Goods” (fake goods) that do not cause injury?', '["Imprisonment up to 1 year and a fine up to ₹3 Lakhs.", "Imprisonment up to 6 months and a fine up to ₹1 Lakh.", "Only a fine of ₹50,000.", "Imprisonment up to 2 years and a fine up to ₹5 Lakhs. Comprehension Consumer protection refers to the laws and regulations designed to ensure fair trade, competition, and accurate information in the marketplace. In a modern economy, the relationship between a buyer and a seller is often unequal; large corporations possess significant resources, while individual consumers may lack the technical knowledge to evaluate complex products. To bridge this gap, the Consumer Protection Act provides a lega"]'::jsonb, 0, 'Answer (a) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q10'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'medium', 'Which of the following is considered a “Responsibility” of a consumer rather than a “Right”?', '["Right to be informed about the ingredients of a product.", "Right to seek compensation for a defective mobile phone.", "Insisting on a cash memo or official receipt after a purchase.", "Access to a variety of products at competitive prices."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q1'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'medium', 'If a consumer is injured by a faulty electrical heater that did not meet safety standards, which right has been primarily violated?', '["Right to be Informed", "Right to Safety", "Right to Consumer Education", "Right to Choose"]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q2'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'medium', 'What is the primary purpose of the “Right to Seek Redressal”?', '["To allow consumers to advertise their own products.", "To ensure consumers can choose between different brands.", "To provide a legal path for compensation against unfair trade practices.", "To force companies to lower their prices during sales."]'::jsonb, 2, 'Answer (c) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q3'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'medium', 'Why is the “Right to be Informed” crucial in the modern marketplace?', '["It allows the government to tax products more easily.", "It helps consumers make rational choices based on product specifications and price. ---PAGE 226--- Consumer Protection 225", "It prevents new companies from entering the market.", "It requires consumers to memorize the history of the manufacturer."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q4'),
  ('Business Studies', 'Consumer Protection', 'Consumer Protection', 'medium', 'Quality certification marks like “ISI” or “ Agmark” are important because:', '["They make the packaging look more attractive.", "They indicate that the product has met specific safety and quality standards.", "They are required only for imported luxury goods.", "They guarantee that the product will never break or expire."]'::jsonb, 1, 'Answer (b) — from chapter answer key.', 'PW CUET ebook · Business Studies · Ch:Consumer Protection · Q5'),
  ('Business Studies', 'Staffing', 'Staffing', 'easy', 'Which of the following management functions is con- sidered a continuous process because new job posi - tions may be created and some employees may leave the organisation? (2025)', '["Planning", "Organising", "Staffing", "Controlling"]'::jsonb, 2, 'Correct option is (c) Staffing.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'easy', 'A widely used training method adopted by many in - stitutions involves providing trainees with exposure to a real work environment. This type of training is known as: (2025)', '["Vestibule Training", "Programmed Instruction", "Internship Training", "Case Study Method"]'::jsonb, 2, 'Correct option is (c) Internship Training.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'medium', 'Which of the following is not considered an aspect of staffing? (2025)', '["Training", "Authority", "Recruitment", "Selection"]'::jsonb, 1, 'Correct option is (b) Authority.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'medium', 'Which of the following statements represent the lim- itations of internal sources of recruitment? (2025)', '["It reduces the opportunity to bring in fresh talent.", "Employees are encouraged to perform better.", "Employees may avoid taking challenging tasks if they expect time-bound promotions.", "It may increase internal competition within the organisation. ---PAGE 101--- Choose the correct answer from the options given below: ( a) (A) and (D) only (b) (A) and (C) only ( c) (A), (B) and (D) only (d) (B), (C) and (D) only"]'::jsonb, 1, 'Correct option is (b) Employees are encouraged to perform better..', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing', 'medium', 'Arrange the following stages of the staffing process in the correct logical sequence: (2025)', '["Searching for prospective employees and encour- aging them to apply", "Issuing the appointment/offer letter", "Providing a brief introduction about the compa- ny", "Determining the number of personnel required for vacant positions Choose the correct answer from the options given below: ( a) (A), (B), (C), (D) (b) (A), (C), (B), (D) ( c) (D), (A), (B), (C) (d) (C), (B), (D), (A)"]'::jsonb, 2, 'Correct option is (c) Providing a brief introduction about the compa- ny.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'medium', 'Identify the correct sequence of steps involved in the selection process: (2024)', '["Selection decision", "Employment interview", "Selection tests", "Reference checking Choose the correct answer from the options given below: ( a) (A), (B), (C), (D) (b) (A), (C), (B), (D) ( c) (B), (A), (D), (C) (d) (C), (B), (D), (A)"]'::jsonb, 3, 'Correct option is (d) Reference checking Choose the correct answer from the options given below: ( a) (A), (B), (C), (D) (b) (A), (C), (B), (D) ( c) (B), (A), (D), (C) (d) (C), (B), (D), (A).', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'easy', 'A training method in which educational institutions and business organisations jointly conduct a pro - gramme is known as: (2024)', '["Vestibule training", "Apprenticeship training", "Internship training", "Job rotation"]'::jsonb, 2, 'Correct option is (c) Internship training.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'medium', 'Match the items given in List–I (Meaning) with the appropriate concepts in List–II (Name of the Concept): (2024) List–I List–II', '["Choosing the most suitable candidate (I) Selection", "Introducing the candidate to superiors and organisation (II) Orientation", "Acquiring job- related skills (III) Recruitment", "Searching for potential employees (IV) Training Choose the correct answer from the options given below: ( a) (A) – (I), (B) – (II), (C) – (III), (D) – (IV) ( b) (A) – (I), (B) – (III), (C) – (II), (D) – (IV) ( c) (A) – (I), (B) – (II), (C) – (IV), (D) – (III) ( d) (A) – (III), (B) – (IV), (C) – (I), (D) – (II)"]'::jsonb, 2, 'Correct option is (c) Acquiring job- related skills (III) Recruitment.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Human Resource Management', 'medium', 'Match the items given in List–I (Type of Test) with the appropriate descriptions in List–II: (2024) List–I List–II', '["Intelligence Test (I) Indicator of a person’s capacity to develop", "Aptitude Test (II) Provides clues about a person’s emotions, values, etc.", "Personality Test (III) Measures the existing skills of an individual", "Trade Test (IV) Indicates a person’s learning ability and decision-making ability Choose the correct answer from the options given below: ( a) (A) – (I), (B) – (II), (C) – (III), (D) – (IV) ( b) (A) – (IV), (B) – (I), (C) – (II), (D) – (III) ( c) (A) – (II), (B) – (III), (C) – (I), (D) – (IV) ( d) (A) – (I), (B) – (III), (C) – (IV), (D) – (II) Read the following passage carefully and answer the question that follows: (Question 10-14) (2023) Lenovo India decided to improve workforce diversity by "]'::jsonb, 1, 'Correct option is (b) Aptitude Test (II) Provides clues about a person’s emotions, values, etc..', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'medium', 'Which external source of recruitment is being used by Lenovo India in the above case?', '["Direct recruitment", "Casual callers", "Transfer", "Recommendations of employees ---PAGE 102---"]'::jsonb, 3, 'Correct option is (d) Recommendations of employees ---PAGE 102---.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'easy', 'Which internal source of recruitment refers to shifting an employee from one job position to another within the organisation?', '["Transfers", "Promotions", "Direct Recruitment", "Casual Callers"]'::jsonb, 0, 'Correct option is (a) Transfers.', 'PW CUET ebook · Business Studies · Staffing');
  INSERT INTO _ebook_q VALUES
  ('Business Studies', 'Staffing', 'Staffing Process', 'easy', 'Under which external source of recruitment do organ- isations maintain a record or database of unsolicited job applicants who apply on their own?', '["Employment Exchange", "Campus Recruitment", "Placement Agencies", "Casual Callers"]'::jsonb, 3, 'Correct option is (d) Casual Callers.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'easy', 'Which of the following is considered an internal source of recruitment?', '["Direct recruitment", "Advertisement", "Promotions", "Campus recruitment"]'::jsonb, 2, 'Correct option is (c) Promotions.', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Staffing', 'Staffing Process', 'medium', 'Which of the following is not considered an external source of recruitment?', '["Direct recruitment", "Advertisement", "Labour contractor", "Transfers - "]'::jsonb, 3, 'Correct option is (d) Transfers - .', 'PW CUET ebook · Business Studies · Staffing'),
  ('Business Studies', 'Controlling', 'Relationship between Planning and Controlling', 'easy', 'Controlling improves future ________ by providing information based on past experience. (2025)', '["Controlling", "Coordinating", "Communication", "Planning ---PAGE 146---"]'::jsonb, 1, 'Correct option is (b) Coordinating.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Relationship between Planning and Controlling', 'easy', 'Which of the following functions brings the management cycle back to the planning function? (2025)', '["Organising", "Coordinating", "Controlling", "Directing"]'::jsonb, 2, 'Correct option is (c) Controlling.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Controlling Process', 'easy', '________ helps in assessing whether the established standards are accurate. (2025)', '["Directing", "Organising", "Planning", "Controlling"]'::jsonb, 2, 'Correct option is (c) Planning.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Controlling Process', 'medium', 'Controlling is important for the following reasons: (2025)', '["It helps in judging the accuracy of standards", "It ensures creativity within the organisation", "It facilitates coordination in actions", "It promotes efficient use of resources Choose the correct answer from the options given below: ( a) (A), (B) and (D) only ( b) ( A), (B) and (C) only ( c) (A), (B), (C) and (D) ( d) ( A), (C) and (D) only"]'::jsonb, 2, 'Correct option is (c) It facilitates coordination in actions.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Controlling Process', 'medium', 'Arrange the following steps of the controlling process in the correct sequence: (2025)', '["Taking corrective action according to the decision taken", "Setting goals and establishing performance standards", "Measuring actual performance and comparing it with standards", "Identifying and analysing the causes of deviations Choose the correct answer from the options given below: ( a) (B), (C), (D), (A) (b) (A), (C), (B), (D) ( c) (B), (A), (D), (C) (d) (C), (B), (D), (A)"]'::jsonb, 0, 'Correct option is (a) Taking corrective action according to the decision taken.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Controlling', 'medium', 'Which of the following is not a limitation of Controlling? (2024)', '["It is a costly affair", "Resistance from employees", "Ensures order and discipline", "Little control over external factors"]'::jsonb, 2, 'Correct option is (c) Ensures order and discipline.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Controlling Process', 'medium', 'Identify the correct sequence of the Controlling process: (2024)', '["Analysing deviations", "Measurement of actual performance", "Setting up standards", "Comparison of actual performance with standards Choose the correct answer from the options given below: ( a) (A), (B), (C), (D) (b) (A), (C), (B), (D) ( c) (B), (A), (D), (C) (d) (C), (B), (D), (A)"]'::jsonb, 3, 'Correct option is (d) Comparison of actual performance with standards Choose the correct answer from the options given below: ( a) (A), (B), (C), (D) (b) (A), (C), (B), (D) ( c) (B), (A), (D), (C) (d) (C), (B), (D), (A).', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Techniques of Controlling', 'medium', '“Only a 5% increase in labour cost may be more troublesome than a 15% increase in postal charges.” (2024) Identify the concept highlighted in the above statement:', '["Deviation", "Critical point control", "Break-even analysis", "Critical path method"]'::jsonb, 1, 'Correct option is (b) Critical point control.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Techniques of Controlling', 'medium', 'Which of the following is not a traditional technique of controlling? (2023)', '["Statistical reports", "Break-even analysis", "PERT and CPM", "Budgetary control"]'::jsonb, 2, 'Correct option is (c) PERT and CPM.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Controlling Process', 'medium', 'Arrange the following steps of the controlling process in the correct logical sequence: (2023)', '["Setting performance standards", "Measurement of actual performance", "Analysing deviations", "Taking corrective action (E) Comparing actual performance with standards Choose the correct answer from the options given below: ( a) B, A, C, D, E (b) A, B, E, C, D ( c) A, E, B, C, D (d) C, A, D, B, E"]'::jsonb, 1, 'Correct option is (b) Measurement of actual performance.', 'PW CUET ebook · Business Studies · Controlling'),
  ('Business Studies', 'Controlling', 'Techniques of Controlling', 'medium', 'Which of the following are techniques of controlling? (2023) A. Ratio analysis B. PERT and CPM C. On-the-job training D. Management audit E. Off-the-job training Choose the correct answer from the options given below:', '["A, C, D and E only", "A, B and D only", "B, C, D and E only", "C, D and E only ---PAGE 147---"]'::jsonb, 1, 'Correct option is (b) A, B and D only.', 'PW CUET ebook · Business Studies · Controlling');
