-- ===========================================================================
-- SEED CUET Accountancy + Business Studies from PW ebook MCQs
-- Tags: exam_id=cuet, board=cuet, stream=NULL, chapter/topic/difficulty
-- Idempotent on unique (question, class_level, subject)
-- ===========================================================================

BEGIN;

DO $seed$
DECLARE
  _exam   uuid;
  _board  uuid;
  _class  uuid;
  _subj   uuid;
  _ch     uuid;
  _topic  uuid;
  _ins    int := 0;
  _skip   int := 0;
  r       RECORD;
BEGIN
  SELECT id INTO _exam FROM public.competitive_exams WHERE code = 'cuet' AND is_active;
  IF _exam IS NULL THEN
    RAISE EXCEPTION 'ROLLED BACK: no active cuet exam';
  END IF;

  SELECT id INTO _board FROM public.boards WHERE code = 'cuet';
  IF _board IS NULL THEN
    ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;
    SELECT id INTO _board FROM public.boards WHERE code = 'cuet';
  END IF;

  VALUES (_board, 'CUET', 12)
  ON CONFLICT (board_id, level) DO UPDATE SET label = EXCLUDED.label;
  SELECT id INTO _class FROM public.curriculum_classes WHERE board_id = _board AND level = 12;

  SELECT _class, n FROM unnest(ARRAY['Accountancy', 'Business Studies']) AS n
  ON CONFLICT (curriculum_class_id, name) DO NOTHING;

  CREATE TEMP TABLE _ebook_q (
    subject text, chapter text, topic text, difficulty text,
    question text, options jsonb, correct_index int, explanation text, source text
  ) ON COMMIT DROP;

  FOR r IN SELECT * FROM _ebook_q LOOP
    SELECT cs.id INTO _subj FROM public.curriculum_subjects cs
     WHERE cs.curriculum_class_id = _class AND cs.name = r.subject;
    IF _subj IS NULL THEN
      RAISE EXCEPTION 'ROLLED BACK: missing subject %', r.subject;
    END IF;

    VALUES (_subj, r.chapter, 1)
    ON CONFLICT (curriculum_subject_id, name) DO NOTHING;
    SELECT id INTO _ch FROM public.chapters
     WHERE curriculum_subject_id = _subj AND name = r.chapter;

    VALUES (_ch, r.topic)
    ON CONFLICT (chapter_id, name) DO NOTHING;
    SELECT id INTO _topic FROM public.topics WHERE chapter_id = _ch AND name = r.topic;

    IF EXISTS (
      SELECT 1 FROM public.question_bank qb
       WHERE qb.question = r.question
         AND qb.class_level IS NOT DISTINCT FROM 12
         AND qb.subject = r.subject
    ) THEN
      _skip := _skip + 1;
    ELSE
        subject, chapter, chapter_id, topic_id, difficulty, question, options,
        correct_index, explanation, board, stream, class_level, exam_id,
        is_approved, is_active, source_type, question_format, source, approved_at
      ) VALUES (
        r.subject, r.chapter, _ch, _topic, r.difficulty, r.question, r.options,
        r.correct_index, r.explanation, 'cuet', NULL, 12, _exam,
        true, true, 'ncert_aligned', 'mcq', r.source, now()
      );
      _ins := _ins + 1;
    END IF;
  END LOOP;

  RAISE NOTICE 'ebook seed: inserted %, skipped %', _ins, _skip;

  IF (SELECT count(*) FROM public.question_bank WHERE exam_id = _exam AND subject = 'Accountancy' AND is_approved) < 50 THEN
    RAISE EXCEPTION 'ROLLED BACK: Accountancy too thin after seed';
  END IF;
  IF (SELECT count(*) FROM public.question_bank WHERE exam_id = _exam AND subject = 'Business Studies' AND is_approved) < 30 THEN
    RAISE EXCEPTION 'ROLLED BACK: Business Studies too thin after seed';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.question_bank
     WHERE exam_id = _exam AND subject IN ('Accountancy','Business Studies') AND stream IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'ROLLED BACK: stream set on exam ebook rows';
  END IF;
END
$seed$;

COMMIT;
